window.BOOK={"key":"umda","app":"mutoon","lsk":"mutoon_umda_v1","title":"عمدة الأحكام","unitWord":"حديث","sub":"عمدة الأحكام من كلام خير الأنام · الحديث · الحافظ عبد الغني المقدسي (ت ٦٠٠هـ) · ٤١٤ حديثًا","source":"https://shamela.ws/book/538 (عمدة الأحكام، تحقيق عبد المحسن بن محمد القاسم، محققة على نسخ عليها إجازة المصنف؛ مشكولة بالكامل) ص ١١٠–٤١٨ · قوبل بـ: العمدة في الأحكام، تحقيق سمير الزهيري (مكتبة المعارف ١٤١٨هـ؛ OpenITI Sham19Y0017103) + متن العمدة داخل «إحكام الأحكام» لابن دقيق العيد (OpenITI Shamela0001665) — مقابلة آلية كلمة بكلمة، انظر umda-sources.md","note":"النص المشكول بالكامل من نشرة عبد المحسن القاسم المحققة على نسخ عليها إجازة المصنف، بترقيمها (٤١٤ حديثًا والروايات تابعة لأحاديثها). قوبل آليًّا كلمة بكلمة بنشرة سمير الزهيري وبمتن العمدة في «إحكام الأحكام» لابن دقيق العيد.","chapters":[{"id":"um1","title":"مقدمة المؤلف","units":[{"id":"um1_1","label":"مقدمة المؤلف · ١","segs":[["matn","بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ صَلَّى اللَّهُ عَلَى سَيِّدِنَا وَمَوْلَانَا مُحَمَّدٍ رَسُولِهِ، وَعَلَى آلِهِ وَسَلَّمَ تَسْلِيماً."]]},{"id":"um1_2","label":"مقدمة المؤلف · ٢","segs":[["matn","قَالَ الشَّيْخُ الحَافِظُ، الإِمَامُ، العَالِمُ، العَامِلُ، مُحْيِي السُّنَّةِ، قَامِعُ البِدْعَةِ، جَمَالُ الحُفَّاظِ؛ تَقِيُّ الدِّينِ أَبُو مُحَمَّدٍ، عَبْدُ الغَنِيِّ بْنُ عَبْدِ الوَاحِدِ بْنِ عَلِيِّ بْنِ سُرُورٍ المَقْدِسِيُّ - رَحْمَةُ اللَّهِ عَلَيْهِ وَرِضْوَانُهُ -:"]]},{"id":"um1_3","label":"مقدمة المؤلف · ٣","segs":[["matn","الحَمْدُ لِلَّهِ المَلِكِ الجَبَّارِ، الوَاحِدِ القَهَّارِ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، رَبُّ السَّمَوَاتِ وَالأَرْضِ وَمَا بَيْنَهُمَا العَزِيزُ الغَفَّارُ، وَصَلَّى اللَّهُ عَلَى النَّبِيِّ المُصْطَفَى المُخْتَارِ، وَعَلَى آلِهِ وَصَحْبِهِ الأَخْيَارِ."]]},{"id":"um1_4","label":"مقدمة المؤلف · ٤","segs":[["matn","أَمَّا بَعْدُ: فَإِنَّ بَعْضَ إِخْوَانِي سَأَلَنِي اخْتِصَارَ جُمْلَةٍ فِي أَحَادِيثِ الأَحْكَامِ، مِمَّا اتَّفَقَ عَلَيْهِ الإِمَامَانِ: أَبُو عَبْدِ اللَّهِ مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ البُخَارِيُّ، وَمُسْلِمُ بْنُ الحَجَّاجِ - رَحْمَةُ اللَّهِ عَلَيْهِمْ -، فَأَجَبْتُهُ إِلَى سُؤَالِهِ؛ رَجَاءَ المَنْفَعَةِ بِهِ."]]},{"id":"um1_5","label":"مقدمة المؤلف · ٥","segs":[["matn","وَأَسْأَلُ اللَّهَ أَنْ يَنْفَعَنَا بِهِ، وَمَنْ كَتَبَهُ، أَوْ سَمِعَهُ، أَوْ حَفِظَهُ، أَوْ نَظَرَ فِيهِ، وَأَنْ يَجْعَلَهُ خَالِصاً لِوَجْهِهِ الكَرِيمِ، مُوجِباً لِلْفَوْزِ لَدَيْهِ؛ فَإِنَّهُ حَسْبُنَا وَنِعْمَ الوَكِيلُ."]]}]},{"id":"um2","title":"كِتَابُ الطَّهَارَةِ","units":[{"id":"um2_1","label":"الحديث ١ · المقطع ١ من ٢","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «إِنَّمَا الأَعْمَالُ بِالنِّيَّةِ - وَفِي رِوَايَةٍ: بِالنِّيَّاتِ -، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى؛ فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ؛ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ،"]]},{"id":"um2_2","label":"الحديث ١ · المقطع ٢ من ٢","segs":[["matn","وَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَتَزَوَّجُهَا؛ فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ»."]]},{"id":"um2_3","label":"الحديث ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«لَا يَقْبَلُ اللَّهُ صَلَاةَ أَحَدِكُمْ إِذَا أَحْدَثَ حَتَّى يَتَوَضَّأَ»."]]},{"id":"um2_4","label":"الحديث ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِي، وَأَبِي هُرَيْرَةَ، وَعَائِشَةَ رَضِيَ اللَّهُ عَنْهُمْ قَالُوا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«وَيْلٌ لِلْأَعْقَابِ مِنَ النَّارِ»."]]},{"id":"um2_5","label":"الحديث ٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ مَاءً ثُمَّ لِيَنْتَثِرْ، وَمَنِ اسْتَجْمَرَ فَلْيُوتِرْ، وَإِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ؛ فَلْيَغْسِلْ يَدَيْهِ قَبْلَ أَنْ يُدْخِلَهُمَا فِي الإِنَاءِ ثَلَاثاً، فَإِنَّ أَحَدَكُمْ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ». وَفِي لَفْظٍ لِمُسْلِمٍ:"]]},{"id":"um2_6","label":"الحديث ٤ · المقطع ٢ من ٢","segs":[["matn","«فَلْيَسْتَنْشِقْ بِمَنْخِرَيْهِ مِنَ المَاءِ». وَفِي لَفْظٍ: «مَنْ تَوَضَّأَ فَلْيَسْتَنْشِقْ»."]]},{"id":"um2_7","label":"الحديث ٥","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا يَبُولَنَّ أَحَدُكُمْ فِي المَاءِ الدَّائِمِ الَّذِي لَا يَجْرِي، ثُمَّ يَغْتَسِلُ مِنْهُ». وَفِي رِوَايَةٍ لِمُسْلِمٍ: «لَا يَغْتَسِلْ أَحَدُكُمْ فِي المَاءِ الدَّائِمِ وَهُوَ جُنُبٌ»."]]},{"id":"um2_8","label":"الحديث ٦ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا شَرِبَ الكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعاً». وَلِمُسْلِمٍ: «أُولَاهُنَّ بِالتُّرَابِ». وَلَهُ فِي حَدِيثِ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"]]},{"id":"um2_9","label":"الحديث ٦ · المقطع ٢ من ٢","segs":[["matn","«إِذَا وَلَغَ الكَلْبُ فِي الإِنَاءِ فَاغْسِلُوهُ سَبْعاً، وَعَفِّرُوهُ الثَّامِنَةَ بِالتُّرَابِ»."]]},{"id":"um2_10","label":"الحديث ٧ · المقطع ١ من ٢","segs":[["rawi","عَنْ حُمْرَانَ - مَوْلَى عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ -:"],["matn","«أَنَّهُ رَأَى عُثْمَانَ دَعَا بِوَضُوءٍ، فَأَفْرَغَ عَلَى يَدَيْهِ مِنْ إِنَائِهِ، فَغَسَلَهُمَا ثَلَاثَ مَرَّاتٍ، ثُمَّ أَدْخَلَ يَمِينَهُ فِي الوَضُوءِ، ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ وَاسْتَنْثَرَ، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثاً، وَيَدَيْهِ إِلَى المِرْفَقَيْنِ ثَلَاثاً، ثُمَّ مَسَحَ بِرَأْسِهِ،"]]},{"id":"um2_11","label":"الحديث ٧ · المقطع ٢ من ٢","segs":[["matn","ثُمَّ غَسَلَ كِلْتَا رِجْلَيْهِ ثَلَاثاً، ثُمَّ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ نَحْوَ وُضُوئِي هَذَا، وَقَالَ: مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا، ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ؛ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ»."]]},{"id":"um2_12","label":"الحديث ٨ · المقطع ١ من ٤","segs":[["rawi","عَنْ عَمْرِو بْنِ يَحْيَى المَازِنِيِّ، عَنْ أَبِيهِ قَالَ:"],["matn","«شَهِدْتُ عَمْرَو بْنَ أَبِي حَسَنٍ سَأَلَ عَبْدَ اللَّهِ بْنَ زَيْدٍ رَضِيَ اللَّهُ عَنْهُ عَنْ وُضُوءِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَعَا بِتَوْرٍ مِنْ مَاءٍ، فَتَوَضَّأَ لَهُمْ وُضُوءَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um2_13","label":"الحديث ٨ · المقطع ٢ من ٤","segs":[["matn","فَأَكْفَأَ عَلَى يَدَيْهِ مِنَ التَّوْرِ، فَغَسَلَ يَدَيْهِ ثَلَاثاً، ثُمَّ أَدْخَلَ يَدَهُ فِي التَّوْرِ، فَمَضْمَضَ وَاسْتَنْشَقَ وَاسْتَنْثَرَ ثَلَاثاً بِثَلَاثِ غَرَفَاتٍ، ثُمَّ أَدْخَلَ يَدَهُ فَغَسَلَ وَجْهَهُ، ثُمَّ أَدْخَلَ يَدَهُ فَغَسَلَ يَدَيْهِ مَرَّتَيْنِ إِلَى المِرْفَقَيْنِ،"]]},{"id":"um2_14","label":"الحديث ٨ · المقطع ٣ من ٤","segs":[["matn","ثُمَّ أَدْخَلَ يَدَهُ فَمَسَحَ رَأْسَهُ، فَأَقْبَلَ بِهِمَا وَأَدْبَرَ مَرَّةً وَاحِدَةً، ثُمَّ غَسَلَ رِجْلَيْهِ». وَفِي رِوَايَةٍ: «بَدَأَ بِمُقَدَّمِ رَأْسِهِ، حَتَّى ذَهَبَ بِهِمَا إِلَى قَفَاهُ، ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى المَكَانِ الَّذِي بَدَأَ مِنْهُ». وَفِي رِوَايَةٍ:"]]},{"id":"um2_15","label":"الحديث ٨ · المقطع ٤ من ٤","segs":[["matn","«أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْرَجْنَا لَهُ مَاءً فِي تَوْرٍ مِنْ صُفْرٍ»."]]},{"id":"um2_16","label":"الحديث ٩","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْجِبُهُ التَّيَمُّنُ فِي تَنَعُّلِهِ، وَتَرَجُّلِهِ، وَطُهُورِهِ، وَفِي شَأْنِهِ كُلِّهِ»."]]},{"id":"um2_17","label":"الحديث ١٠ · المقطع ١ من ٣","segs":[["rawi","عَنْ نُعَيْمٍ المُجْمِرِ، عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:"],["matn","«إِنَّ أُمَّتِي يُدْعَوْنَ يَوْمَ القِيَامَةِ غُرّاً مُحَجَّلِينَ مِنْ آثَارِ الوُضُوءِ؛ فَمَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ غُرَّتَهُ فَلْيَفْعَلْ». وَفِي رِوَايَةٍ: «رَأَيْتُ أَبَا هُرَيْرَةَ يَتَوَضَّأُ، فَغَسَلَ وَجْهَهُ، وَيَدَيْهِ حَتَّى كَادَ يَبْلُغُ المَنْكِبَيْنِ،"]]},{"id":"um2_18","label":"الحديث ١٠ · المقطع ٢ من ٣","segs":[["matn","ثُمَّ غَسَلَ رِجْلَيْهِ حَتَّى رَفَعَ إِلَى السَّاقَيْنِ، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «إِنَّ أُمَّتِي يُدْعَوْنَ يَوْمَ القِيَامَةِ غُرّاً مُحَجَّلِينَ مِنْ أَثَرِ الوُضُوءِ؛ فَمَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ غُرَّتَهُ فَلْيَفْعَلْ»."]]},{"id":"um2_19","label":"الحديث ١٠ · المقطع ٣ من ٣","segs":[["matn","وَفِي لَفْظٍ لِمُسْلِمٍ: «سَمِعْتُ خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: تَبْلُغُ الحِلْيَةُ مِنَ المُؤْمِنِ حَيْثُ يَبْلُغُ الوُضُوءُ»."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um3","title":"بَابُ الِاسْتِطَابَةِ","units":[{"id":"um3_1","label":"الحديث ١١","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا دَخَلَ الخَلَاءَ قَالَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الخُبُثِ وَالخَبَائِثِ»."]]},{"id":"um3_2","label":"الحديث ١٢","segs":[["rawi","عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«إِذَا أَتَيْتُمُ الغَائِطَ؛ فَلَا تَسْتَقْبِلُوا القِبْلَةَ بِغَائِطٍ وَلَا بَوْلٍ، وَلَا تَسْتَدْبِرُوهَا، وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا. قَالَ أَبُو أَيُّوبَ: فَقَدِمْنَا الشَّامَ فَوَجَدْنَا مَرَاحِيضَ قَدْ بُنِيَتْ نَحْوَ الكَعْبَةِ؛ فَنَنْحَرِفُ عَنْهَا وَنَسْتَغْفِرُ اللَّهَ عَزَّ وَجَلَّ»."]]},{"id":"um3_3","label":"الحديث ١٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«رَقِيتُ يَوْماً عَلَى بَيْتِ حَفْصَةَ، فَرَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْضِي حَاجَتَهُ مُسْتَقْبِلَ الشَّامِ، مُسْتَدْبِرَ الكَعْبَةِ»."]]},{"id":"um3_4","label":"الحديث ١٤","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْخُلُ الخَلَاءَ، فَأَحْمِلُ أَنَا وَغُلَامٌ نَحْوِي إِدَاوَةً مِنْ مَاءٍ وَعَنَزَةً، فَيَسْتَنْجِي بِالمَاءِ»."]]},{"id":"um3_5","label":"الحديث ١٥","segs":[["rawi","عَنْ أَبِي قَتَادَةَ الحَارِثِ بْنِ رِبْعِيٍّ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا يُمْسِكَنَّ أَحَدُكُمْ ذَكَرَهُ بِيَمِينِهِ وَهُوَ يَبُولُ، وَلَا يَتَمَسَّحْ مِنَ الخَلَاءِ بِيَمِينِهِ، وَلَا يَتَنَفَّسْ فِي الإِنَاءِ»."]]},{"id":"um3_6","label":"الحديث ١٦ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَبْرَيْنِ، فَقَالَ: إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ؛ أَمَّا أَحَدُهُمَا: فَكَانَ لَا يَسْتَتِرُ مِنَ البَوْلِ، وَأَمَّا الآخَرُ: فَكَانَ يَمْشِي بِالنَّمِيمَةِ، فَأَخَذَ جَرِيدَةً رَطْبَةً فَشَقَّهَا نِصْفَيْنِ،"]]},{"id":"um3_7","label":"الحديث ١٦ · المقطع ٢ من ٢","segs":[["matn","فَغَرَزَ فِي كُلِّ قَبْرٍ وَاحِدَةً، فَقَالُوا: يَا رَسُولَ اللَّهِ! لِمَ فَعَلْتَ هَذَا؟ فَقَالَ: لَعَلَّهُ يُخَفَّفُ عَنْهُمَا مَا لَمْ يَيْبَسَا»."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um4","title":"بَابُ السِّوَاكِ","units":[{"id":"um4_1","label":"الحديث ١٧","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ»."]]},{"id":"um4_2","label":"الحديث ١٨","segs":[["rawi","عَنْ حُذَيْفَةَ بْنِ اليَمَانِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ اللَّيْلِ يَشُوصُ فَاهُ بِالسِّوَاكِ»."]]},{"id":"um4_3","label":"الحديث ١٩ · المقطع ١ من ٤","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«دَخَلَ عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا مُسْنِدَتُهُ إِلَى صَدْرِي، وَمَعَ عَبْدِ الرَّحْمَنِ سِوَاكٌ رَطْبٌ يَسْتَنُّ بِهِ، فَأَبَدَّهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَصَرَهُ،"]]},{"id":"um4_4","label":"الحديث ١٩ · المقطع ٢ من ٤","segs":[["matn","فَأَخَذْتُ السِّوَاكَ فَقَضِمْتُهُ، فَطَيَّبْتُهُ، ثُمَّ دَفَعْتُهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَنَّ بِهِ، فَمَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَنَّ اسْتِنَاناً أَحْسَنَ مِنْهُ،"]]},{"id":"um4_5","label":"الحديث ١٩ · المقطع ٣ من ٤","segs":[["matn","فَمَا عَدَا أَنْ فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَفَعَ يَدَهُ - أَوْ إِصْبَعَهُ - ثُمَّ قَالَ: فِي الرَّفِيقِ الأَعْلَى - ثَلَاثاً -، ثُمَّ قَضَى، وَكَانَتْ تَقُولُ: مَاتَ بَيْنَ حَاقِنَتِي وَذَاقِنَتِي». وَفِي لَفْظٍ:"]]},{"id":"um4_6","label":"الحديث ١٩ · المقطع ٤ من ٤","segs":[["matn","«فَرَأَيْتُهُ يَنْظُرُ إِلَيْهِ - وَعَرَفْتُ أَنَّهُ يُحِبُّ السِّوَاكَ -، فَقُلْتُ: آخُذُهُ لَكَ؟ فَأَشَارَ بِرَأْسِهِ: أَنْ نَعَمْ». لَفْظُ البُخَارِيِّ؛ وَلِمُسْلِمٍ: نَحْوُهُ."]]},{"id":"um4_7","label":"الحديث ٢٠","segs":[["rawi","عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَسْتَاكُ بِسِوَاكٍ، قَالَ: وَطَرَفُ السِّوَاكِ عَلَى لِسَانِهِ، يَقُولُ: أُعْ أُعْ وَالسِّوَاكُ فِي فِيهِ؛ كَأَنَّهُ يَتَهَوَّعُ»."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um5","title":"بَابُ المَسْحِ عَلَى الخُفَّيْنِ","units":[{"id":"um5_1","label":"الحديث ٢١","segs":[["rawi","عَنِ المُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كُنْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَأَهْوَيْتُ لِأَنْزِعَ خُفَّيْهِ، فَقَالَ: دَعْهُمَا، فَإِنِّي أَدْخَلْتُهُمَا طَاهِرَتَيْنِ؛ فَمَسَحَ عَلَيْهِمَا»."]]},{"id":"um5_2","label":"الحديث ٢٢","segs":[["rawi","عَنْ حُذَيْفَةَ بْنِ اليَمَانِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«كُنْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ فَبَالَ، وَتَوَضَّأَ، وَمَسَحَ عَلَى خُفَّيْهِ»؛ مُخْتَصَرٌ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um6","title":"بَابٌ فِي المَذْيِ وَغَيْرِهِ","units":[{"id":"um6_1","label":"الحديث ٢٣","segs":[["rawi","عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كُنْتُ رَجُلاً مَذَّاءً، فَاسْتَحْيَيْتُ أَنْ أَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمَكَانِ ابْنَتِهِ، فَأَمَرْتُ المِقْدَادَ ابْنَ الأَسْوَدِ فَسَأَلَهُ، فَقَالَ: يَغْسِلُ ذَكَرَهُ وَيَتَوَضَّأُ». وَلِلْبُخَارِيِّ: «اغْسِلْ ذَكَرَكَ وَتَوَضَّأْ». وَلِمُسْلِمٍ: «تَوَضَّأْ وَانْضِحْ فَرْجَكَ»."]]},{"id":"um6_2","label":"الحديث ٢٤","segs":[["rawi","عَنْ عَبَّادِ بْنِ تَمِيمٍ، عَنْ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ المَازِنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«شُكِيَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرَّجُلُ يُخَيَّلُ إِلَيْهِ أَنَّهُ يَجِدُ الشَّيْءَ فِي الصَّلَاةِ، قَالَ: لَا يَنْصَرِفْ حَتَّى يَسْمَعَ صَوْتاً، أَوْ يَجِدَ رِيحاً»."]]},{"id":"um6_3","label":"الحديث ٢٥","segs":[["rawi","عَنْ أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ الأَسَدِيَّةِ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّهَا أَتَتْ بِابْنٍ لَهَا صَغِيرٍ لَمْ يَأْكُلِ الطَّعَامَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَجْلَسَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجْرِهِ، فَبَالَ عَلَى ثَوْبِهِ، فَدَعَا بِمَاءٍ فَنَضَحَهُ وَلَمْ يَغْسِلْهُ»."]]},{"id":"um6_4","label":"الحديث ٢٦","segs":[["rawi","عَنْ عَائِشَةَ - أُمِّ المُؤْمِنِينَ - رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِصَبِيٍّ فَبَالَ عَلَى ثَوْبِهِ، فَدَعَا بِمَاءٍ فَأَتْبَعَهُ إِيَّاهُ». وَلِمُسْلِمٍ: «فَأَتْبَعَهُ بَوْلَهُ وَلَمْ يَغْسِلْهُ»."]]},{"id":"um6_5","label":"الحديث ٢٧","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«جَاءَ أَعْرَابِيٌّ فَبَالَ فِي طَائِفَةِ المَسْجِدِ، فَزَجَرَهُ النَّاسُ، فَنَهَاهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا قَضَى بَوْلَهُ أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَنُوبٍ مِنْ مَاءٍ فَأُهْرِيقَ عَلَيْهِ»."]]},{"id":"um6_6","label":"الحديث ٢٨","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «الفِطْرَةُ خَمْسٌ: الخِتَانُ، وَالِاسْتِحْدَادُ، وَقَصُّ الشَّارِبِ، وَتَقْلِيمُ الأَظْفَارِ، وَنَتْفُ الإِبْطِ»."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um7","title":"بَابُ الجَنَابَةِ","units":[{"id":"um7_1","label":"الحديث ٢٩","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقِيَهُ فِي بَعْضِ طُرُقِ المَدِينَةِ وَهُوَ جُنُبٌ، فَانْخَنَسْتُ مِنْهُ، فَذَهَبْتُ فَاغْتَسَلْتُ ثُمَّ جِئْتُ، فَقَالَ: أَيْنَ كُنْتَ يَا أَبَا هُرَيْرَةَ؟ قَالَ: كُنْتُ جُنُباً فَكَرِهْتُ أَنْ أُجَالِسَكَ وَأَنَا عَلَى غَيْرِ طَهَارَةٍ، فَقَالَ: سُبْحَانَ اللَّهِ! إِنَّ المُؤْمِنَ لَا يَنْجُسُ»."]]},{"id":"um7_2","label":"الحديث ٣٠ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اغْتَسَلَ مِنَ الجَنَابَةِ غَسَلَ يَدَيْهِ، وَتَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ، ثُمَّ اغْتَسَلَ، ثُمَّ يُخَلِّلُ بِيَدَيْهِ شَعَرَهُ، حَتَّى إِذَا ظَنَّ أَنَّهُ قَدْ أَرْوَى بَشَرَتَهُ؛ أَفَاضَ عَلَيْهِ المَاءَ ثَلَاثَ مَرَّاتٍ،"]]},{"id":"um7_3","label":"الحديث ٣٠ · المقطع ٢ من ٢","segs":[["matn","ثُمَّ غَسَلَ سَائِرَ جَسَدِهِ». وَكَانَتْ تَقُولُ: «كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ؛ نَغْتَرِفُ مِنْهُ جَمِيعاً»."]]},{"id":"um7_4","label":"الحديث ٣١ · المقطع ١ من ٢","segs":[["rawi","عَنْ مَيْمُونَةَ بِنْتِ الحَارِثِ رَضِيَ اللَّهُ عَنْهَا - زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَتْ:"],["matn","«وَضَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَضُوءَ الجَنَابَةِ، فَأَكْفَأَ بِيَمِينِهِ عَلَى يَسَارِهِ مَرَّتَيْنِ - أَوْ ثَلَاثاً -، ثُمَّ غَسَلَ فَرْجَهُ، ثُمَّ ضَرَبَ يَدَهُ بِالأَرْضِ - أَوِ الحَائِطِ - مَرَّتَيْنِ - أَوْ ثَلَاثاً -،"]]},{"id":"um7_5","label":"الحديث ٣١ · المقطع ٢ من ٢","segs":[["matn","ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ، وَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ، ثُمَّ أَفَاضَ عَلَى رَأْسِهِ المَاءَ، ثُمَّ غَسَلَ جَسَدَهُ، ثُمَّ تَنَحَّى فَغَسَلَ رِجْلَيْهِ، فَأَتَيْتُهُ بِخِرْقَةٍ فَلَمْ يُرِدْهَا؛ فَجَعَلَ يَنْفُضُ المَاءَ بِيَدِهِ»."]]},{"id":"um7_6","label":"الحديث ٣٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّ عُمَرَ بْنَ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«يَا رَسُولَ اللَّهِ! أَيَرْقُدُ أَحَدُنَا وَهُوَ جُنُبٌ؟ قَالَ: نَعَمْ؛ إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَرْقُدْ»."]]},{"id":"um7_7","label":"الحديث ٣٣ · المقطع ١ من ٢","segs":[["rawi","عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا - زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَتْ:"],["matn","«جَاءَتْ أُمُّ سُلَيْمٍ - امْرَأَةُ أَبِي طَلْحَةَ - إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ! إِنَّ اللَّهَ لَا يَسْتَحْيِي مِنَ الحَقِّ؛ هَلْ عَلَى المَرْأَةِ مِنْ غُسْلٍ إِذَا هِيَ احْتَلَمَتْ؟"]]},{"id":"um7_8","label":"الحديث ٣٣ · المقطع ٢ من ٢","segs":[["matn","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ؛ إِذَا رَأَتِ المَاءَ»."]]},{"id":"um7_9","label":"الحديث ٣٤","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كُنْتُ أَغْسِلُ الجَنَابَةَ مِنْ ثَوْبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَخْرُجُ إِلَى الصَّلَاةِ وَإِنَّ بُقَعَ المَاءِ فِي ثَوْبِهِ». وَفِي لَفْظٍ لِمُسْلِمٍ: «لَقَدْ كُنْتُ أَفْرُكُهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرْكاً، فَيُصَلِّي فِيهِ»."]]},{"id":"um7_10","label":"الحديث ٣٥","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا جَلَسَ بَيْنَ شُعَبِهَا الأَرْبَعِ، ثُمَّ جَهَدَهَا؛ فَقَدْ وَجَبَ الغَسْلُ». وَفِي لَفْظٍ: «وَإِنْ لَمْ يُنْزِلْ»."]]},{"id":"um7_11","label":"الحديث ٣٦ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي جَعْفَرٍ مُحَمَّدِ بْنِ عَلِيِّ بْنِ الحُسَيْنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ:"],["matn","«أَنَّهُ كَانَ هُوَ وَأَبُوهُ عِنْدَ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا - وَعِنْدَهُ قَوْمٌ - فَسَأَلُوهُ عَنِ الغَسْلِ؟ فَقَالَ: يَكْفِيكَ صَاعٌ، فَقَالَ رَجُلٌ: مَا يَكْفِينِي، فَقَالَ جَابِرٌ: كَانَ يَكْفِي مَنْ هُوَ أَوْفَى مِنْكَ شَعَراً،"]]},{"id":"um7_12","label":"الحديث ٣٦ · المقطع ٢ من ٣","segs":[["matn","وَخَيْرٌ مِنْكَ - يُرِيدُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -، ثُمَّ أَمَّنَا فِي ثَوْبٍ». وَفِي لَفْظٍ: «كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُفْرِغُ عَلَى رَأْسِهِ ثَلَاثاً». الرَّجُلُ الَّذِي قَالَ «مَا يَكْفِينِي»:"]]},{"id":"um7_13","label":"الحديث ٣٦ · المقطع ٣ من ٣","segs":[["matn","هُوَ الحَسَنُ بْنُ مُحَمَّدِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ؛ أَبُوهُ: ابْنُ الحَنَفِيَّةِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um8","title":"بَابُ التَّيَمُّمِ","units":[{"id":"um8_1","label":"الحديث ٣٧","segs":[["rawi","عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلاً مُعْتَزِلاً لَمْ يُصَلِّ فِي القَوْمِ، فَقَالَ: يَا فُلَانُ! مَا مَنَعَكَ أَنْ تُصَلِّيَ فِي القَوْمِ؟ فَقَالَ: يَا رَسُولَ اللَّهِ! أَصَابَتْنِي جَنَابَةٌ وَلَا مَاءَ؛ قَالَ: عَلَيْكَ بِالصَّعِيدِ؛ فَإِنَّهُ يَكْفِيكَ»."]]},{"id":"um8_2","label":"الحديث ٣٨ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَمَّارِ بْنِ يَاسِرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَاجَةٍ فَأَجْنَبْتُ، فَلَمْ أَجِدِ المَاءَ، فَتَمَرَّغْتُ فِي الصَّعِيدِ كَمَا تَمَرَّغُ الدَّابَّةُ، ثُمَّ أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ:"]]},{"id":"um8_3","label":"الحديث ٣٨ · المقطع ٢ من ٢","segs":[["matn","إِنَّمَا يَكْفِيكَ أَنْ تَقُولَ بِيَدَيْكَ هَكَذَا، ثُمَّ ضَرَبَ بِيَدَيْهِ الأَرْضَ ضَرْبَةً وَاحِدَةً، ثُمَّ مَسَحَ الشِّمَالَ عَلَى اليَمِينِ، وَظَاهِرَ كَفَّيْهِ وَوَجْهَهُ»."]]},{"id":"um8_4","label":"الحديث ٣٩ · المقطع ١ من ٢","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«أُعْطِيتُ خَمْساً لَمْ يُعْطَهُنَّ أَحَدٌ مِنَ الأَنْبِيَاءِ قَبْلِي: نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَجُعِلَتْ لِيَ الأَرْضُ مَسْجِداً وَطَهُوراً؛ فَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلَاةُ فَلْيُصَلِّ، وَأُحِلَّتْ لِيَ الغَنَائِمُ، وَلَمْ تَحِلَّ لِأَحَدٍ قَبْلِي، وَأُعْطِيتُ الشَّفَاعَةَ،"]]},{"id":"um8_5","label":"الحديث ٣٩ · المقطع ٢ من ٢","segs":[["matn","وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَى النَّاسِ عَامَّةً»."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um9","title":"بَابُ الحَيْضِ","units":[{"id":"um9_1","label":"الحديث ٤٠ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ فَاطِمَةَ بِنْتَ أَبِي حُبَيْشٍ سَأَلَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: إِنِّي أُسْتَحَاضُ فَلَا أَطْهُرُ، أَفَأَدَعُ الصَّلَاةَ؟ فَقَالَ: لَا؛ إِنَّ ذَلِكِ عِرْقٌ، وَلَكِنْ دَعِي الصَّلَاةَ قَدْرَ الأَيَّامِ الَّتِي كُنْتِ تَحِيضِينَ فِيهَا، ثُمَّ اغْتَسِلِي وَصَلِّي»."]]},{"id":"um9_2","label":"الحديث ٤٠ · المقطع ٢ من ٢","segs":[["matn","وَفِي رِوَايَةٍ: «وَلَيْسَ بِالحَيْضَةِ؛ فَإِذَا أَقْبَلَتِ الحَيْضَةُ: فَاتْرُكِي الصَّلَاةَ، فَإِذَا ذَهَبَ قَدْرُهَا: فَاغْسِلِي عَنْكِ الدَّمَ وَصَلِّي»."]]},{"id":"um9_3","label":"الحديث ٤١","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ أُمَّ حَبِيبَةَ رَضِيَ اللَّهُ عَنْهَا اسْتُحِيضَتْ سَبْعَ سِنِينَ، فَسَأَلَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكِ؛ فَأَمَرَهَا أَنْ تَغْتَسِلَ؛ فَكَانَتْ تَغْتَسِلُ لِكُلِّ صَلَاةٍ»."]]},{"id":"um9_4","label":"الحديث ٤٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كُنْتُ أَغْتَسِلُ أَنَا وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ؛ كِلَانَا جُنُبٌ، وَكَانَ يَأْمُرُنِي فَأَتَّزِرُ، فَيُبَاشِرُنِي وَأَنَا حَائِضٌ، وَكَانَ يُخْرِجُ رَأْسَهُ إِلَيَّ وَهُوَ مُعْتَكِفٌ فَأَغْسِلُهُ وَأَنَا حَائِضٌ»."]]},{"id":"um9_5","label":"الحديث ٤٣","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَّكِئُ فِي حَجْرِي وَأَنَا حَائِضٌ؛ فَيَقْرَأُ القُرْآنَ»."]]},{"id":"um9_6","label":"الحديث ٤٤","segs":[["rawi","عَنْ مُعَاذَةَ قَالَتْ:"],["matn","«سَأَلْتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فَقُلْتُ: مَا بَالُ الحَائِضِ تَقْضِي الصَّوْمَ وَلَا تَقْضِي الصَّلَاةَ؟ فَقَالَتْ: أَحَرُورِيَّةٌ أَنْتِ؟ قُلْتُ: لَسْتُ بِحَرُورِيَّةٍ، وَلَكِنِّي أَسْأَلُ، قَالَتْ: كَانَ يُصِيبُنَا ذَلِكِ فَنُؤْمَرُ بِقَضَاءِ الصَّوْمِ، وَلَا نُؤْمَرُ بِقَضَاءِ الصَّلَاةِ»."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um10","title":"بَابُ المَوَاقِيتِ","units":[{"id":"um10_1","label":"الحديث ٤٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي عَمْرٍو الشَّيْبَانِيِّ - وَاسْمُهُ: سَعْدُ بْنُ إِيَاسٍ - قَالَ: حَدَّثَنِي صَاحِبُ هَذِهِ الدَّارِ - وَأَشَارَ بِيَدِهِ إِلَى دَارِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ - قَالَ:"],["matn","«سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ العَمَلِ أَحَبُّ إِلَى اللَّهِ؟ قَالَ: الصَّلَاةُ عَلَى وَقْتِهَا، قُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: بِرُّ الوَالِدَيْنِ، قُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: الجِهَادُ فِي سَبِيلِ اللَّهِ، قَالَ:"]]},{"id":"um10_2","label":"الحديث ٤٥ · المقطع ٢ من ٢","segs":[["matn","حَدَّثَنِي بِهِنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَوِ اسْتَزَدْتُهُ لَزَادَنِي»."]]},{"id":"um10_3","label":"الحديث ٤٦","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«لَقَدْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الفَجْرَ، فَيَشْهَدُ مَعَهُ نِسَاءٌ مِنَ المُؤْمِنَاتِ مُتَلَفِّعَاتٍ بِمُرُوطِهِنَّ، ثُمَّ يَرْجِعْنَ إِلَى بُيُوتِهِنَّ مَا يَعْرِفُهُنَّ أَحَدٌ مِنَ الغَلَسِ»."]]},{"id":"um10_4","label":"الحديث ٤٧","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الظُّهْرَ بِالهَاجِرَةِ، وَالعَصْرَ وَالشَّمْسُ نَقِيَّةٌ، وَالمَغْرِبَ إِذَا وَجَبَتْ، وَالعِشَاءَ أَحْيَاناً وَأَحْيَاناً؛ إِذَا رَآهُمُ اجْتَمَعُوا عَجَّلَ، وَإِذَا رَآهُمْ أَبْطَؤُوا أَخَّرَ، وَالصُّبْحَ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهَا بِغَلَسٍ»."]]},{"id":"um10_5","label":"الحديث ٤٨ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي المِنْهَالِ سَيَّارِ بْنِ سَلَامَةَ قَالَ:"],["matn","«دَخَلْتُ أَنَا وَأَبِي عَلَى أَبِي بَرْزَةَ الأَسْلَمِيِّ رَضِيَ اللَّهُ عَنْهُ، فَقَالَ لَهُ أَبِي: كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي المَكْتُوبَةَ؟ فَقَالَ: كَانَ يُصَلِّي الهَجِيرَ - الَّتِي تَدْعُونَهَا الأُولَى - حِينَ تَدْحَضُ الشَّمْسُ،"]]},{"id":"um10_6","label":"الحديث ٤٨ · المقطع ٢ من ٣","segs":[["matn","وَيُصَلِّي العَصْرَ، ثُمَّ يَرْجِعُ أَحَدُنَا إِلَى رَحْلِهِ فِي أَقْصَى المَدِينَةِ وَالشَّمْسُ حَيَّةٌ، وَنَسِيتُ مَا قَالَ فِي المَغْرِبِ، وَكَانَ يَسْتَحِبُّ أَنْ يُؤَخِّرَ مِنَ العِشَاءِ - الَّتِي تَدْعُونَهَا العَتَمَةَ -، وَكَانَ يَكْرَهُ النَّوْمَ قَبْلَهَا وَالحَدِيثَ بَعْدَهَا،"]]},{"id":"um10_7","label":"الحديث ٤٨ · المقطع ٣ من ٣","segs":[["matn","وَكَانَ يَنْفَتِلُ مِنْ صَلَاةِ الغَدَاةِ حِينَ يَعْرِفُ الرَّجُلُ جَلِيسَهُ، وَيَقْرَأُ بِالسِّتِّينَ إِلَى المِئَةِ»."]]},{"id":"um10_8","label":"الحديث ٤٩ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ - يَوْمَ الخَنْدَقِ -:"],["matn","«مَلَأَ اللَّهُ قُبُورَهُمْ وَبُيُوتَهُمْ نَاراً؛ كَمَا شَغَلُونَا عَنِ الصَّلَاةِ الوُسْطَى حَتَّى غَابَتِ الشَّمْسُ». وَفِي لَفْظٍ لِمُسْلِمٍ: «شَغَلُونَا عَنِ الصَّلَاةِ الوُسْطَى - صَلَاةِ العَصْرِ - ثُمَّ صَلَّاهَا بَيْنَ المَغْرِبِ وَالعِشَاءِ»."]]},{"id":"um10_9","label":"الحديث ٤٩ · المقطع ٢ من ٣","segs":[["matn","وَلَهُ عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: «حَبَسَ المُشْرِكُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صَلَاةِ العَصْرِ حَتَّى احْمَرَّتِ الشَّمْسُ أَوِ اصْفَرَّتْ؛ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um10_10","label":"الحديث ٤٩ · المقطع ٣ من ٣","segs":[["matn","شَغَلُونَا عَنِ الصَّلَاةِ الوُسْطَى - صَلَاةِ العَصْرِ -؛ مَلَأَ اللَّهُ أَجْوَافَهُمْ وَقُبُورَهُمْ نَاراً - أَوْ حَشَا اللَّهُ أَجْوَافَهُمْ وَقُبُورَهُمْ نَاراً -»."]]},{"id":"um10_11","label":"الحديث ٥٠ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أَعْتَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالعِشَاءِ، فَخَرَجَ عُمَرُ فَقَالَ: الصَّلَاةَ يَا رَسُولَ اللَّهِ! رَقَدَ النِّسَاءُ وَالصِّبْيَانُ، فَخَرَجَ وَرَأْسُهُ يَقْطُرُ يَقُولُ:"]]},{"id":"um10_12","label":"الحديث ٥٠ · المقطع ٢ من ٢","segs":[["matn","لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي - أَوْ عَلَى النَّاسِ - لَأَمَرْتُهُمْ بِهَذِهِ الصَّلَاةِ هَذِهِ السَّاعَةَ»."]]},{"id":"um10_13","label":"الحديث ٥١","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا أُقِيمَتِ الصَّلَاةُ وَحَضَرَ العَشَاءُ؛ فَابْدَؤُوا بِالعَشَاءِ». وَعَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: نَحْوُهُ. وَلِمُسْلِمٍ عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «لَا صَلَاةَ بِحَضْرَةِ طَعَامٍ، وَلَا وَهُوَ يُدَافِعُهُ الأَخْبَثَانِ»."]]},{"id":"um10_14","label":"الحديث ٥٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«شَهِدَ عِنْدِي رِجَالٌ مَرْضِيُّونَ - وَأَرْضَاهُمْ عِنْدِي عُمَرُ - أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الصَّلَاةِ بَعْدَ الصُّبْحِ حَتَّى تُشْرِقَ الشَّمْسُ، وَبَعْدَ العَصْرِ حَتَّى تَغْرُبَ»."]]},{"id":"um10_15","label":"الحديث ٥٣ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا صَلَاةَ بَعْدَ الصُّبْحِ حَتَّى تَرْتَفِعَ الشَّمْسُ، وَلَا صَلَاةَ بَعْدَ العَصْرِ حَتَّى تَغِيبَ الشَّمْسُ». وَفِي البَابِ: عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، وَعَبْدِ اللَّهِ بْنِ مَسْعُودٍ، وَعَبْدِ اللَّهِ بْنِ عَمُرَ بْنِ الخَطَّابِ،"]]},{"id":"um10_16","label":"الحديث ٥٣ · المقطع ٢ من ٣","segs":[["matn","وَعَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِي، وَأَبِي هُرَيْرَةَ، وَسَمُرَةَ بْنِ جُنْدُبٍ، وَسَلَمَةَ ابْنِ الأَكْوَعِ، وَزَيْدِ بْنِ ثَابِتٍ، وَمُعَاذِ ابْنِ عَفْرَاءَ، وَكَعْبِ بْنِ مُرَّةَ، وَأَبِي أُمَامَةَ البَاهِلِيِّ، وَعَمْرِو بْنِ عَبَسَةَ السُّلَمِيِّ، وَعَائِشَةَ رَضِيَ اللَّهُ عَنْهُمْ،"]]},{"id":"um10_17","label":"الحديث ٥٣ · المقطع ٣ من ٣","segs":[["matn","وَالصُّنَابِحِيِّ - وَلَمْ يَسْمَعْ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -."]]},{"id":"um10_18","label":"الحديث ٥٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ عُمَرَ بْنَ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ جَاءَ يَوْمَ الخَنْدَقِ بَعْدَمَا غَرَبَتِ الشَّمْسُ، فَجَعَلَ يَسُبُّ كُفَّارَ قُرَيْشٍ، وَيَقُولُ: يَا رَسُولَ اللَّهِ! مَا كِدْتُ أُصَلِّي العَصْرَ حَتَّى كَادَتِ الشَّمْسُ تَغْرُبُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um10_19","label":"الحديث ٥٤ · المقطع ٢ من ٢","segs":[["matn","وَاللَّهِ مَا صَلَّيْتُهَا! قَالَ: فَقُمْنَا إِلَى بُطْحَانَ، فَتَوَضَّأَ لِلصَّلَاةِ وَتَوَضَّأْنَا لَهَا، فَصَلَّى العَصْرَ بَعْدَمَا غَرَبَتِ الشَّمْسُ، ثُمَّ صَلَّى بَعْدَهَا المَغْرِبَ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um11","title":"بَابُ فَضْلِ صَلَاةِ الجَمَاعَةِ وَوُجُوبِهَا","units":[{"id":"um11_1","label":"الحديث ٥٥","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«صَلَاةُ الجَمَاعَةِ أَفْضَلُ مِنْ صَلَاةِ الفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً»."]]},{"id":"um11_2","label":"الحديث ٥٦ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «صَلَاةُ الرَّجُلِ فِي الجَمَاعَةِ تُضَعَّفُ عَلَى صَلَاتِهِ فِي بَيْتِهِ وَفِي سُوقِهِ خَمْساً وَعِشْرِينَ ضِعْفاً؛ وَذَلِكَ أَنَّهُ: إِذَا تَوَضَّأَ فَأَحْسَنَ الوُضُوءَ، ثُمَّ خَرَجَ إِلَى المَسْجِدِ لَا يُخْرِجُهُ إِلَّا الصَّلَاةُ؛"]]},{"id":"um11_3","label":"الحديث ٥٦ · المقطع ٢ من ٢","segs":[["matn","لَمْ يَخْطُ خَطْوَةً إِلَّا رُفِعَتْ لَهُ بِهَا دَرَجَةٌ، وَحُطَّ عَنْهُ بِهَا خَطِيئَةٌ؛ فَإِذَا صَلَّى لَمْ تَزَلِ المَلَائِكَةُ تُصَلِّي عَلَيْهِ مَا دَامَ فِي مُصَلَّاهُ: اللَّهُمَّ صَلِّ عَلَيْهِ! اللَّهُمَّ ارْحَمْهُ! وَلَا يَزَالُ فِي صَلَاةٍ مَا انْتَظَرَ الصَّلَاةَ»."]]},{"id":"um11_4","label":"الحديث ٥٧ · المقطع ١ من ٢","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«أَثْقَلُ الصَّلَاةِ عَلَى المُنَافِقِينَ: صَلَاةُ العِشَاءِ، وَصَلَاةُ الفَجْرِ، وَلَوْ يَعْلَمُونَ مَا فِيهِمَا لَأَتَوْهُمَا وَلَوْ حَبْواً، وَلَقَدْ هَمَمْتُ أَنْ آمُرَ بِالصَّلَاةِ فَتُقَامَ، ثُمَّ آمُرَ رَجُلاً فَيُصَلِّيَ بِالنَّاسِ،"]]},{"id":"um11_5","label":"الحديث ٥٧ · المقطع ٢ من ٢","segs":[["matn","ثُمَّ أَنْطَلِقَ مَعِي بِرِجَالٍ مَعَهُمْ حُزَمٌ مِنْ حَطَبٍ إِلَى قَوْمٍ لَا يَشْهَدُونَ الصَّلَاةَ فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ بِالنَّارِ»."]]},{"id":"um11_6","label":"الحديث ٥٨ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا اسْتَأْذَنَتْ أَحَدَكُمُ امْرَأَتُهُ إِلَى المَسْجِدِ فَلَا يَمْنَعْهَا، قَالَ: فَقَالَ بِلَالُ بْنُ عَبْدِ اللَّهِ: وَاللَّهِ لَنَمْنَعُهُنَّ، قَالَ: فَأَقْبَلَ عَلَيْهِ عَبْدُ اللَّهِ فَسَبَّهُ سَبّاً سَيِّئاً مَا سَمِعْتُهُ سَبَّهُ مِثْلَهُ قَطُّ، وَقَالَ:"]]},{"id":"um11_7","label":"الحديث ٥٨ · المقطع ٢ من ٢","segs":[["matn","أُخْبِرُكَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَتَقُولُ: وَاللَّهِ لَنَمْنَعُهُنَّ؟!». وَفِي لَفْظٍ: «لَا تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ»."]]},{"id":"um11_8","label":"الحديث ٥٩ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ قَبْلَ الظُّهْرِ، وَرَكْعَتَيْنِ بَعْدَ الظُّهْرِ، وَرَكْعَتَيْنِ بَعْدَ الجُمُعَةِ، وَرَكْعَتَيْنِ بَعْدَ المَغْرِبِ، وَرَكْعَتَيْنِ بَعْدَ العِشَاءِ». وَفِي لَفْظٍ: «فَأَمَّا المَغْرِبُ وَالعِشَاءُ وَالجُمُعَةُ: فَفِي بَيْتِهِ». وَفِي لَفْظٍ:"]]},{"id":"um11_9","label":"الحديث ٥٩ · المقطع ٢ من ٢","segs":[["matn","«أَنَّ ابْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: حَدَّثَتْنِي حَفْصَةُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي سَجْدَتَيْنِ خَفِيفَتَيْنِ بَعْدَمَا يَطْلُعُ الفَجْرُ، وَكَانَتْ سَاعَةً لَا أَدْخُلُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا»."]]},{"id":"um11_10","label":"الحديث ٦٠","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«لَمْ يَكُنِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى شَيْءٍ مِنَ النَّوَافِلِ أَشَدَّ تَعَاهُداً مِنْهُ عَلَى رَكْعَتَيِ الفَجْرِ». وَفِي لَفْظٍ لِمُسْلِمٍ: «رَكْعَتَا الفَجْرِ؛ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um12","title":"بَابُ الأَذَانِ","units":[{"id":"um12_1","label":"الحديث ٦١","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«أُمِرَ بِلَالٌ أَنْ يَشْفَعَ الأَذَانَ، وَيُوتِرَ الإِقَامَةَ»."]]},{"id":"um12_2","label":"الحديث ٦٢ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي جُحَيْفَةَ وَهْبِ بْنِ عَبْدِ اللَّهِ السُّوَائِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي قُبَّةٍ لَهُ حَمْرَاءَ مِنْ أَدَمٍ؛ قَالَ: فَخَرَجَ بِلَالٌ بِوَضُوءٍ، فَمِنْ نَاضِحٍ وَنَائِلٍ، قَالَ:"]]},{"id":"um12_3","label":"الحديث ٦٢ · المقطع ٢ من ٣","segs":[["matn","فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِ حُلَّةٌ حَمْرَاءُ - كَأَنِّي أَنْظُرُ إِلَى بَيَاضِ سَاقَيْهِ -، قَالَ: فَتَوَضَّأَ وَأَذَّنَ بِلَالٌ، قَالَ: فَجَعَلْتُ أَتَتَبَّعُ فَاهُ هَاهُنَا وَهَاهُنَا، يَقُولُ - يَمِيناً وَشِمَالاً -: حَيَّ عَلَى الصَّلَاةِ!"]]},{"id":"um12_4","label":"الحديث ٦٢ · المقطع ٣ من ٣","segs":[["matn","حَيَّ عَلَى الفَلَاحِ! ثُمَّ رُكِزَتْ لَهُ عَنَزَةٌ، فَتَقَدَّمَ وَصَلَّى الظُّهْرَ رَكْعَتَيْنِ، ثُمَّ لَمْ يَزَلْ يُصَلِّي رَكْعَتَيْنِ حَتَّى رَجَعَ إِلَى المَدِينَةِ»."]]},{"id":"um12_5","label":"الحديث ٦٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:"],["matn","«إِنَّ بِلَالاً يُؤَذِّنُ بِلَيْلٍ؛ فَكُلُوا وَاشْرَبُوا حَتَّى تَسْمَعُوا أَذَانَ ابْنِ أُمِّ مَكْتُومٍ»."]]},{"id":"um12_6","label":"الحديث ٦٤","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِذَا سَمِعْتُمُ المُؤَذِّنَ؛ فَقُولُوا مِثْلَ مَا يَقُولُ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um13","title":"بَابُ اسْتِقْبَالِ القِبْلَةِ","units":[{"id":"um13_1","label":"الحديث ٦٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُسَبِّحُ عَلَى ظَهْرِ رَاحِلَتِهِ حَيْثُ كَانَ وَجْهُهُ، يُومِئُ بِرَأْسِهِ، وَكَانَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَفْعَلُهُ». وَفِي رِوَايَةٍ: «كَانَ يُوتِرُ عَلَى بَعِيرِهِ». وَلِمُسْلِمٍ:"]]},{"id":"um13_2","label":"الحديث ٦٥ · المقطع ٢ من ٢","segs":[["matn","«غَيْرَ أَنَّهُ لَا يُصَلِّي عَلَيْهَا المَكْتُوبَةَ». وَلِلْبُخَارِيِّ: «إِلَّا الفَرَائِضَ»."]]},{"id":"um13_3","label":"الحديث ٦٦","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«بَيْنَمَا النَّاسُ بِقُبَاءٍ فِي صَلَاةِ الصُّبْحِ إِذْ جَاءَهُمْ آتٍ فَقَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أُنْزِلَ عَلَيْهِ اللَّيْلَةَ قُرْآنٌ، وَقَدْ أُمِرَ أَنْ يَسْتَقْبِلَ القِبْلَةَ فَاسْتَقْبِلُوهَا، وَكَانَتْ وُجُوهُهُمْ إِلَى الشَّامِ فَاسْتَدَارُوا إِلَى الكَعْبَةِ»."]]},{"id":"um13_4","label":"الحديث ٦٧ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَنَسِ بْنِ سِيرِينَ قَالَ:"],["matn","«اسْتَقْبَلْنَا أَنَساً رَضِيَ اللَّهُ عَنْهُ حِينَ قَدِمَ مِنَ الشَّامِ، فَلَقِينَاهُ بِعَيْنِ التَّمْرِ، فَرَأَيْتُهُ يُصَلِّي عَلَى حِمَارٍ وَوَجْهُهُ مِنْ ذَا الجَانِبِ - يَعْنِي: عَنْ يَسَارِ القِبْلَةِ -، فَقُلْتُ: رَأَيْتُكَ تُصَلِّي لِغَيْرِ القِبْلَةِ! فَقَالَ:"]]},{"id":"um13_5","label":"الحديث ٦٧ · المقطع ٢ من ٢","segs":[["matn","لَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ لَمْ أَفْعَلْهُ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um14","title":"بَابُ الصُّفُوفِ","units":[{"id":"um14_1","label":"الحديث ٦٨","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «سَوُّوا صُفُوفَكُمْ؛ فَإِنَّ تَسْوِيَةَ الصَّفِّ مِنْ تَمَامِ الصَّلَاةِ»."]]},{"id":"um14_2","label":"الحديث ٦٩ · المقطع ١ من ٢","segs":[["rawi","عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"],["matn","«لَتُسَوُّنَّ صُفُوفَكُمْ أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُمْ». وَلِمُسْلِمٍ: «كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسَوِّي صُفُوفَنَا؛ حَتَّى كَأَنَّمَا يُسَوِّي بِهَا القِدَاحَ، حَتَّى رَأَى أَنْ قَدْ عَقَلْنَا، ثُمَّ خَرَجَ يَوْماً، فَقَامَ حَتَّى كَادَ يُكَبِّرُ،"]]},{"id":"um14_3","label":"الحديث ٦٩ · المقطع ٢ من ٢","segs":[["matn","فَرَأَى رَجُلاً بَادِياً صَدْرُهُ، فَقَالَ: عِبَادَ اللَّهِ! لَتُسَوُّنَّ صُفُوفَكُمْ، أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُمْ»."]]},{"id":"um14_4","label":"الحديث ٧٠ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ جَدَّتَهُ مُلَيْكَةَ دَعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِطَعَامٍ صَنَعَتْهُ، فَأَكَلَ مِنْهُ، ثُمَّ قَالَ: قُومُوا فَلِأُصَلِّ لَكُمْ، قَالَ أَنَسٌ: فَقُمْتُ إِلَى حَصِيرٍ لَنَا قَدِ اسْوَدَّ مِنْ طُولِ مَا لُبِسَ، فَنَضَحْتُهُ بِمَاءٍ،"]]},{"id":"um14_5","label":"الحديث ٧٠ · المقطع ٢ من ٢","segs":[["matn","فَقَامَ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَصَفَفْتُ أَنَا وَاليَتِيمُ وَرَاءَهُ، وَالعَجُوزُ مِنْ وَرَائِنَا، فَصَلَّى لَنَا رَكْعَتَيْنِ، ثُمَّ انْصَرَفَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ». وَلِمُسْلِمٍ: «أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِهِ وَبِأُمِّهِ، فَأَقَامَنِي عَنْ يَمِينِهِ، وَأَقَامَ المَرْأَةَ خَلْفَنَا»."]]},{"id":"um14_6","label":"الحديث ٧١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«بِتُّ عِنْدَ خَالَتِي مَيْمُونَةَ رَضِيَ اللَّهُ عَنْهَا؛ فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ، فَقُمْتُ عَنْ يَسَارِهِ، فَأَخَذَ بِرَأْسِي فَأَقَامَنِي عَنْ يَمِينِهِ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um15","title":"بَابُ الإِمَامَةِ","units":[{"id":"um15_1","label":"الحديث ٧٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«أَمَا يَخْشَى الَّذِي يَرْفَعُ رَأْسَهُ قَبْلَ الإِمَامِ أَنْ يُحَوِّلَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ؟! - أَوْ يَجْعَلَ صُورَتَهُ صُورَةَ حِمَارٍ؟! -»."]]},{"id":"um15_2","label":"الحديث ٧٣","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِنَّمَا جُعِلَ الإِمَامُ لِيُؤْتَمَّ بِهِ؛ فَلَا تَخْتَلِفُوا عَلَيْهِ؛ فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ؛ فَقُولُوا: رَبَّنَا وَلَكَ الحَمْدُ، وَإِذَا سَجَدَ فَاسْجُدُوا، وَإِذَا صَلَّى جَالِساً فَصَلُّوا جُلُوساً أَجْمَعُونَ»."]]},{"id":"um15_3","label":"الحديث ٧٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِهِ وَهُوَ شَاكٍ، فَصَلَّى جَالِساً وَصَلَّى وَرَاءَهُ قَوْمٌ قِيَاماً، فَأَشَارَ إِلَيْهِمْ: أَنِ اجْلِسُوا، فَلَمَّا انْصَرَفَ قَالَ: إِنَّمَا جُعِلَ الإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا رَفَعَ فَارْفَعُوا،"]]},{"id":"um15_4","label":"الحديث ٧٤ · المقطع ٢ من ٢","segs":[["matn","وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ؛ فَقُولُوا: رَبَّنَا وَلَكَ الحَمْدُ، وَإِذَا صَلَّى جَالِساً فَصَلُّوا جُلُوساً أَجْمَعُونَ»."]]},{"id":"um15_5","label":"الحديث ٧٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ يَزِيدَ الخَطْمِيِّ الأَنْصَارِيِّ قَالَ:"],["matn","«حَدَّثَنِي البَرَاءُ رَضِيَ اللَّهُ عَنْهُ - وَهُوَ غَيْرُ كَذُوبٍ - قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ،"]]},{"id":"um15_6","label":"الحديث ٧٥ · المقطع ٢ من ٢","segs":[["matn","لَمْ يَحْنِ أَحَدٌ مِنَّا ظَهْرَهُ حَتَّى يَقَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَاجِداً، ثُمَّ نَقَعُ سُجُوداً بَعْدَهُ»."]]},{"id":"um15_7","label":"الحديث ٧٦","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا أَمَّنَ الإِمَامُ فَأَمِّنُوا؛ فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ المَلَائِكَةِ؛ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ»."]]},{"id":"um15_8","label":"الحديث ٧٧","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا صَلَّى أَحَدُكُمْ لِلنَّاسِ فَلْيُخَفِّفْ؛ فَإِنَّ فِيهِمُ الضَّعِيفَ وَالسَّقِيمَ وَذَا الحَاجَةِ، وَإِذَا صَلَّى أَحَدُكُمْ لِنَفْسِهِ فَلْيُطَوِّلْ مَا شَاءَ»."]]},{"id":"um15_9","label":"الحديث ٧٨ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي مَسْعُودٍ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي لَأَتَأَخَّرُ عَنْ صَلَاةِ الصُّبْحِ مِنْ أَجْلِ فُلَانٍ مِمَّا يُطِيلُ بِنَا،"]]},{"id":"um15_10","label":"الحديث ٧٨ · المقطع ٢ من ٢","segs":[["matn","فَمَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَضِبَ فِي مَوْعِظَةٍ قَطُّ أَشَدَّ مِمَّا غَضِبَ يَوْمَئِذٍ، فَقَالَ: يَا أَيُّهَا النَّاسُ! إِنَّ مِنْكُمْ مُنَفِّرِينَ، فَأَيُّكُمْ أَمَّ النَّاسَ فَلْيُوجِزْ؛ فَإِنَّ مِنْ وَرَائِهِ الكَبِيرَ وَالضَّعِيفَ وَذَا الحَاجَةِ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um16","title":"بَابُ صِفَةِ صَلَاةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ","units":[{"id":"um16_1","label":"الحديث ٧٩ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَبَّرَ فِي الصَّلَاةِ سَكَتَ هُنَيْهَةً قَبْلَ أَنْ يَقْرَأَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ! بِأَبِي أَنْتَ وَأُمِّي! أَرَأَيْتَ سُكُوتَكَ بَيْنَ التَّكْبِيرِ وَالقِرَاءَةِ مَا تَقُولُ؟ قَالَ: أَقُولُ:"]]},{"id":"um16_2","label":"الحديث ٧٩ · المقطع ٢ من ٢","segs":[["matn","اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ المَشْرِقِ وَالمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالثَّلْجِ وَالمَاءِ وَالبَرَدِ»."]]},{"id":"um16_3","label":"الحديث ٨٠ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَفْتِحُ الصَّلَاةَ بِالتَّكْبِيرِ، وَالقِرَاءَةَ بِ﴿الحَمْدُ لِلَّهِ رَبِّ العَالَمِينَ﴾، وَكَانَ إِذَا رَكَعَ لَمْ يُشْخِصْ رَأْسَهُ وَلَمْ يُصَوِّبْهُ، وَلَكِنْ بَيْنَ ذَلِكَ،"]]},{"id":"um16_4","label":"الحديث ٨٠ · المقطع ٢ من ٣","segs":[["matn","وَكَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ لَمْ يَسْجُدْ حَتَّى يَسْتَوِيَ قَائِماً، وَكَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ السَّجْدَةِ لَمْ يَسْجُدْ حَتَّى يَسْتَوِيَ قَاعِداً، وَكَانَ يَقُولُ فِي كُلِّ رَكْعَتَيْنِ: التَّحِيَّةَ، وَكَانَ يَفْرُشُ رِجْلَهُ اليُسْرَى وَيَنْصِبُ رِجْلَهُ اليُمْنَى،"]]},{"id":"um16_5","label":"الحديث ٨٠ · المقطع ٣ من ٣","segs":[["matn","وَكَانَ يَنْهَى عَنْ عُقْبَةِ الشَّيْطَانِ، وَيَنْهَى أَنْ يَفْتَرِشَ الرَّجُلُ ذِرَاعَيْهِ افْتِرَاشَ السَّبُعِ، وَكَانَ يَخْتِمُ الصَّلَاةَ بِالتَّسْلِيمِ»."]]},{"id":"um16_6","label":"الحديث ٨١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَرْفَعُ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ إِذَا افْتَتَحَ الصَّلَاةَ وَإِذَا كَبَّرَ لِلرُّكُوعِ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ رَفَعَهُمَا كَذَلِكَ، وَقَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الحَمْدُ، وَكَانَ لَا يَفْعَلُ ذَلِكَ فِي السُّجُودِ»."]]},{"id":"um16_7","label":"الحديث ٨٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةِ أَعْظُمٍ: عَلَى الجَبْهَةِ - وَأَشَارَ بِيَدِهِ إِلَى أَنْفِهِ -، وَاليَدَيْنِ، وَالرُّكْبَتَيْنِ، وَأَطْرَافِ القَدَمَيْنِ»."]]},{"id":"um16_8","label":"الحديث ٨٣ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ إِلَى الصَّلَاةِ يُكَبِّرُ حِينَ يَقُومُ، ثُمَّ يُكَبِّرُ حِينَ يَرْكَعُ، ثُمَّ يَقُولُ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ؛ حِينَ يَرْفَعُ صُلْبَهُ مِنَ الرَّكْعَةِ، ثُمَّ يَقُولُ وَهُوَ قَائِمٌ:"]]},{"id":"um16_9","label":"الحديث ٨٣ · المقطع ٢ من ٢","segs":[["matn","رَبَّنَا وَلَكَ الحَمْدُ، ثُمَّ يُكَبِّرُ حِينَ يَهْوِي، ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ، ثُمَّ يُكَبِّرُ حِينَ يَسْجُدُ، ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ، ثُمَّ يَفْعَلُ ذَلِكَ فِي صَلَاتِهِ كُلِّهَا حَتَّى يَقْضِيَهَا، وَيُكَبِّرُ حِينَ يَقُومُ مِنَ الثِّنْتَيْنِ بَعْدَ الجُلُوسِ»."]]},{"id":"um16_10","label":"الحديث ٨٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ مُطَرِّفِ بْنِ عَبْدِ اللَّهِ قَالَ:"],["matn","«صَلَّيْتُ أَنَا وَعِمْرَانُ صَلَاةً خَلْفَ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُمَا؛ فَكَانَ إِذَا سَجَدَ كَبَّرَ، وَإِذَا رَفَعَ رَأْسَهُ كَبَّرَ، وَإِذَا نَهَضَ مِنَ الرَّكْعَتَيْنِ كَبَّرَ، فَلَمَّا قَضَى الصَّلَاةَ أَخَذَ بِيَدِي عِمْرَانُ بْنُ حُصَيْنٍ فَقَالَ:"]]},{"id":"um16_11","label":"الحديث ٨٤ · المقطع ٢ من ٢","segs":[["matn","قَدْ ذَكَّرَنِي هَذَا صَلَاةَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَوْ قَالَ: صَلَّى بِنَا صَلَاةَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -»."]]},{"id":"um16_12","label":"الحديث ٨٥","segs":[["rawi","عَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«رَمَقْتُ الصَّلَاةَ مَعَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَجَدْتُ قِيَامَهُ، فَرَكْعَتَهُ، فَاعْتِدَالَهُ بَعْدَ رُكُوعِهِ، فَسَجْدَتَهُ، فَجَلْسَتَهُ بَيْنَ السَّجْدَتَيْنِ، فَسَجْدَتَهُ، فَجَلْسَتَهُ مَا بَيْنَ التَّسْلِيمِ وَالِانْصِرَافِ؛ قَرِيباً مِنَ السَّوَاءِ». وَفِي رِوَايَةِ البُخَارِيِّ: «مَا خَلَا القِيَامَ وَالقُعُودَ قَرِيباً مِنَ السَّوَاءِ»."]]},{"id":"um16_13","label":"الحديث ٨٦ · المقطع ١ من ٢","segs":[["rawi","عَنْ ثَابِتٍ البُنَانِيِّ، عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«إِنِّي لَا آلُو أَنْ أُصَلِّيَ بِكُمْ كَمَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِنَا، قَالَ ثَابِتٌ: فَكَانَ أَنَسٌ يَصْنَعُ شَيْئاً لَا أَرَاكُمْ تَصْنَعُونَهُ؛"]]},{"id":"um16_14","label":"الحديث ٨٦ · المقطع ٢ من ٢","segs":[["matn","كَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ انْتَصَبَ قَائِماً حَتَّى يَقُولَ القَائِلُ: قَدْ نَسِيَ، وَإِذَا رَفَعَ مِنَ السَّجْدَةِ مَكَثَ حَتَّى يَقُولَ القَائِلُ: قَدْ نَسِيَ»."]]},{"id":"um16_15","label":"الحديث ٨٧","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«مَا صَلَّيْتُ وَرَاءَ إِمَامٍ قَطُّ أَخَفَّ صَلَاةً وَلَا أَتَمَّ صَلَاةً مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ»."]]},{"id":"um16_16","label":"الحديث ٨٨ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي قِلَابَةَ عَبْدِ اللَّهِ بْنِ زَيْدٍ الجَرْمِيِّ البَصْرِيِّ قَالَ:"],["matn","«جَاءَنَا مَالِكُ بْنُ الحُوَيْرِثِ رَضِيَ اللَّهُ عَنْهُ فِي مَسْجِدِنَا هَذَا؛ فَقَالَ: إِنِّي لَأُصَلِّي بِكُمْ وَمَا أُرِيدُ الصَّلَاةَ، أُصَلِّي كَيْفَ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، فَقُلْتُ لِأَبِي قِلَابَةَ: كَيْفَ كَانَ يُصَلِّي؟ قَالَ:"]]},{"id":"um16_17","label":"الحديث ٨٨ · المقطع ٢ من ٢","segs":[["matn","مِثْلَ صَلَاةِ شَيْخِنَا هَذَا - وَكَانَ يَجْلِسُ إِذَا رَفَعَ رَأْسَهُ مِنَ السُّجُودِ قَبْلَ أَنْ يَنْهَضَ -»."]]},{"id":"um16_18","label":"الحديث ٨٩","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ مَالِكٍ ابْنِ بُحَيْنَةَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا صَلَّى فَرَّجَ بَيْنَ يَدَيْهِ حَتَّى يَبْدُوَ بَيَاضُ إِبْطَيْهِ»."]]},{"id":"um16_19","label":"الحديث ٩٠","segs":[["rawi","عَنْ أَبِي مَسْلَمَةَ سَعِيدِ بْنِ يَزِيدَ قَالَ:"],["matn","«سَأَلْتُ أَنَسَ بْنَ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي نَعْلَيْهِ؟ قَالَ: نَعَمْ»."]]},{"id":"um16_20","label":"الحديث ٩١","segs":[["rawi","عَنْ أَبِي قَتَادَةَ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي وَهُوَ حَامِلٌ أُمَامَةَ - بِنْتَ زَيْنَبَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلِأَبِي العَاصِي بْنِ الرَّبِيعِ بْنِ عَبْدِ شَمْسٍ -، فَإِذَا سَجَدَ وَضَعَهَا، وَإِذَا قَامَ حَمَلَهَا»."]]},{"id":"um16_21","label":"الحديث ٩٢","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«اعْتَدِلُوا فِي السُّجُودِ، وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ انْبِسَاطَ الكَلْبِ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um17","title":"بَابُ وُجُوبِ الطُّمَأْنِينَةِ فِي الرُّكُوعِ وَالسُّجُودِ","units":[{"id":"um17_1","label":"الحديث ٩٣ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ المَسْجِدَ، فَدَخَلَ رَجُلٌ فَصَلَّى، ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ، فَرَجَعَ فَصَلَّى كَمَا صَلَّى،"]]},{"id":"um17_2","label":"الحديث ٩٣ · المقطع ٢ من ٣","segs":[["matn","ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ - ثَلَاثاً -، فَقَالَ: وَالَّذِي بَعَثَكَ بِالحَقِّ! مَا أُحْسِنُ غَيْرَهُ فَعَلِّمْنِي، قَالَ: إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ،"]]},{"id":"um17_3","label":"الحديث ٩٣ · المقطع ٣ من ٣","segs":[["matn","ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنَ القُرْآنِ، ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعاً، ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِماً، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِداً، ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِساً، وَافْعَلْ ذَلِكَ فِي صَلَاتِكَ كُلِّهَا»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um18","title":"بَابُ القِرَاءَةِ فِي الصَّلَاةِ","units":[{"id":"um18_1","label":"الحديث ٩٤","segs":[["rawi","عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ بِفَاتِحَةِ الكِتَابِ»."]]},{"id":"um18_2","label":"الحديث ٩٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي قَتَادَةَ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الرَّكْعَتَيْنِ الأُولَيَيْنِ مِنْ صَلَاةِ الظُّهْرِ بِفَاتِحَةِ الكِتَابِ وَسُورَتَيْنِ؛ يُطَوِّلُ فِي الأُولَى، وَيُقَصِّرُ فِي الثَّانِيَةِ، يُسْمِعُ الآيَةَ أَحْيَاناً، وَكَانَ يَقْرَأُ فِي العَصْرِ بِفَاتِحَةِ الكِتَابِ وَسُورَتَيْنِ؛ يُطَوِّلُ فِي الأُولَى،"]]},{"id":"um18_3","label":"الحديث ٩٥ · المقطع ٢ من ٢","segs":[["matn","وَيُقَصِّرُ فِي الثَّانِيَةِ، وَكَانَ يُطَوِّلُ فِي الرَّكْعَةِ الأُولَى مِنْ صَلَاةِ الصُّبْحِ، وَيُقَصِّرُ فِي الثَّانِيَةِ، وَفِي الرَّكْعَتَيْنِ الأُخْرَيَيْنِ بِأُمِّ الكِتَابِ»."]]},{"id":"um18_4","label":"الحديث ٩٦","segs":[["rawi","عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي المَغْرِبِ بِالطُّورِ»."]]},{"id":"um18_5","label":"الحديث ٩٧","segs":[["rawi","عَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي سَفَرٍ، فَصَلَّى العِشَاءَ الآخِرَةَ، فَقَرَأَ فِي إِحْدَى الرَّكْعَتَيْنِ بِالتِّينِ وَالزَّيْتُونِ، فَمَا سَمِعْتُ أَحَداً أَحْسَنَ صَوْتاً أَوْ قِرَاءَةً مِنْهُ»."]]},{"id":"um18_6","label":"الحديث ٩٨ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ رَجُلاً عَلَى سَرِيَّةٍ، فَكَانَ يَقْرَأُ لِأَصْحَابِهِ فِي صَلَاتِهِمْ، فَيَخْتِمُ بِ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾، فَلَمَّا رَجَعُوا ذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ:"]]},{"id":"um18_7","label":"الحديث ٩٨ · المقطع ٢ من ٢","segs":[["matn","سَلُوهُ لِأَيِّ شَيْءٍ يَصْنَعُ ذَلِكَ؟ فَسَأَلُوهُ فَقَالَ: لِأَنَّهَا صِفَةُ الرَّحْمَنِ عَزَّ وَجَلَّ؛ فَأَنَا أُحِبُّ أَنْ أَقْرَأَ بِهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَخْبِرُوهُ أَنَّ اللَّهَ تَعَالَى يُحِبُّهُ»."]]},{"id":"um18_8","label":"الحديث ٩٩","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِمُعَاذٍ:"],["matn","«فَلَوْلَا صَلَّيْتَ بِ﴿سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى﴾، ﴿وَالشَّمْسِ وَضُحَاهَا﴾، ﴿وَاللَّيْلِ إِذَا يَغْشَى﴾! فَإِنَّهُ يُصَلِّي وَرَاءَكَ الكَبِيرُ، وَالضَّعِيفُ، وَذُو الحَاجَةِ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um19","title":"بَابُ تَرْكِ الجَهْرِ بِ﴿بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ﴾","units":[{"id":"um19_1","label":"الحديث ١٠٠ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ وَعُمَرَ رَضِيَ اللَّهُ عَنْهُمَا كَانُوا يَفْتَتِحُونَ الصَّلَاةَ بِ﴿الحَمْدُ لِلَّهِ رَبِّ العَالَمِينَ﴾». وَفِي رِوَايَةٍ: «صَلَّيْتُ مَعَ أَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ رَضِيَ اللَّهُ عَنْهُمْ؛"]]},{"id":"um19_2","label":"الحديث ١٠٠ · المقطع ٢ من ٣","segs":[["matn","فَلَمْ أَسْمَعْ أَحَداً مِنْهُمْ يَقْرَأُ ﴿بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ﴾». وَلِمُسْلِمٍ: «صَلَّيْتُ خَلْفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ؛ فَكَانُوا يَسْتَفْتِحُونَ بِ﴿الحَمْدُ لِلَّهِ رَبِّ العَالَمِينَ﴾؛"]]},{"id":"um19_3","label":"الحديث ١٠٠ · المقطع ٣ من ٣","segs":[["matn","لَا يَذْكُرُونَ ﴿بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ﴾ فِي أَوَّلِ قِرَاءَةٍ وَلَا فِي آخِرِهَا»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um20","title":"بَابُ سُجُودِ السَّهْوِ","units":[{"id":"um20_1","label":"الحديث ١٠١ · المقطع ١ من ٤","segs":[["rawi","عَنْ مُحَمَّدِ بْنِ سِيرِينَ، عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِحْدَى صَلَاتَيِ العَشِيِّ - قَالَ ابْنُ سِيرِينَ: وَسَمَّاهَا أَبُو هُرَيْرَةَ، وَلَكِنْ نَسِيتُ أَنَا - قَالَ: فَصَلَّى بِنَا رَكْعَتَيْنِ ثُمَّ سَلَّمَ، فَقَامَ إِلَى خَشَبَةٍ مَعْرُوضَةٍ فِي المَسْجِدِ،"]]},{"id":"um20_2","label":"الحديث ١٠١ · المقطع ٢ من ٤","segs":[["matn","فَاتَّكَأَ عَلَيْهَا - كَأَنَّهُ غَضْبَانُ - وَوَضَعَ يَدَهُ اليُمْنَى عَلَى اليُسْرَى وَشَبَّكَ بَيْنَ أَصَابِعِهِ، وَخَرَجَتِ السَّرَعَانُ مِنْ أَبْوَابِ المَسْجِدِ فَقَالُوا: قُصِرَتِ الصَّلَاةُ؟ وَفِي القَوْمِ أَبُو بَكْرٍ وَعُمَرُ فَهَابَا أَنْ يُكَلِّمَاهُ،"]]},{"id":"um20_3","label":"الحديث ١٠١ · المقطع ٣ من ٤","segs":[["matn","وَفِي القَوْمِ رَجُلٌ فِي يَدَيْهِ طُولٌ يُقَالُ لَهُ: ذُو اليَدَيْنِ، فَقَالَ: يَا رَسُولَ اللَّهِ! أَنَسِيتَ أَمْ قُصِرَتِ الصَّلَاةُ؟ قَالَ: لَمْ أَنْسَ وَلَمْ تُقْصَرْ، فَقَالَ: أَكَمَا يَقُولُ ذُو اليَدَيْنِ؟ فَقَالُوا: نَعَمْ، فَتَقَدَّمَ؛ فَصَلَّى مَا تَرَكَ،"]]},{"id":"um20_4","label":"الحديث ١٠١ · المقطع ٤ من ٤","segs":[["matn","ثُمَّ سَلَّمَ، ثُمَّ كَبَّرَ وَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ، ثُمَّ رَفَعَ رَأْسَهُ وَكَبَّرَ، ثُمَّ كَبَّرَ وَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ، ثُمَّ رَفَعَ رَأْسَهُ وَكَبَّرَ، فَرُبَّمَا سَأَلُوهُ: ثُمَّ سَلَّمَ؟ قَالَ: فَنُبِّئْتُ أَنَّ عِمْرَانَ بْنَ حُصَيْنٍ قَالَ: ثُمَّ سَلَّمَ»."]]},{"id":"um20_5","label":"الحديث ١٠٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ ابْنِ بُحَيْنَةَ رَضِيَ اللَّهُ عَنْهُمَا - وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِهِمُ الظُّهْرَ، فَقَامَ فِي الرَّكْعَتَيْنِ الأُولَيَيْنِ وَلَمْ يَجْلِسْ، فَقَامَ النَّاسُ مَعَهُ، حَتَّى إِذَا قَضَى الصَّلَاةَ وَانْتَظَرَ النَّاسُ تَسْلِيمَهُ؛ كَبَّرَ وَهُوَ جَالِسٌ فَسَجَدَ سَجْدَتَيْنِ قَبْلَ أَنْ يُسَلِّمَ، ثُمَّ سَلَّمَ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um21","title":"بَابُ المُرُورِ بَيْنَ يَدَيِ المُصَلِّي","units":[{"id":"um21_1","label":"الحديث ١٠٣","segs":[["rawi","عَنْ أَبِي جُهَيْمِ بْنِ الحَارِثِ بْنِ الصِّمَّةِ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«لَوْ يَعْلَمُ المَارُّ بَيْنَ يَدَيِ المُصَلِّي مَاذَا عَلَيْهِ مِنَ الإِثْمِ؛ لَكَانَ أَنْ يَقِفَ أَرْبَعِينَ خَيْراً لَهُ مِنْ أَنْ يَمُرَّ بَيْنَ يَدَيْهِ. قَالَ أَبُو النَّضْرِ: لَا أَدْرِي؛ قَالَ: أَرْبَعِينَ يَوْماً، أَوْ شَهْراً، أَوْ سَنَةً»."]]},{"id":"um21_2","label":"الحديث ١٠٤","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «إِذَا صَلَّى أَحَدُكُمْ إِلَى شَيْءٍ يَسْتُرُهُ مِنَ النَّاسِ فَأَرَادَ أَحَدٌ أَنْ يَجْتَازَ بَيْنَ يَدَيْهِ؛ فَلْيَدْفَعْهُ، فَإِنْ أَبَى فَلْيُقَاتِلْهُ؛ فَإِنَّمَا هُوَ شَيْطَانٌ»."]]},{"id":"um21_3","label":"الحديث ١٠٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أَقْبَلْتُ رَاكِباً عَلَى حِمَارٍ أَتَانٍ - وَأَنَا يَوْمَئِذٍ قَدْ نَاهَزْتُ الِاحْتِلَامَ - وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِالنَّاسِ بِمِنىً إِلَى غَيْرِ جِدَارٍ، فَمَرَرْتُ بَيْنَ يَدَيْ بَعْضِ الصَّفِّ، فَنَزَلْتُ، فَأَرْسَلْتُ الأَتَانَ تَرْتَعُ،"]]},{"id":"um21_4","label":"الحديث ١٠٥ · المقطع ٢ من ٢","segs":[["matn","وَدَخَلْتُ فِي الصَّفِّ؛ فَلَمْ يُنْكِرْ ذَلِكَ عَلَيَّ أَحَدٌ»."]]},{"id":"um21_5","label":"الحديث ١٠٦","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كُنْتُ أَنَامُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرِجْلَايَ فِي قِبْلَتِهِ، فَإِذَا سَجَدَ غَمَزَنِي فَقَبَضْتُ رِجْلَيَّ، وَإِذَا قَامَ بَسَطْتُهُمَا، وَالبُيُوتُ يَوْمَئِذٍ لَيْسَ فِيهَا مَصَابِيحُ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um22","title":"بَابٌ جَامِعٌ","units":[{"id":"um22_1","label":"الحديث ١٠٧","segs":[["rawi","عَنْ أَبِي قَتَادَةَ بْنِ رِبْعِيٍّ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«إِذَا دَخَلَ أَحَدُكُمُ المَسْجِدَ؛ فَلَا يَجْلِسْ حَتَّى يُصَلِّيَ رَكْعَتَيْنِ»."]]},{"id":"um22_2","label":"الحديث ١٠٨","segs":[["rawi","عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كُنَّا نَتَكَلَّمُ فِي الصَّلَاةِ؛ يُكَلِّمُ الرَّجُلُ صَاحِبَهُ وَهُوَ إِلَى جَنْبِهِ فِي الصَّلَاةِ، حَتَّى نَزَلَتْ: ﴿وَقُومُوا لِلَّهِ قَانِتِينَ﴾؛ فَأُمِرْنَا بِالسُّكُوتِ وَنُهِينَا عَنِ الكَلَامِ»."]]},{"id":"um22_3","label":"الحديث ١٠٩","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، وَأَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُمْ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:"],["matn","«إِذَا اشْتَدَّ الحَرُّ فَأَبْرِدُوا عَنِ الصَّلَاةِ؛ فَإِنَّ شِدَّةَ الحَرِّ مِنْ فَيْحِ جَهَنَّمَ»."]]},{"id":"um22_4","label":"الحديث ١١٠","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ نَسِيَ صَلَاةً فَلْيُصَلِّهَا إِذَا ذَكَرَهَا، لَا كَفَّارَةَ لَهَا إِلَّا ذَلِكَ؛ ﴿أَقِمِ الصَّلَاةَ لِذِكْرِي﴾». وَلِمُسْلِمٍ: «مَنْ نَسِيَ صَلَاةً أَوْ نَامَ عَنْهَا؛ فَكَفَّارَتُهَا أَنْ يُصَلِّيَهَا إِذَا ذَكَرَهَا»."]]},{"id":"um22_5","label":"الحديث ١١١","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ مُعَاذَ بْنَ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ كَانَ يُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِشَاءَ الآخِرَةِ، ثُمَّ يَرْجِعُ إِلَى قَوْمِهِ فَيُصَلِّي بِهِمْ تِلْكَ الصَّلَاةَ»."]]},{"id":"um22_6","label":"الحديث ١١٢","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كُنَّا نُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شِدَّةِ الحَرِّ، فَإِذَا لَمْ يَسْتَطِعْ أَحَدُنَا أَنْ يُمَكِّنَ جَبْهَتَهُ مِنَ الأَرْضِ بَسَطَ ثَوْبَهُ فَسَجَدَ عَلَيْهِ»."]]},{"id":"um22_7","label":"الحديث ١١٣","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَا يُصَلِّي أَحَدُكُمْ فِي الثَّوْبِ الوَاحِدِ لَيْسَ عَلَى عَاتِقِهِ مِنْهُ شَيْءٌ»."]]},{"id":"um22_8","label":"الحديث ١١٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ أَكَلَ ثُوماً أَوْ بَصَلاً فَلْيَعْتَزِلْنَا - أَوْ لِيَعْتَزِلْ مَسْجِدَنَا -، وَلْيَقْعُدْ فِي بَيْتِهِ، وَأُتِيَ بِقِدْرٍ فِيهِ خَضِرَاتٌ مِنْ بُقُولٍ، فَوَجَدَ لَهَا رِيحاً، فَسَأَلَ فَأُخْبِرَ بِمَا فِيهَا مِنَ البُقُولِ، فَقَالَ:"]]},{"id":"um22_9","label":"الحديث ١١٤ · المقطع ٢ من ٢","segs":[["matn","قَرِّبُوهَا - إِلَى بَعْضِ أَصْحَابِهِ -، فَلَمَّا رَآهُ كَرِهَ أَكْلَهَا قَالَ: كُلْ؛ فَإِنِّي أُنَاجِي مَنْ لَا تُنَاجِي»."]]},{"id":"um22_10","label":"الحديث ١١٥","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ أَكَلَ البَصَلَ وَالثُّومَ وَالكُرَّاثَ فَلَا يَقْرَبَنَّ مَسْجِدَنَا؛ فَإِنَّ المَلَائِكَةَ تَتَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ بَنُو آدَمَ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um23","title":"بَابُ التَّشَهُّدِ","units":[{"id":"um23_1","label":"الحديث ١١٦ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«عَلَّمَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ التَّشَهُّدَ - كَفِّي بَيْنَ كَفَّيْهِ - كَمَا يُعَلِّمُنِي السُّورَةَ مِنَ القُرْآنِ: التَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ، وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ،"]]},{"id":"um23_2","label":"الحديث ١١٦ · المقطع ٢ من ٣","segs":[["matn","أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ». وَفِي لَفْظٍ: «إِذَا قَعَدَ أَحَدُكُمْ فِي الصَّلَاةِ؛ فَلْيَقُلِ: التَّحِيَّاتُ لِلَّهِ … - وَذَكَرَهُ -». وَفِيهِ: «فَإِنَّكُمْ إِذَا فَعَلْتُمْ ذَلِكَ؛"]]},{"id":"um23_3","label":"الحديث ١١٦ · المقطع ٣ من ٣","segs":[["matn","فَقَدْ سَلَّمْتُمْ عَلَى كُلِّ عَبْدٍ لِلَّهِ صَالِحٍ فِي السَّمَاءِ وَالأَرْضِ». وَفِيهِ: «فَلْيَتَخَيَّرْ مِنَ المَسْأَلَةِ مَا شَاءَ»."]]},{"id":"um23_4","label":"الحديث ١١٧ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى قَالَ:"],["matn","«لَقِيَنِي كَعْبُ بْنُ عُجْرَةَ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: أَلَا أُهْدِي لَكَ هَدِيَّةً؟ إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَيْنَا فَقُلْنَا: يَا رَسُولَ اللَّهِ! قَدْ عَلِمْنَا كَيْفَ نُسَلِّمُ عَلَيْكَ؛ فَكَيْفَ نُصَلِّي عَلَيْكَ؟ قَالَ: قُولُوا:"]]},{"id":"um23_5","label":"الحديث ١١٧ · المقطع ٢ من ٢","segs":[["matn","اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ»."]]},{"id":"um23_6","label":"الحديث ١١٨ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْعُو يَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ القَبْرِ، وَمِنْ عَذَابِ النَّارِ، وَمِنْ فِتْنَةِ المَحْيَا وَالمَمَاتِ، وَمِنْ فِتْنَةِ المَسِيحِ الدَّجَّالِ». وَفِي لَفْظٍ لِمُسْلِمٍ:"]]},{"id":"um23_7","label":"الحديث ١١٨ · المقطع ٢ من ٢","segs":[["matn","«إِذَا تَشَهَّدَ أَحَدُكُمْ فَلْيَسْتَعِذْ بِاللَّهِ مِنْ أَرْبَعٍ؛ يَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ»، ثُمَّ ذَكَرَ نَحْوَهُ."]]},{"id":"um23_8","label":"الحديث ١١٩","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِي، عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُمْ أَنَّهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«عَلِّمْنِي دُعَاءً أَدْعُو بِهِ فِي صَلَاتِي، قَالَ: قُلِ: اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْماً كَثِيراً، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي، إِنَّكَ أَنْتَ الغَفُورُ الرَّحِيمُ»."]]},{"id":"um23_9","label":"الحديث ١٢٠ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«مَا صَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةً بَعْدَ أَنْ أُنْزِلَتْ عَلَيْهِ: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالفَتْحُ﴾؛ إِلَّا يَقُولُ فِيهَا: سُبْحَانَكَ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي». وَفِي لَفْظٍ:"]]},{"id":"um23_10","label":"الحديث ١٢٠ · المقطع ٢ من ٢","segs":[["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ: سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um24","title":"بَابُ الوِتْرِ","units":[{"id":"um24_1","label":"الحديث ١٢١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«سَأَلَ رَجُلٌ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى المِنْبَرِ: مَا تَرَى فِي صَلَاةِ اللَّيْلِ؟ قَالَ: مَثْنَى مَثْنَى، فَإِذَا خَشِيَ الصُّبْحَ صَلَّى وَاحِدَةً فَأَوْتَرَتْ لَهُ مَا صَلَّى، وَإِنَّهُ كَانَ يَقُولُ: اجْعَلُوا آخِرَ صَلَاتِكُمْ بِاللَّيْلِ وِتْراً»."]]},{"id":"um24_2","label":"الحديث ١٢٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«مِنْ كُلِّ اللَّيْلِ قَدْ أَوْتَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ مِنْ أَوَّلِ اللَّيْلِ، وَأَوْسَطِهِ، وَآخِرِهِ، فَانْتَهَى وِتْرُهُ إِلَى السَّحَرِ»."]]},{"id":"um24_3","label":"الحديث ١٢٣","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً؛ يُوتِرُ مِنْ ذَلِكَ بِخَمْسٍ، لَا يَجْلِسُ فِي شَيْءٍ إِلَّا فِي آخِرِهَا»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um25","title":"بَابُ الذِّكْرِ عَقِيبَ الصَّلَاةِ","units":[{"id":"um25_1","label":"الحديث ١٢٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَفْعَ الصَّوْتِ بِالذِّكْرِ حِينَ يَنْصَرِفُ النَّاسُ مِنَ المَكْتُوبَةِ؛ كَانَ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: كُنْتُ أَعْلَمُ إِذَا انْصَرَفُوا بِذَلِكَ إِذَا سَمِعْتُهُ -». وَفِي لَفْظٍ:"]]},{"id":"um25_2","label":"الحديث ١٢٤ · المقطع ٢ من ٢","segs":[["matn","«مَا كُنَّا نَعْرِفُ انْقِضَاءَ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا بِالتَّكْبِيرِ»."]]},{"id":"um25_3","label":"الحديث ١٢٥ · المقطع ١ من ٣","segs":[["rawi","عَنْ وَرَّادٍ - مَوْلَى المُغِيرَةِ بْنِ شُعْبَةَ - قَالَ:"],["matn","«أَمْلَى عَلَيَّ المُغِيرَةُ بْنُ شُعْبَةَ فِي كِتَابٍ إِلَى مُعَاوِيَةَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي دُبُرِ كُلِّ صَلَاةٍ مَكْتُوبَةٍ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ،"]]},{"id":"um25_4","label":"الحديث ١٢٥ · المقطع ٢ من ٣","segs":[["matn","لَهُ المُلْكُ وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الجَدِّ مِنْكَ الجَدُّ، ثُمَّ وَفَدْتُ بَعْدُ عَلَى مُعَاوِيَةَ فَسَمِعْتُهُ يَأْمُرُ النَّاسَ بِذَلِكَ». وَفِي لَفْظٍ:"]]},{"id":"um25_5","label":"الحديث ١٢٥ · المقطع ٣ من ٣","segs":[["matn","«وَكَانَ يَنْهَى عَنْ قِيلَ وَقَالَ، وَإِضَاعَةِ المَالِ، وَكَثْرَةِ السُّؤَالِ، وَكَانَ يَنْهَى عَنْ عُقُوقِ الأُمَّهَاتِ، وَوَأْدِ البَنَاتِ، وَمَنْعٍ وَهَاتِ»."]]},{"id":"um25_6","label":"الحديث ١٢٦ · المقطع ١ من ٥","segs":[["rawi","عَنْ سُمَيٍّ - مَوْلَى أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الحَارِثِ بْنِ هِشَامٍ -، عَنْ أَبِي صَالِحٍ السَّمَّانِ، عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ فُقَرَاءَ المُهَاجِرِينَ أَتَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: قَدْ ذَهَبَ أَهْلُ الدُّثُورِ بِالدَّرَجَاتِ العُلَى، وَالنَّعِيمِ المُقِيمِ، فَقَالَ: وَمَا ذَاكَ؟ قَالُوا: يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَيَتَصَدَّقُونَ وَلَا نَتَصَدَّقُ، وَيُعْتِقُونَ وَلَا نُعْتِقُ؛"]]},{"id":"um25_7","label":"الحديث ١٢٦ · المقطع ٢ من ٥","segs":[["matn","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفَلَا أُعَلِّمُكُمْ شَيْئاً تُدْرِكُونَ بِهِ مَنْ سَبَقَكُمْ، وَتَسْبِقُونَ بِهِ مَنْ بَعْدَكُمْ، وَلَا يَكُونُ أَحَدٌ أَفْضَلَ مِنْكُمْ؛ إِلَّا مَنْ صَنَعَ مِثْلَ مَا صَنَعْتُمْ؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ! قَالَ:"]]},{"id":"um25_8","label":"الحديث ١٢٦ · المقطع ٣ من ٥","segs":[["matn","تُسَبِّحُونَ وَتُكَبِّرُونَ وَتَحْمَدُونَ دُبُرَ كُلِّ صَلَاةٍ - ثَلَاثاً وَثَلَاثِينَ مَرَّةً -. قَالَ أَبُو صَالِحٍ: فَرَجَعَ فُقَرَاءُ المُهَاجِرِينَ، فَقَالُوا: سَمِعَ إِخْوَانُنَا أَهْلُ الأَمْوَالِ بِمَا فَعَلْنَا، فَفَعَلُوا مِثْلَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um25_9","label":"الحديث ١٢٦ · المقطع ٤ من ٥","segs":[["matn","ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَنْ يَشَاءُ. قَالَ سُمَيٌّ: فَحَدَّثْتُ بَعْضَ أَهْلِي هَذَا الحَدِيثَ، فَقَالَ: وَهِمْتَ، إِنَّمَا قَالَ لَكَ: تُسَبِّحُ اللَّهَ ثَلَاثاً وَثَلَاثِينَ، وَتَحْمَدُ اللَّهَ ثَلَاثاً وَثَلَاثِينَ، وتُكَبِّرُ اللَّهَ ثَلَاثاً وَثَلَاثِينَ،"]]},{"id":"um25_10","label":"الحديث ١٢٦ · المقطع ٥ من ٥","segs":[["matn","فَرَجَعْتُ إِلَى أَبِي صَالِحٍ فَقُلْتُ لَهُ ذَلِكَ، فَقَالَ: اللَّهُ أَكْبَرُ، وَسُبْحَانَ اللَّهِ، وَالحَمْدُ لِلَّهِ؛ حَتَّى تَبْلُغَ مِنْ جَمِيعِهِنَّ ثَلَاثاً وَثَلَاثِينَ»."]]},{"id":"um25_11","label":"الحديث ١٢٧","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي خَمِيصَةٍ لَهَا أَعْلَامٌ، فَنَظَرَ إِلَى أَعْلَامِهَا نَظْرَةً، فَلَمَّا انْصَرَفَ قَالَ: اذْهَبُوا بِخَمِيصَتِي هَذِهِ إِلَى أَبِي جَهْمٍ، وَائْتُونِي بِأَنْبِجَانِيَّةِ أَبِي جَهْمٍ؛ فَإِنَّهَا أَلْهَتْنِي آنِفاً عَنْ صَلَاتِي»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um26","title":"بَابُ الجَمْعِ بَيْنَ الصَّلَاتَيْنِ فِي السَّفَرِ","units":[{"id":"um26_1","label":"الحديث ١٢٨","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ صَلَاةِ الظُّهْرِ وَالعَصْرِ إِذَا كَانَ عَلَى ظَهْرِ سَيْرٍ، وَيَجْمَعُ بَيْنَ المَغْرِبِ وَالعِشَاءِ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um27","title":"بَابُ قَصْرِ الصَّلَاةِ فِي السَّفَرِ","units":[{"id":"um27_1","label":"الحديث ١٢٩","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«صَحِبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ فَكَانَ لَا يَزِيدُ فِي السَّفَرِ عَلَى رَكْعَتَيْنِ، وَأَبَا بَكْرٍ وَعُمَرَ وَعُثْمَانَ كَذَلِكَ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um28","title":"بَابُ الجُمُعَةِ","units":[{"id":"um28_1","label":"الحديث ١٣٠ · المقطع ١ من ٢","segs":[["rawi","عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ عَلَيْهِ، فَكَبَّرَ وَكَبَّرَ النَّاسُ وَرَاءَهُ وَهُوَ عَلَى المِنْبَرِ، ثُمَّ رَفَعَ، فَنَزَلَ القَهْقَرَى حَتَّى سَجَدَ فِي أَصْلِ المِنْبَرِ، ثُمَّ عَادَ حَتَّى فَرَغَ مِنْ آخِرِ صَلَاتِهِ،"]]},{"id":"um28_2","label":"الحديث ١٣٠ · المقطع ٢ من ٢","segs":[["matn","ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ: أَيُّهَا النَّاسُ! إِنَّمَا صَنَعْتُ هَذَا لِتَأْتَمُّوا بِي، وَلِتَعَلَّمُوا صَلَاتِي». وَفِي لَفْظٍ: «صَلَّى عَلَيْهَا، ثُمَّ كَبَّرَ عَلَيْهَا، ثُمَّ رَكَعَ وَهُوَ عَلَيْهَا، ثُمَّ نَزَلَ القَهْقَرَى»."]]},{"id":"um28_3","label":"الحديث ١٣١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ جَاءَ مِنْكُمُ الجُمُعَةَ؛ فَلْيَغْتَسِلْ»."]]},{"id":"um28_4","label":"الحديث ١٣٢","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ خُطْبَتَيْنِ وَهُوَ قَائِمٌ؛ يَفْصِلُ بَيْنَهُمَا بِجُلُوسٍ»."]]},{"id":"um28_5","label":"الحديث ١٣٣","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«جَاءَ رَجُلٌ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ النَّاسَ يَوْمَ الجُمُعَةِ، فَقَالَ: صَلَّيْتَ يَا فُلَانُ؟ قَالَ: لَا، قَالَ: قُمْ فَارْكَعْ رَكْعَتَيْنِ». وَفِي رِوَايَةٍ: «فَصَلِّ رَكْعَتَيْنِ»."]]},{"id":"um28_6","label":"الحديث ١٣٤","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا قُلْتَ لِصَاحِبِكَ: أَنْصِتْ يَوْمَ الجُمُعَةِ وَالإِمَامُ يَخْطُبُ؛ فَقَدْ لَغَوْتَ»."]]},{"id":"um28_7","label":"الحديث ١٣٥ · المقطع ١ من ٢","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنِ اغْتَسَلَ يَوْمَ الجُمُعَةِ ثُمَّ رَاحَ؛ فَكَأَنَّمَا قَرَّبَ بَدَنَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الثَّانِيَةِ؛ فَكَأَنَّمَا قَرَّبَ بَقَرَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الثَّالِثَةِ؛ فَكَأَنَّمَا قَرَّبَ كَبْشاً أَقْرَنَ، وَمَنْ رَاحَ فِي السَّاعَةِ الرَّابِعَةِ؛ فَكَأَنَّمَا قَرَّبَ دَجَاجَةً،"]]},{"id":"um28_8","label":"الحديث ١٣٥ · المقطع ٢ من ٢","segs":[["matn","وَمَنْ رَاحَ فِي السَّاعَةِ الخَامِسَةِ؛ فَكَأَنَّمَا قَرَّبَ بَيْضَةً، فَإِذَا خَرَجَ الإِمَامُ؛ حَضَرَتِ المَلَائِكَةُ يَسْتَمِعُونَ الذِّكْرَ»."]]},{"id":"um28_9","label":"الحديث ١٣٦","segs":[["rawi","عَنْ سَلَمَةَ ابْنِ الأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ - وَكَانَ مِنْ أَصْحَابِ الشَّجَرَةِ - قَالَ:"],["matn","«كُنَّا نُصَلِّي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الجُمُعَةَ، ثُمَّ نَنْصَرِفُ وَلَيْسَ لِلْحِيطَانِ ظِلٌّ نَسْتَظِلُّ بِهِ». وَفِي لَفْظٍ: «كُنَّا نُجَمِّعُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا زَالَتِ الشَّمْسُ، ثُمَّ نَرْجِعُ فَنَتَّبِعُ الفَيْءَ»."]]},{"id":"um28_10","label":"الحديث ١٣٧","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي صَلَاةِ الفَجْرِ يَوْمَ الجُمُعَةِ: ﴿الم * تَنْزِيلُ﴾ السَّجْدَةَ، وَ ﴿هَلْ أَتَى عَلَى الإِنْسَانِ﴾»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um29","title":"بَابُ العِيدَيْنِ","units":[{"id":"um29_1","label":"الحديث ١٣٨","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ وَعُمَرُ رَضِيَ اللَّهُ عَنْهُمَا يُصَلُّونَ العِيدَيْنِ قَبْلَ الخُطْبَةِ»."]]},{"id":"um29_2","label":"الحديث ١٣٩ · المقطع ١ من ٣","segs":[["rawi","عَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«خَطَبَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الأَضْحَى بَعْدَ الصَّلَاةِ، فَقَالَ: مَنْ صَلَّى صَلَاتَنَا وَنَسَكَ نُسُكَنَا؛ فَقَدْ أَصَابَ النُّسُكَ، وَمَنْ نَسَكَ قَبْلَ الصَّلَاةِ؛ فَلَا نُسُكَ لَهُ،"]]},{"id":"um29_3","label":"الحديث ١٣٩ · المقطع ٢ من ٣","segs":[["matn","فَقَالَ أَبُو بُرْدَةَ بْنُ نِيَارٍ - خَالُ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمْ -: يَا رَسُولَ اللَّهِ! إِنِّي نَسَكْتُ شَاتِي قَبْلَ الصَّلَاةِ وَعَرَفْتُ أَنَّ اليَوْمَ يَوْمُ أَكْلٍ وَشُرْبٍ،"]]},{"id":"um29_4","label":"الحديث ١٣٩ · المقطع ٣ من ٣","segs":[["matn","وَأَحْبَبْتُ أَنْ تَكُونَ شَاتِي أَوَّلَ مَا يُذْبَحُ فِي بَيْتِي، فَذَبَحْتُ شَاتِي، وَتَغَدَّيْتُ قَبْلَ أَنْ آتِيَ الصَّلَاةَ، فَقَالَ: شَاتُكَ شَاةُ لَحْمٍ، قَالَ: يَا رَسُولَ اللَّهِ! فَإِنَّ عِنْدِي عَنَاقاً هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْنِ؛ أَفَتَجْزِي عَنِّي؟ قَالَ: نَعَمْ، وَلَنْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ»."]]},{"id":"um29_5","label":"الحديث ١٤٠","segs":[["rawi","عَنْ جُنْدُبِ بْنِ عَبْدِ اللَّهِ البَجَلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«صَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ، ثُمَّ خَطَبَ، ثُمَّ ذَبَحَ، وَقَالَ: مَنْ ذَبَحَ قَبْلَ أَنْ يُصَلِّيَ؛ فَلْيَذْبَحْ أُخْرَى مَكَانَهَا، وَمَنْ لَمْ يَذْبَحْ؛ فَلْيَذْبَحْ بِاسْمِ اللَّهِ»."]]},{"id":"um29_6","label":"الحديث ١٤١ · المقطع ١ من ٣","segs":[["rawi","عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«شَهِدْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ العِيدِ؛ فَبَدَأَ بِالصَّلَاةِ قَبْلَ الخُطْبَةِ بِلَا أَذَانٍ وَلَا إِقَامَةٍ، ثُمَّ قَامَ مُتَوَكِّئاً عَلَى بِلَالٍ، فَأَمَرَ بِتَقْوَى اللَّهِ وَحَثَّ عَلَى طَاعَتِهِ، وَوَعَظَ النَّاسَ وَذَكَّرَهُمْ،"]]},{"id":"um29_7","label":"الحديث ١٤١ · المقطع ٢ من ٣","segs":[["matn","ثُمَّ مَضَى حَتَّى أَتَى النِّسَاءَ فَوَعَظَهُنَّ وَذَكَّرَهُنَّ، وَقَالَ: تَصَدَّقْنَ؛ فَإِنَّكُنَّ أَكْثَرُ حَطَبِ جَهَنَّمَ، فَقَامَتِ امْرَأَةٌ مِنْ سِطَةِ النِّسَاءِ سَفْعَاءُ الخَدَّيْنِ، فَقَالَتْ: لِمَ يَا رَسُولَ اللَّهِ؟! قَالَ: لِأَنَّكُنَّ تُكْثِرْنَ الشَّكَاةَ، وَتَكْفُرْنَ العَشِيرَ، قَالَ:"]]},{"id":"um29_8","label":"الحديث ١٤١ · المقطع ٣ من ٣","segs":[["matn","فَجَعَلْنَ يَتَصَدَّقْنَ مِنْ حُلِيِّهِنَّ، يُلْقِينَ فِي ثَوْبِ بِلَالٍ مِنْ أَقْرِطَتِهِنَّ وَخَوَاتِيمِهِنَّ»."]]},{"id":"um29_9","label":"الحديث ١٤٢ · المقطع ١ من ٢","segs":[["rawi","عَنْ أُمِّ عَطِيَّةَ نُسَيْبَةَ الأَنْصَارِيَّةِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«أَمَرَنَا - تَعْنِي: النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَنْ نُخْرِجَ فِي العِيدَيْنِ: العَوَاتِقَ وَذَوَاتِ الخُدُورِ، وَأَمَرَ الحُيَّضَ أَنْ يَعْتَزِلْنَ مُصَلَّى المُسْلِمِينَ». وَفِي لَفْظٍ: «كُنَّا نُؤْمَرُ أَنْ نَخْرُجَ يَوْمَ العِيدِ، حَتَّى تَخْرُجَ البِكْرُ مِنْ خِدْرِهَا،"]]},{"id":"um29_10","label":"الحديث ١٤٢ · المقطع ٢ من ٢","segs":[["matn","حَتَّى تَخْرُجَ الحُيَّضُ، فَيُكَبِّرْنَ بِتَكْبِيرِهِمْ، وَيَدْعُونَ بِدُعَائِهِمْ؛ يَرْجُونَ بَرَكَةَ ذَلِكَ اليَوْمِ وَطُهْرَتَهُ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um30","title":"بَابُ صَلَاةِ الكُسُوفِ","units":[{"id":"um30_1","label":"الحديث ١٤٣","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ الشَّمْسَ خَسَفَتْ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَعَثَ مُنَادِياً يُنَادِي: الصَّلَاةَ جَامِعَةً؛ فَاجْتَمَعُوا، وَتَقَدَّمَ فَكَبَّرَ، وَصَلَّى أَرْبَعَ رَكَعَاتٍ فِي رَكْعَتَيْنِ، وَأَرْبَعَ سَجَدَاتٍ»."]]},{"id":"um30_2","label":"الحديث ١٤٤","segs":[["rawi","عَنْ أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو الأَنْصَارِيِّ البَدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«إِنَّ الشَّمْسَ وَالقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، يُخَوِّفُ اللَّهُ بِهِمَا عِبَادَهُ، وَإِنَّهُمَا لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ مِنَ النَّاسِ، فَإِذَا رَأَيْتُمْ مِنْهَا شَيْئاً: فَصَلُّوا وَادْعُوا حَتَّى يَنْكَشِفَ مَا بِكُمْ»."]]},{"id":"um30_3","label":"الحديث ١٤٥ · المقطع ١ من ٤","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«خَسَفَتِ الشَّمْسُ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّاسِ، فَأَطَالَ القِيَامَ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ قَامَ فَأَطَالَ القِيَامَ - وَهُوَ دُونَ القِيَامِ الأَوَّلِ -،"]]},{"id":"um30_4","label":"الحديث ١٤٥ · المقطع ٢ من ٤","segs":[["matn","ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ - وَهُوَ دُونَ الرُّكُوعِ الأَوَّلِ -، ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ، ثُمَّ فَعَلَ فِي الرَّكْعَةِ الأُخْرَى مِثْلَ مَا فَعَلَ فِي الرَّكْعَةِ الأُولَى، ثُمَّ انْصَرَفَ وَقَدْ تَجَلَّتِ الشَّمْسُ، فَخَطَبَ النَّاسَ،"]]},{"id":"um30_5","label":"الحديث ١٤٥ · المقطع ٣ من ٤","segs":[["matn","فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: إِنَّ الشَّمْسَ وَالقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ؛ فَادْعُوا اللَّهَ، وَكَبِّرُوا، وَصَلُّوا، وَتَصَدَّقُوا، ثُمَّ قَالَ: يَا أُمَّةَ مُحَمَّدٍ! وَاللَّهِ!"]]},{"id":"um30_6","label":"الحديث ١٤٥ · المقطع ٤ من ٤","segs":[["matn","مَا مِنْ أَحَدٍ أَغْيَرُ مِنَ اللَّهِ أَنْ يَزْنِيَ عَبْدُهُ، أَوْ تَزْنِيَ أَمَتُهُ، يَا أُمَّةَ مُحَمَّدٍ! وَاللَّهِ! لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلاً وَلَبَكَيْتُمْ كَثِيراً». وَفِي لَفْظٍ: «فَاسْتَكْمَلَ أَرْبَعَ رَكَعَاتٍ وَأَرْبَعَ سَجَدَاتٍ»."]]},{"id":"um30_7","label":"الحديث ١٤٦ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«خَسَفَتِ الشَّمْسُ فِي زَمَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ فَزِعاً يَخْشَى أَنْ تَكُونَ السَّاعَةُ، حَتَّى أَتَى المَسْجِدَ، فَقَامَ فَصَلَّى بِأَطْوَلِ قِيَامٍ وَرُكُوعٍ وَسُجُودٍ، مَا رَأَيْتُهُ يَفْعَلُهُ فِي صَلَاةٍ قَطُّ، ثُمَّ قَالَ:"]]},{"id":"um30_8","label":"الحديث ١٤٦ · المقطع ٢ من ٢","segs":[["matn","إِنَّ هَذِهِ الآيَاتِ الَّتِي يُرْسِلُهَا اللَّهُ لَا تَكُونُ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، وَلَكِنَّ اللَّهَ عَزَّ وَجَلَّ يُرْسِلُهَا يُخَوِّفُ بِهَا عِبَادَهُ؛ فَإِذَا رَأَيْتُمْ مِنْهَا شَيْئاً؛ فَافْزَعُوا إِلَى ذِكْرِهِ، وَدُعَائِهِ، وَاسْتِغْفَارِهِ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um31","title":"بَابُ الِاسْتِسْقَاءِ","units":[{"id":"um31_1","label":"الحديث ١٤٧","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ المَازِنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَسْقِي، فَتَوَجَّهَ إِلَى القِبْلَةِ يَدْعُو، وَحَوَّلَ رِدَاءَهُ، ثُمَّ صَلَّى رَكْعَتَيْنِ، جَهَرَ فِيهِمَا بِالقِرَاءَةِ». وَفِي لَفْظٍ: «إِلَى المُصَلَّى»."]]},{"id":"um31_2","label":"الحديث ١٤٨ · المقطع ١ من ٥","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَجُلاً دَخَلَ المَسْجِدَ يَوْمَ الجُمُعَةِ مِنْ بَابٍ كَانَ نَحْوَ دَارِ القَضَاءِ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يَخْطُبُ، فَاسْتَقْبَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِماً، ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ! هَلَكَتِ الأَمْوَالُ،"]]},{"id":"um31_3","label":"الحديث ١٤٨ · المقطع ٢ من ٥","segs":[["matn","وَانْقَطَعَتِ السُّبُلُ، فَادْعُ اللَّهَ يُغِثْنَا، قَالَ: فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ ثُمَّ قَالَ: اللَّهُمَّ أَغِثْنَا! اللَّهُمَّ أَغِثْنَا! اللَّهُمَّ أَغِثْنَا! قَالَ أَنَسٌ: وَلَا وَاللَّهِ! مَا نَرَى فِي السَّمَاءِ مِنْ سَحَابٍ وَلَا قَزَعَةٍ،"]]},{"id":"um31_4","label":"الحديث ١٤٨ · المقطع ٣ من ٥","segs":[["matn","وَمَا بَيْنَنَا وَبَيْنَ سَلْعٍ مِنْ بَيْتٍ وَلَا دَارٍ، قَالَ: فَطَلَعَتْ مِنْ وَرَائِهِ سَحَابَةٌ مِثْلُ التُّرْسِ، فَلَمَّا تَوَسَّطَتِ السَّمَاءَ انْتَشَرَتْ ثُمَّ أَمْطَرَتْ، قَالَ: فَلَا وَاللَّهِ! مَا رَأَينَا الشَّمْسَ سَبْتاً، قَالَ:"]]},{"id":"um31_5","label":"الحديث ١٤٨ · المقطع ٤ من ٥","segs":[["matn","ثُمَّ دَخَلَ رَجُلٌ مِنْ ذَلِكَ البَابِ فِي الجُمُعَةِ المُقْبِلَةِ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يَخْطُبُ، فَاسْتَقْبَلَهُ قَائِماً فَقَالَ: يَا رَسُولَ اللَّهِ! هَلَكَتِ الأَمْوَالُ وَانْقَطَعَتِ السُّبُلُ؛ فَادْعُ اللَّهَ يُمْسِكْهَا عَنَّا، قَالَ:"]]},{"id":"um31_6","label":"الحديث ١٤٨ · المقطع ٥ من ٥","segs":[["matn","فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ ثُمَّ قَالَ: اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا، اللَّهُمَّ عَلَى الآكَامِ، وَالظِّرَابِ، وَبُطُونِ الأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ، قَالَ: فَأَقْلَعَتْ، وَخَرَجْنَا نَمْشِي فِي الشَّمْسِ. قَالَ شَرِيكٌ: فَسَأَلْتُ أَنَسَ بْنَ مَالِكٍ: أَهُوَ الرَّجُلُ الأَوَّلُ؟ قَالَ: لَا أَدْرِي»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um32","title":"بَابُ صَلَاةِ الخَوْفِ","units":[{"id":"um32_1","label":"الحديث ١٤٩","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الخَوْفِ فِي بَعْضِ أَيَّامِهِ، فَقَامَتْ طَائِفَةٌ مَعَهُ، وَطَائِفَةٌ بِإِزَاءِ العَدُوِّ، فَصَلَّى بِالَّذِينَ مَعَهُ رَكْعَةً، ثُمَّ ذَهَبُوا، وَجَاءَ الآخَرُونَ فَصَلَّى بِهِمْ رَكْعَةً، وَقَضَتِ الطَّائِفَتَانِ رَكْعَةً رَكْعَةً»."]]},{"id":"um32_2","label":"الحديث ١٥٠","segs":[["rawi","عَنْ يَزِيدَ بْنِ رُومَانَ، عَنْ صَالِحِ بْنِ خَوَّاتِ بْنِ جُبَيْرٍ، عَمَّنْ صَلَّى مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ ذَاتِ الرِّقَاعِ؛ صَلَاةَ الخَوْفِ:"],["matn","«أَنَّ طَائِفَةً صَفَّتْ مَعَهُ، وَطَائِفَةٌ وِجَاهَ العَدُوِّ، فَصَلَّى بِالَّذِينَ مَعَهُ رَكْعَةً، ثُمَّ ثَبَتَ قَائِماً، وَأَتَمُّوا لِأَنْفُسِهِمْ، ثُمَّ انْصَرَفُوا فَصَفُّوا وِجَاهَ العَدُوِّ، وَجَاءَتِ الطَّائِفَةُ الأُخْرَى، فَصَلَّى بِهِمُ الرَّكْعَةَ الَّتِي بَقِيَتْ، ثُمَّ ثَبَتَ جَالِساً، وَأَتَمُّوا لِأَنْفُسِهِمْ، ثُمَّ سَلَّمَ بِهِمْ»."]]},{"id":"um32_3","label":"الحديث ١٥١ · المقطع ١ من ٦","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الخَوْفِ، فَصَفَفْنَا صَفَّيْنِ خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَالعَدُوُّ بَيْنَنَا وَبَيْنَ القِبْلَةِ، فَكَبَّرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَبَّرْنَا جَمِيعاً، ثُمَّ رَكَعَ وَرَكَعْنَا جَمِيعاً،"]]},{"id":"um32_4","label":"الحديث ١٥١ · المقطع ٢ من ٦","segs":[["matn","ثُمَّ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ وَرَفَعْنَا جَمِيعاً، ثُمَّ انْحَدَرَ بِالسُّجُودِ وَالصَّفُّ الَّذِي يَلِيهِ، وَقَامَ الصَّفُّ المُؤَخَّرُ فِي نَحْرِ العَدُوِّ، فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السُّجُودَ، وَقَامَ الصَّفُّ الَّذِي يَلِيهِ: انْحَدَرَ الصَّفُّ المُؤَخَّرُ بِالسُّجُودِ،"]]},{"id":"um32_5","label":"الحديث ١٥١ · المقطع ٣ من ٦","segs":[["matn","وَقَامُوا، ثُمَّ تَقَدَّمَ الصَّفُّ المُؤَخَّرُ، وَتَأَخَّرَ الصَّفُّ المُقَدَّمُ، ثُمَّ رَكَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَكَعْنَا جَمِيعاً، ثُمَّ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فَرَفَعْنَا جَمِيعاً،"]]},{"id":"um32_6","label":"الحديث ١٥١ · المقطع ٤ من ٦","segs":[["matn","ثُمَّ انْحَدَرَ بِالسُّجُودِ وَالصَّفُّ الَّذِي يَلِيهِ - الَّذِي كَانَ مُؤَخَّراً فِي الرَّكْعَةِ الأُولَى -، فَقَامَ الصَّفُّ المُؤَخَّرُ فِي نُحُورِ العَدُوِّ، فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السُّجُودَ وَالصَّفُّ الَّذِي يَلِيهِ؛"]]},{"id":"um32_7","label":"الحديث ١٥١ · المقطع ٥ من ٦","segs":[["matn","انْحَدَرَ الصَّفُّ المُؤَخَّرُ بِالسُّجُودِ فَسَجَدُوا، ثُمَّ سَلَّمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَلَّمْنَا جَمِيعاً، قَالَ جَابِرٌ: كَمَا يَصْنَعُ حَرَسُكُمْ هَؤُلَاءِ بِأُمَرَائِهِمْ». وَذَكَرَ البُخَارِيُّ طَرَفاً مِنْهُ:"]]},{"id":"um32_8","label":"الحديث ١٥١ · المقطع ٦ من ٦","segs":[["matn","«وَأَنَّهُ صَلَّى صَلَاةَ الخَوْفِ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الغَزْوَةِ السَّابِعَةِ؛ غَزْوَةِ ذَاتِ الرِّقَاعِ»."],["takh","ذَكَرَهُ مُسْلِمٌ بِتَمَامِهِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um33","title":"كِتَابُ الجَنَائِزِ","units":[{"id":"um33_1","label":"الحديث ١٥٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«نَعَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّجَاشِيَّ فِي اليَوْمِ الَّذِي مَاتَ فِيهِ، وَخَرَجَ بِهِمْ إِلَى المُصَلَّى، فَصَفَّ بِهِمْ، وَكَبَّرَ أَرْبَعاً»."]]},{"id":"um33_2","label":"الحديث ١٥٣","segs":[["rawi","عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى النَّجَاشِيِّ؛ فَكُنْتُ فِي الصَّفِّ الثَّانِي أَوِ الثَّالِثِ»."]]},{"id":"um33_3","label":"الحديث ١٥٤","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى قَبْرٍ بَعْدَمَا دُفِنَ، فَكَبَّرَ عَلَيْهِ أَرْبَعاً»."]]},{"id":"um33_4","label":"الحديث ١٥٥","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُفِّنَ فِي ثَلَاثَةِ أَثْوَابٍ يَمَانِيَةٍ بِيضٍ، لَيْسَ فِيهَا قَمِيصٌ وَلَا عِمَامَةٌ»."]]},{"id":"um33_5","label":"الحديث ١٥٦ · المقطع ١ من ٣","segs":[["rawi","عَنْ أُمِّ عَطِيَّةَ الأَنْصَارِيَّةِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ تُوُفِّيَتِ ابْنَتُهُ، فَقَالَ: اغْسِلْنَهَا ثَلَاثاً، أَوْ خَمْساً، أَوْ أَكْثَرَ مِنْ ذَلِكِ - إِنْ رَأَيْتُنَّ ذَلِكِ -، بِمَاءٍ وَسِدْرٍ،"]]},{"id":"um33_6","label":"الحديث ١٥٦ · المقطع ٢ من ٣","segs":[["matn","وَاجْعَلْنَ فِي الآخِرَةِ كَافُوراً - أَوْ شَيْئاً مِنْ كَافُورٍ -، فَإِذَا فَرَغْتُنَّ فَآذِنَّنِي، فَلَمَّا فَرَغْنَا آذَنَّاهُ، فَأَعْطَانَا حَقْوَهُ، فَقَالَ: أَشْعِرْنَهَا بِهِ - تَعْنِي: إِزَارَهُ -». وَفِي رِوَايَةٍ: «أَوْ سَبْعاً». وَقَالَ: «ابْدَأْنَ بِمَيَامِنِهَا وَمَوَاضِعِ الوُضُوءِ مِنْهَا»."]]},{"id":"um33_7","label":"الحديث ١٥٦ · المقطع ٣ من ٣","segs":[["matn","وَأَنَّ أُمَّ عَطِيَّةَ قَالَتْ: «وَجَعَلْنَا رَأْسَهَا ثَلَاثَةَ قُرُونٍ»."]]},{"id":"um33_8","label":"الحديث ١٥٧ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«بَيْنَمَا رَجُلٌ وَاقِفٌ بِعَرَفَةَ، إِذْ وَقَعَ عَنْ رَاحِلَتِهِ فَوَقَصَتْهُ - أَوْ قَالَ: فَأَوْقَصَتْهُ -، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اغْسِلُوهُ بِمَاءٍ وَسِدْرٍ، وَكَفِّنُوهُ فِي ثَوْبَيْنِ، وَلَا تُحَنِّطُوهُ، وَلَا تُخَمِّرُوا رَأْسَهُ؛"]]},{"id":"um33_9","label":"الحديث ١٥٧ · المقطع ٢ من ٢","segs":[["matn","فَإِنَّهُ يُبْعَثُ يَوْمَ القِيَامَةِ مُلَبِّياً». وَفِي رِوَايَةٍ: «وَلَا تُخَمِّرُوا وَجْهَهُ، وَلَا رَأْسَهُ»."]]},{"id":"um33_10","label":"الحديث ١٥٨","segs":[["rawi","عَنْ أُمِّ عَطِيَّةَ الأَنْصَارِيَّةِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«نُهِينَا عَنِ اتِّبَاعِ الجَنَائِزِ، وَلَمْ يُعْزَمْ عَلَيْنَا»."]]},{"id":"um33_11","label":"الحديث ١٥٩","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«أَسْرِعُوا بِالجِنَازَةِ؛ فَإِنْ تَكُ صَالِحَةً فَخَيْرٌ تُقَدِّمُونَهَا إِلَيْهِ، وَإِنْ تَكُ سِوَى ذَلِكَ فَشَرٌّ تَضَعُونَهُ عَنْ رِقَابِكُمْ»."]]},{"id":"um33_12","label":"الحديث ١٦٠","segs":[["rawi","عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«صَلَّيْتُ وَرَاءَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى امْرَأَةٍ مَاتَتْ فِي نِفَاسِهَا؛ فَقَامَ وَسْطَهَا»."]]},{"id":"um33_13","label":"الحديث ١٦١","segs":[["rawi","عَنْ أَبِي مُوسَى عَبْدِ اللَّهِ بْنِ قَيْسٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَرِئَ مِنَ الصَّالِقَةِ وَالحَالِقَةِ وَالشَّاقَّةِ»."]]},{"id":"um33_14","label":"الحديث ١٦٢ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«لَمَّا اشْتَكَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَكَرَ بَعْضُ نِسَائِهِ كَنِيسَةً رَأَيْنَهَا بِأَرْضِ الحَبَشَةِ يُقَالُ لَهَا: مَارِيَةُ، وَكَانَتْ أُمُّ سَلَمَةَ وَأُمُّ حَبِيبَةَ أَتَتَا أَرْضَ الحَبَشَةِ؛ فَذَكَرَتَا مِنْ حُسْنِهَا وَتَصَاوِيرَ فِيهَا، فَرَفَعَ رَأْسَهُ فَقَالَ:"]]},{"id":"um33_15","label":"الحديث ١٦٢ · المقطع ٢ من ٢","segs":[["matn","أُولَئِكِ إِذَا مَاتَ فِيهِمُ الرَّجُلُ الصَّالِحُ بَنَوْا عَلَى قَبْرِهِ مَسْجِداً، ثُمَّ صَوَّرُوا فِيهِ تِلْكَ الصُّورَةَ، أُولَئِكِ شِرَارُ الخَلْقِ عِنْدَ اللَّهِ»."]]},{"id":"um33_16","label":"الحديث ١٦٣","segs":[["rawi","وَعَنْهَا رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فِي مَرَضِهِ الَّذِي لَمْ يَقُمْ مِنْهُ -: لَعَنَ اللَّهُ اليَهُودَ وَالنَّصَارَى اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ، قَالَتْ: وَلَوْلَا ذَلِكَ أُبْرِزَ قَبْرُهُ؛ غَيْرَ أَنَّهُ خُشِيَ أَنْ يُتَّخَذَ مَسْجِداً»."]]},{"id":"um33_17","label":"الحديث ١٦٤","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَيْسَ مِنَّا مَنْ ضَرَبَ الخُدُودَ، وَشَقَّ الجُيُوبَ، وَدَعَا بِدَعْوَى الجَاهِلِيَّةِ»."]]},{"id":"um33_18","label":"الحديث ١٦٥","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«مَنْ شَهِدَ الجِنَازَةَ حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَهَا حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ، قِيلَ: وَمَا القِيرَاطَانِ؟ قَالَ: مِثْلُ الجَبَلَيْنِ العَظِيمَيْنِ». وَلِمُسْلِمٍ: «أَصْغَرُهُمَا مِثْلُ أُحُدٍ»."]]}],"group":"كِتَابُ الجَنَائِزِ"},{"id":"um34","title":"كِتَابُ الزَّكَاةِ","units":[{"id":"um34_1","label":"الحديث ١٦٦ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ - حِينَ بَعَثَهُ إِلَى اليَمَنِ -: «إِنَّكَ سَتَأْتِي قَوْماً أَهْلَ كِتَابٍ؛ فَإِذَا جِئْتَهُمْ فَادْعُهُمْ إِلَى أَنْ يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ،"]]},{"id":"um34_2","label":"الحديث ١٦٦ · المقطع ٢ من ٣","segs":[["matn","وَأَنَّ مُحَمَّداً رَسُولُ اللَّهِ؛ فَإِنْ هُمْ أَطَاعُوا لَكَ بِذَلِكَ؛ فَأَخْبِرْهُمْ أَنَّ اللَّهَ قَدْ فَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ؛ فَإِنْ هُمْ أَطَاعُوا لَكَ بِذَلِكَ؛"]]},{"id":"um34_3","label":"الحديث ١٦٦ · المقطع ٣ من ٣","segs":[["matn","فَأَخْبِرْهُمْ أَنَّ اللَّهَ قَدْ فَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ؛ فَإِنْ هُمْ أَطَاعُوا لَكَ بِذَلِكَ؛ فَإِيَّاكَ وَكَرَائِمَ أَمْوَالِهِمْ، وَاتَّقِ دَعْوَةَ المَظْلُومِ؛ فَإِنَّهَا لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ»."]]},{"id":"um34_4","label":"الحديث ١٦٧","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَيْسَ فِيمَا دُونَ خَمْسِ أَوَاقٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسِ ذَوْدٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ صَدَقَةٌ»."]]},{"id":"um34_5","label":"الحديث ١٦٨","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَيْسَ عَلَى المُسْلِمِ فِي عَبْدِهِ وَلَا فَرَسِهِ صَدَقَةٌ». وَفِي لَفْظٍ: «إِلَّا زَكَاةَ الفِطْرِ فِي الرَّقِيقِ»."]]},{"id":"um34_6","label":"الحديث ١٦٩","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«العَجْمَاءُ جُبَارٌ، وَالبِئْرُ جُبَارٌ، وَالمَعْدِنُ جُبَارٌ، وَفِي الرِّكَازِ الخُمُسُ»."]]},{"id":"um34_7","label":"الحديث ١٧٠ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عُمَرَ رَضِيَ اللَّهُ عَنْهُ عَلَى الصَّدَقَةِ، فَقِيلَ: مَنَعَ ابْنُ جَمِيلٍ وَخَالِدُ بْنُ الوَلِيدِ وَالعَبَّاسُ - عَمُّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -،"]]},{"id":"um34_8","label":"الحديث ١٧٠ · المقطع ٢ من ٣","segs":[["matn","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا يَنْقِمُ ابْنُ جَمِيلٍ إِلَّا أَنْ كَانَ فَقِيراً فَأَغْنَاهُ اللَّهُ؟ وَأَمَّا خَالِدٌ؛ فَإِنَّكُمْ تَظْلِمُونَ خَالِداً؛ وَقَدِ احْتَبَسَ أَدْرَاعَهُ وَأَعْتَادَهُ فِي سَبِيلِ اللَّهِ، وَأَمَّا العَبَّاسُ؛ فَهِيَ عَلَيَّ وَمِثْلُهَا،"]]},{"id":"um34_9","label":"الحديث ١٧٠ · المقطع ٣ من ٣","segs":[["matn","ثُمَّ قَالَ: يَا عُمَرُ! أَمَا شَعَرْتَ أَنَّ عَمَّ الرَّجُلِ صِنْوُ أَبِيهِ؟»."]]},{"id":"um34_10","label":"الحديث ١٧١ · المقطع ١ من ٤","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«لَمَّا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ حُنَيْنٍ؛ قَسَمَ فِي النَّاسِ وَفِي المُؤَلَّفَةِ قُلُوبُهُمْ، وَلَمْ يُعْطِ الأَنْصَارَ شَيْئاً، فَكَأَنَّهُمْ وَجَدُوا؛ إِذْ لَمْ يُصِبْهُمْ مَا أَصَابَ النَّاسَ، فَخَطَبَهُمْ فَقَالَ: يَا مَعْشَرَ الأَنْصَارِ!"]]},{"id":"um34_11","label":"الحديث ١٧١ · المقطع ٢ من ٤","segs":[["matn","أَلَمْ أَجِدْكُمْ ضُلَّالاً فَهَدَاكُمُ اللَّهُ بِي؟ وَكُنْتُمْ مُتَفَرِّقِينَ فَأَلَّفَكُمُ اللَّهُ بِي؟ وَعَالَةً فَأَغْنَاكُمُ اللَّهُ بِي؟ كُلَّمَا قَالَ شَيْئاً قَالُوا: اللَّهُ وَرَسُولُهُ أَمَنُّ، قَالَ: مَا يَمْنَعُكُمْ أَنْ تُجِيبُوا رَسُولَ اللَّهِ؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَمَنُّ، قَالَ:"]]},{"id":"um34_12","label":"الحديث ١٧١ · المقطع ٣ من ٤","segs":[["matn","لَوْ شِئْتُمْ لَقُلْتُمْ: جِئْتَنَا كَذَا وَكَذَا، أَلَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالشَّاةِ وَالبَعِيرِ، وَتَذْهَبُونَ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى رِحَالِكُمْ؟ لَوْلَا الهِجْرَةُ لَكُنْتُ امْرَأً مِنَ الأَنْصَارِ،"]]},{"id":"um34_13","label":"الحديث ١٧١ · المقطع ٤ من ٤","segs":[["matn","وَلَوْ سَلَكَ النَّاسُ وَادِياً وَشِعْباً لَسَلَكْتُ وَادِيَ الأَنْصَارِ وَشِعْبَهَا، الأَنْصَارُ شِعَارٌ، وَالنَّاسُ دِثَارٌ، إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي أَثَرَةً؛ فَاصْبِرُوا حَتَّى تَلْقَوْنِي عَلَى الحَوْضِ»."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um35","title":"بَابُ صَدَقَةِ الفِطْرِ","units":[{"id":"um35_1","label":"الحديث ١٧٢ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«فَرَضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَدَقَةَ الفِطْرِ - أَوْ قَالَ: رَمَضَانَ - عَلَى الذَّكَرِ وَالأُنْثَى، وَالحُرِّ وَالمَمْلُوكِ؛ صَاعاً مِنْ تَمْرٍ، أَوْ صَاعاً مِنْ شَعِيرٍ، فَعَدَلَ النَّاسُ بِهِ نِصْفَ صَاعٍ مِنْ بُرٍّ، عَلَى الصَّغِيرِ وَالكَبِيرِ»."]]},{"id":"um35_2","label":"الحديث ١٧٢ · المقطع ٢ من ٢","segs":[["matn","وَفِي لَفْظٍ: «أَنْ تُؤَدَّى قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلَاةِ»."]]},{"id":"um35_3","label":"الحديث ١٧٣ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كُنَّا نُعْطِيهَا فِي زَمَانِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَاعاً مِنْ طَعَامٍ، أَوْ صَاعاً مِنْ تَمْرٍ، أَوْ صَاعاً مِنْ شَعِيرٍ، أَوْ صَاعاً مِنْ أَقِطٍ، أَوْ صَاعاً مِنْ زَبِيبٍ، فَلَمَّا جَاءَ مُعَاوِيَةُ - وَجَاءَتِ السَّمْرَاءُ -؛"]]},{"id":"um35_4","label":"الحديث ١٧٣ · المقطع ٢ من ٢","segs":[["matn","قَالَ: أَرَى مُدّاً مِنْ هَذَا يَعْدِلُ مُدَّيْنِ، قَالَ أَبُو سَعِيدٍ: أَمَّا أَنَا؛ فَلَا أَزَالُ أُخْرِجُهُ كَمَا كُنْتُ أُخْرِجُهُ»."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um36","title":"كِتَابُ الصِّيَامِ","units":[{"id":"um36_1","label":"الحديث ١٧٤","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَا تَقَدَّمُوا رَمَضَانَ بِصَوْمِ يَوْمٍ وَلَا يَوْمَيْنِ؛ إِلَّا رَجُلاً كَانَ يَصُومُ صَوْماً فَلْيَصُمْهُ»."]]},{"id":"um36_2","label":"الحديث ١٧٥","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"],["matn","«إِذَا رَأَيْتُمُوهُ فَصُومُوا، وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا، فَإِنْ غُمَّ عَلَيْكُمْ فَاقْدُرُوا لَهُ»."]]},{"id":"um36_3","label":"الحديث ١٧٦","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً»."]]},{"id":"um36_4","label":"الحديث ١٧٧","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ، عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«تَسَحَّرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَامَ إِلَى الصَّلَاةِ. قَالَ أَنَسٌ: قُلْتُ لِزَيْدٍ: كَمْ كَانَ بَيْنَ الأَذَانِ وَالسَّحُورِ؟ قَالَ: قَدْرُ خَمْسِينَ آيَةً»."]]},{"id":"um36_5","label":"الحديث ١٧٨","segs":[["rawi","عَنْ عَائِشَةَ، وَأُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُدْرِكُهُ الفَجْرُ وَهُوَ جُنُبٌ مِنْ أَهْلِهِ، ثُمَّ يَغْتَسِلُ وَيَصُومُ»."]]},{"id":"um36_6","label":"الحديث ١٧٩","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ نَسِيَ وَهُوَ صَائِمٌ فَأَكَلَ أَوْ شَرِبَ؛ فَلْيُتِمَّ صَوْمَهُ، فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ»."]]},{"id":"um36_7","label":"الحديث ١٨٠ · المقطع ١ من ٤","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ رَجُلٌ، فَقَالَ: يَا رَسُولَ اللَّهِ! هَلَكْتُ! قَالَ: مَا لَكَ؟ قَالَ: وَقَعْتُ عَلَى امْرَأَتِي وَأَنَا صَائِمٌ - وَفِي رِوَايَةٍ: أَصَبْتُ أَهْلِي فِي رَمَضَانَ -،"]]},{"id":"um36_8","label":"الحديث ١٨٠ · المقطع ٢ من ٤","segs":[["matn","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ تَجِدُ رَقَبَةً تُعْتِقُهَا؟ قَالَ: لَا، قَالَ: فَهَلْ تَسْتَطِيعُ أَنْ تَصُومَ شَهْرَيْنِ مُتَتَابِعَيْنِ؟ قَالَ: لَا، قَالَ: فَهَلْ تَجِدُ إِطْعَامَ سِتِّينَ مِسْكِيناً؟ قَالَ: لَا،"]]},{"id":"um36_9","label":"الحديث ١٨٠ · المقطع ٣ من ٤","segs":[["matn","فَمَكَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَبَيْنَا نَحْنُ عَلَى ذَلِكَ أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَرَقٍ فِيهِ تَمْرٌ - وَالعَرَقُ: المِكْتَلُ -؛ قَالَ: أَيْنَ السَّائِلُ؟ فَقَالَ: أَنَا، قَالَ: خُذْ هَذَا فَتَصَدَّقْ بِهِ، فَقَالَ الرَّجُلُ:"]]},{"id":"um36_10","label":"الحديث ١٨٠ · المقطع ٤ من ٤","segs":[["matn","عَلَى أَفْقَرَ مِنِّي يَا رَسُولَ اللَّهِ؟ فَوَاللَّهِ! مَا بَيْنَ لَابَتَيْهَا - يُرِيدُ الحَرَّتَيْنِ - أَهْلُ بَيْتٍ أَفْقَرُ مِنْ أَهْلِ بَيْتِي، فَضَحِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدَتْ أَنْيَابُهُ، ثُمَّ قَالَ: أَطْعِمْهُ أَهْلَكَ»."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um37","title":"بَابُ الصَّوْمِ فِي السَّفَرِ وَغَيْرِهِ","units":[{"id":"um37_1","label":"الحديث ١٨١","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ حَمْزَةَ بْنَ عَمْرٍو الأَسْلَمِيَّ رَضِيَ اللَّهُ عَنْهُ قَالَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَصُومُ فِي السَّفَرِ؟ - وَكَانَ كَثِيرَ الصِّيَامِ - فَقَالَ: إِنْ شِئْتَ فَصُمْ، وَإِنْ شِئْتَ فَأَفْطِرْ»."]]},{"id":"um37_2","label":"الحديث ١٨٢","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كُنَّا نُسَافِرُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَعِبِ الصَّائِمُ عَلَى المُفْطِرِ، وَلَا المُفْطِرُ عَلَى الصَّائِمِ»."]]},{"id":"um37_3","label":"الحديث ١٨٣ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شَهْرِ رَمَضَانَ فِي حَرٍّ شَدِيدٍ؛ حَتَّى إِنْ كَانَ أَحَدُنَا لَيَضَعُ يَدَهُ عَلَى رَأْسِهِ مِنْ شِدَّةِ الحَرِّ،"]]},{"id":"um37_4","label":"الحديث ١٨٣ · المقطع ٢ من ٢","segs":[["matn","وَمَا فِينَا صَائِمٌ إِلَّا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَبْدُ اللَّهِ بْنُ رَوَاحَةَ»."]]},{"id":"um37_5","label":"الحديث ١٨٤","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَرَأَى زِحَاماً وَرَجُلاً قَدْ ظُلِّلَ عَلَيْهِ، فَقَالَ: مَا هَذَا؟ فَقَالُوا: صَائِمٌ، فَقَالَ: لَيْسَ مِنَ البِرِّ الصَّوْمُ فِي السَّفَرِ». وَلِمُسْلِمٍ: «عَلَيْكُمْ بِرُخْصَةِ اللَّهِ الَّتِي رَخَّصَ لَكُمْ»."]]},{"id":"um37_6","label":"الحديث ١٨٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ فَمِنَّا الصَّائِمُ، وَمِنَّا المُفْطِرُ، قَالَ: فَنَزَلْنَا مَنْزِلاً فِي يَوْمٍ حَارٍّ، وَأَكْثَرُنَا ظِلّاً صَاحِبُ الكِسَاءِ، فَمِنَّا مَنْ يَتَّقِي الشَّمْسَ بِيَدِهِ، قَالَ: فَسَقَطَ الصُّوَّامُ،"]]},{"id":"um37_7","label":"الحديث ١٨٥ · المقطع ٢ من ٢","segs":[["matn","وَقَامَ المُفْطِرُونَ فَضَرَبُوا الأَبْنِيَةَ وَسَقَوُا الرِّكَابَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ذَهَبَ المُفْطِرُونَ اليَوْمَ بِالأَجْرِ»."]]},{"id":"um37_8","label":"الحديث ١٨٦","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كَانَ يَكُونُ عَلَيَّ الصَّوْمُ مِنْ رَمَضَانَ، فَمَا أَسْتَطِيعُ أَنْ أَقْضِيَ إِلَّا فِي شَعْبَانَ»."]]},{"id":"um37_9","label":"الحديث ١٨٧","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ مَاتَ وَعَلَيْهِ صِيَامٌ؛ صَامَ عَنْهُ وَلِيُّهُ». وَأَخْرَجَهُ أَبُو دَاوُدَ وَقَالَ: «هَذَا فِي النَّذْرِ؛ وَهُوَ قَوْلُ أَحْمَدَ بْنِ حَنْبَلٍ»."]]},{"id":"um37_10","label":"الحديث ١٨٨ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! إِنَّ أُمِّي مَاتَتْ وَعَلَيْهَا صَوْمُ شَهْرٍ؛ أَفَأَقْضِيهِ عَنْهَا؟ فَقَالَ: لَوْ كَانَ عَلَى أُمِّكَ دَيْنٌ أَكُنْتَ قَاضِيَهُ عَنْهَا؟ قَالَ: نَعَمْ، قَالَ:"]]},{"id":"um37_11","label":"الحديث ١٨٨ · المقطع ٢ من ٣","segs":[["matn","فَدَيْنُ اللَّهِ أَحَقُّ أَنْ يُقْضَى». وَفِي رِوَايَةٍ: «جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ! إِنَّ أُمِّي مَاتَتْ وَعَلَيْهَا صَوْمُ نَذْرٍ؛ أَفَأَصُومُ عَنْهَا؟ فَقَالَ:"]]},{"id":"um37_12","label":"الحديث ١٨٨ · المقطع ٣ من ٣","segs":[["matn","أَرَأَيْتِ لَوْ كَانَ عَلَى أُمِّكِ دَيْنٌ فَقَضَيْتِيهِ؛ أَكَانَ ذَلِكِ يُؤَدِّي عَنْهَا؟ قَالَتْ: نَعَمْ، قَالَ: فَصُومِي عَنْ أُمِّكِ»."]]},{"id":"um37_13","label":"الحديث ١٨٩","segs":[["rawi","عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الفِطْرَ»."]]},{"id":"um37_14","label":"الحديث ١٩٠","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِذَا أَقْبَلَ اللَّيْلُ مِنْ هَاهُنَا، وَأَدْبَرَ النَّهَارُ مِنْ هَاهُنَا؛ فَقَدْ أَفْطَرَ الصَّائِمُ»."]]},{"id":"um37_15","label":"الحديث ١٩١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الوِصَالِ، قَالُوا: إِنَّكَ تُوَاصِلُ، قَالَ: إِنِّي لَسْتُ مِثْلَكُمْ، إِنِّي أُطْعَمُ وَأُسْقَى». وَلِمُسْلِمٍ عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: «فَأَيُّكُمْ أَرَادَ أَنْ يُوَاصِلَ فَلْيُوَاصِلْ إِلَى السَّحَرِ»."],["takh","رَوَاهُ: أَبُو هُرَيْرَةَ، وَعَائِشَةُ، وَأَنَسُ بْنُ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمْ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um38","title":"بَابُ أَفْضَلِ الصِّيَامِ وَغَيْرِهِ","units":[{"id":"um38_1","label":"الحديث ١٩٢ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِي رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أُخْبِرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِّي أَقُولُ: وَاللَّهِ لَأَصُومَنَّ النَّهَارَ، وَلَأَقُومَنَّ اللَّيْلَ مَا عِشْتُ، فَقُلْتُ لَهُ: قَدْ قُلْتُهُ - بِأَبِي أَنْتَ وَأُمِّي -، قَالَ: فَإِنَّكَ لَا تَسْتَطِيعُ ذَلِكَ، فَصُمْ وَأَفْطِرْ، وَقُمْ وَنَمْ،"]]},{"id":"um38_2","label":"الحديث ١٩٢ · المقطع ٢ من ٣","segs":[["matn","وَصُمْ مِنَ الشَّهْرِ ثَلَاثَةَ أَيَّامٍ؛ فَإِنَّ الحَسَنَةَ بِعَشْرِ أَمْثَالِهَا، وَذَلِكَ مِثْلُ صِيَامِ الدَّهْرِ، قُلْتُ: فَإِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ، قَالَ: فَصُمْ يَوْماً وَأَفْطِرْ يَوْمَيْنِ، قُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ، قَالَ: فَصُمْ يَوْماً وَأَفْطِرْ يَوْماً؛"]]},{"id":"um38_3","label":"الحديث ١٩٢ · المقطع ٣ من ٣","segs":[["matn","فَذَلِكَ صِيَامُ دَاوُدَ عَلَيْهِ السَّلَامُ، وَهُوَ أَفْضَلُ الصِّيَامِ، فَقُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ». وَفِي رِوَايَةٍ: «لَا صَوْمَ فَوْقَ صَوْمِ دَاوُدَ؛ شَطْرُ الدَّهْرِ؛ صُمْ يَوْماً وَأَفْطِرْ يَوْماً»."]]},{"id":"um38_4","label":"الحديث ١٩٣","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«إِنَّ أَحَبَّ الصِّيَامِ إِلَى اللَّهِ صِيَامُ دَاوُدَ، وَأَحَبُّ الصَّلَاةِ إِلَى اللَّهِ صَلَاةُ دَاوُدَ؛ كَانَ يَنَامُ نِصْفَ اللَّيْلِ، وَيَقُومُ ثُلُثَهُ، وَيَنَامُ سُدُسَهُ، وَكَانَ يَصُومُ يَوْماً وَيُفْطِرُ يَوْماً»."]]},{"id":"um38_5","label":"الحديث ١٩٤","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«أَوْصَانِي خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثٍ: صِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَرَكْعَتَيِ الضُّحَى، وَأَنْ أُوتِرَ قَبْلَ أَنْ أَنَامَ»."]]},{"id":"um38_6","label":"الحديث ١٩٥","segs":[["rawi","عَنْ مُحَمَّدِ بْنِ عَبَّادِ بْنِ جَعْفَرٍ قَالَ:"],["matn","«سَأَلْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صَوْمِ يَوْمِ الجُمُعَةِ؟ قَالَ: نَعَمْ». زَادَ مُسْلِمٌ: «وَرَبِّ الكَعْبَةِ!»."]]},{"id":"um38_7","label":"الحديث ١٩٦","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"],["matn","«لَا يَصُومَنَّ أَحَدُكُمْ يَوْمَ الجُمُعَةِ؛ إِلَّا أَنْ يَصُومَ يَوْماً قَبْلَهُ، أَوْ يَوْماً بَعْدَهُ»."]]},{"id":"um38_8","label":"الحديث ١٩٧","segs":[["rawi","عَنْ أَبِي عُبَيْدٍ مَوْلَى ابْنِ أَزْهَرَ - وَاسْمُهُ: سَعْدُ بْنُ عُبَيْدٍ - قَالَ:"],["matn","«شَهِدْتُ العِيدَ مَعَ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: هَذَانِ يَوْمَانِ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صِيَامِهِمَا: يَوْمُ فِطْرِكُمْ مِنْ صِيَامِكُمْ، وَاليَوْمُ الآخَرُ تَأْكُلُونَ فِيهِ مِنْ نُسُكِكُمْ»."]]},{"id":"um38_9","label":"الحديث ١٩٨","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صَوْمِ يَوْمَيْنِ: الفِطْرِ وَالنَّحْرِ، وَعَنِ الصَّمَّاءِ، وَأَنْ يَحْتَبِيَ الرَّجُلُ فِي ثَوْبٍ وَاحِدٍ، وَعَنِ الصَّلَاةِ بَعْدَ الصُّبْحِ وَالعَصْرِ»."],["takh","أَخْرَجَهُ مُسْلِمٌ بِتَمَامِهِ. وَأَخْرَجَ البُخَارِيُّ: الصَّوْمَ فَقَطْ."]]},{"id":"um38_10","label":"الحديث ١٩٩","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«مَنْ صَامَ يَوْماً فِي سَبِيلِ اللَّهِ؛ بَعَّدَ اللَّهُ وَجْهَهُ عَنِ النَّارِ سَبْعِينَ خَرِيفاً»."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um39","title":"بَابُ لَيْلَةِ القَدْرِ","units":[{"id":"um39_1","label":"الحديث ٢٠٠","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رِجَالاً مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُرُوا لَيْلَةَ القَدْرِ فِي المَنَامِ فِي السَّبْعِ الأَوَاخِرِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرَى رُؤْيَاكُمْ قَدْ تَوَاطَأَتْ فِي السَّبْعِ الأَوَاخِرِ؛ فَمَنْ كَانَ مُتَحَرِّيَهَا فَلْيَتَحَرَّهَا فِي السَّبْعِ الأَوَاخِرِ»."]]},{"id":"um39_2","label":"الحديث ٢٠١","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«تَحَرَّوْا لَيْلَةَ القَدْرِ فِي الوِتْرِ مِنَ العَشْرِ الأَوَاخِرِ»."]]},{"id":"um39_3","label":"الحديث ٢٠٢ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَعْتَكِفُ فِي العَشْرِ الأَوْسَطِ مِنْ رَمَضَانَ، فَاعْتَكَفَ عَاماً، حَتَّى إِذَا كَانَتْ لَيْلَةُ إِحْدَى وَعِشْرِينَ - وَهِيَ اللَّيْلَةُ الَّتِي يَخْرُجُ مِنْ صَبِيحَتِهَا مِنِ اعْتِكَافِهِ - قَالَ:"]]},{"id":"um39_4","label":"الحديث ٢٠٢ · المقطع ٢ من ٣","segs":[["matn","مَنِ اعْتَكَفَ مَعِي فَلْيَعْتَكِفِ العَشْرَ الأَوَاخِرَ؛ فَقَدْ أُرِيتُ هَذِهِ اللَّيْلَةَ ثُمَّ أُنْسِيتُهَا، وَقَدْ رَأَيْتُنِي أَسْجُدُ فِي مَاءٍ وَطِينٍ مِنْ صَبِيحَتِهَا؛ فَالْتَمِسُوهَا فِي العَشْرِ الأَوَاخِرِ، وَالْتَمِسُوهَا فِي كُلِّ وِتْرٍ، فَمَطَرَتِ السَّمَاءُ تِلْكَ اللَّيْلَةَ،"]]},{"id":"um39_5","label":"الحديث ٢٠٢ · المقطع ٣ من ٣","segs":[["matn","وَكَانَ المَسْجِدُ عَلَى عَرِيشٍ، فَوَكَفَ المَسْجِدُ، فَأَبْصَرَتْ عَيْنَايَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَى جَبْهَتِهِ أَثَرُ المَاءِ وَالطِّينِ مِنْ صُبْحِ إِحْدَى وَعِشْرِينَ»."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um40","title":"بَابُ الِاعْتِكَافِ","units":[{"id":"um40_1","label":"الحديث ٢٠٣ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَعْتَكِفُ العَشْرَ الأَوَاخِرَ مِنْ رَمَضَانَ حَتَّى تَوَفَّاهُ اللَّهُ عَزَّ وَجَلَّ، ثُمَّ اعْتَكَفَ أَزْوَاجُهُ بَعْدَهُ». وَفِي لَفْظٍ: «كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْتَكِفُ فِي كُلِّ رَمَضَانَ،"]]},{"id":"um40_2","label":"الحديث ٢٠٣ · المقطع ٢ من ٢","segs":[["matn","فَإِذَا صَلَّى الغَدَاةَ جَاءَ مَكَانَهُ الَّذِي اعْتَكَفَ فِيهِ»."]]},{"id":"um40_3","label":"الحديث ٢٠٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّهَا كَانَتْ تُرَجِّلُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ حَائِضٌ، وَهُوَ مُعْتَكِفٌ فِي المَسْجِدِ، وَهِيَ فِي حُجْرَتِهَا؛ يُنَاوِلُهَا رَأْسَهُ». وَفِي رِوَايَةٍ: «وَكَانَ لَا يَدْخُلُ البَيْتَ إِلَّا لِحَاجَةِ الإِنْسَانِ». وَفِي رِوَايَةٍ:"]]},{"id":"um40_4","label":"الحديث ٢٠٤ · المقطع ٢ من ٢","segs":[["matn","«أَنَّ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إِنْ كُنْتُ لَأَدْخُلُ البَيْتَ لِلْحَاجَةِ وَالمَرِيضُ فِيهِ، فَمَا أَسْأَلُ عَنْهُ إِلَّا وَأَنَا مَارَّةٌ»."]]},{"id":"um40_5","label":"الحديث ٢٠٥","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«قُلْتُ: يَا رَسُولَ اللَّهِ! إِنِّي كُنْتُ نَذَرْتُ فِي الجَاهِلِيَّةِ أَنْ أَعْتَكِفَ لَيْلَةً - وَفِي رِوَايَةٍ: يَوْماً - فِي المَسْجِدِ الحَرَامِ؛ قَالَ: فَأَوْفِ بِنَذْرِكَ». وَلَمْ يَذْكُرْ بَعْضُ الرُّوَاةِ: «يَوْماً» وَلَا «لَيْلَةً»."]]},{"id":"um40_6","label":"الحديث ٢٠٦ · المقطع ١ من ٤","segs":[["rawi","عَنْ صَفِيَّةَ بِنْتِ حُيَيٍّ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُعْتَكِفاً فَأَتَيْتُهُ أَزُورُهُ لَيْلاً، فَحَدَّثْتُهُ، ثُمَّ قُمْتُ لِأَنْقَلِبَ، فَقَامَ مَعِي لِيَقْلِبَنِي - وَكَانَ مَسْكَنُهَا فِي دَارِ أُسَامَةَ بْنِ زَيْدٍ -، فَمَرَّ رَجُلَانِ مِنَ الأَنْصَارِ،"]]},{"id":"um40_7","label":"الحديث ٢٠٦ · المقطع ٢ من ٤","segs":[["matn","فَلَمَّا رَأَيَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسْرَعَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَلَى رِسْلِكُمَا، إِنَّهَا صَفِيَّةُ بِنْتُ حُيَيٍّ، فَقَالَا: سُبْحَانَ اللَّهِ يَا رَسُولَ اللَّهِ! فَقَالَ:"]]},{"id":"um40_8","label":"الحديث ٢٠٦ · المقطع ٣ من ٤","segs":[["matn","إِنَّ الشَّيْطَانَ يَجْرِي مِنِ ابْنِ آدَمَ مَجْرَى الدَّمِ، وَإِنِّي خَشِيتُ أَنْ يَقْذِفَ فِي قُلُوبِكُمَا شَرّاً - أَوْ قَالَ: شَيْئاً -». وَفِي رِوَايَةٍ: «أَنَّهَا جَاءَتْ تَزُورُهُ فِي اعْتِكَافِهِ فِي المَسْجِدِ فِي العَشْرِ الأَوَاخِرِ مِنْ رَمَضَانَ،"]]},{"id":"um40_9","label":"الحديث ٢٠٦ · المقطع ٤ من ٤","segs":[["matn","فَتَحَدَّثَتْ عِنْدَهُ سَاعَةً ثُمَّ قَامَتْ تَنْقَلِبُ، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَهَا يَقْلِبُهَا، حَتَّى إِذَا بَلَغَتْ بَابَ المَسْجِدِ عِنْدَ بَابِ أُمِّ سَلَمَةَ …»، ثُمَّ ذَكَرَهُ بِمَعْنَاهُ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um41","title":"بَابُ المَوَاقِيتِ","units":[{"id":"um41_1","label":"الحديث ٢٠٧ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَّتَ لِأَهْلِ المَدِينَةِ: ذَا الحُلَيْفَةِ، وَلِأَهْلِ الشَّامِ: الجُحْفَةَ، وَلِأَهْلِ نَجْدٍ: قَرْنَ المَنَازِلِ، وَلِأَهْلِ اليَمَنِ: يَلَمْلَمَ؛ هُنَّ لَهُنَّ، وَلِمَنْ أَتَى عَلَيْهِنَّ مِنْ غَيْرِهِنَّ؛ مِمَّنْ أَرَادَ الحَجَّ وَالعُمْرَةَ،"]]},{"id":"um41_2","label":"الحديث ٢٠٧ · المقطع ٢ من ٢","segs":[["matn","وَمَنْ كَانَ دُونَ ذَلِكَ: فَمِنْ حَيْثُ أَنْشَأَ؛ حَتَّى أَهْلُ مَكَّةَ مِنْ مَكَّةَ»."]]},{"id":"um41_3","label":"الحديث ٢٠٨","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«يُهِلُّ أَهْلُ المَدِينَةِ مِنْ ذِي الحُلَيْفَةِ، وَأَهْلُ الشَّامِ مِنَ الجُحْفَةِ، وَأَهْلُ نَجْدٍ مِنْ قَرْنٍ. قَالَ عَبْدُ اللَّهِ: وَبَلَغَنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَيُهِلُّ أَهْلُ اليَمَنِ مِنْ يَلَمْلَمَ»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um42","title":"بَابُ مَا يَلْبَسُ المُحْرِمُ مِنَ الثِّيَابِ","units":[{"id":"um42_1","label":"الحديث ٢٠٩ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَجُلاً قَالَ: يَا رَسُولَ اللَّهِ! مَا يَلْبَسُ المُحْرِمُ مِنَ الثِّيَابِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَلْبَسُ القُمُصَ، وَلَا العَمَائِمَ، وَلَا السَّرَاوِيلَاتِ، وَلَا البَرَانِسَ، وَلَا الخِفَافَ؛"]]},{"id":"um42_2","label":"الحديث ٢٠٩ · المقطع ٢ من ٢","segs":[["matn","إِلَّا أَحَدٌ لَا يَجِدُ نَعْلَيْنِ فَلْيَلْبَسِ الخُفَّيْنِ وَلْيَقْطَعْهُمَا أَسْفَلَ مِنَ الكَعْبَيْنِ، وَلَا يَلْبَسْ مِنَ الثِّيَابِ شَيْئاً مَسَّهُ زَعْفَرَانٌ أَوْ وَرْسٌ». وَلِلْبُخَارِيِّ: «وَلَا تَنْتَقِبِ المَرْأَةُ، وَلَا تَلْبَسِ القُفَّازَيْنِ»."]]},{"id":"um42_3","label":"الحديث ٢١٠","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ بِعَرَفَاتٍ: مَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسِ الخُفَّيْنِ، وَمَنْ لَمْ يَجِدْ إِزَاراً فَلْيَلْبَسِ السَّرَاوِيلَ - لِلْمُحْرِمِ -»."]]},{"id":"um42_4","label":"الحديث ٢١١ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ تَلْبِيَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ! لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ! إِنَّ الحَمْدَ وَالنِّعْمَةَ لَكَ وَالمُلْكَ، لَا شَرِيكَ لَكَ. قَالَ: وَكَانَ عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَزِيدُ فِيهَا:"]]},{"id":"um42_5","label":"الحديث ٢١١ · المقطع ٢ من ٢","segs":[["matn","لَبَّيْكَ لَبَّيْكَ وَسَعْدَيْكَ، وَالخَيْرُ بِيَدَيْكَ، وَالرَّغْبَاءُ إِلَيْكَ وَالعَمَلُ»."]]},{"id":"um42_6","label":"الحديث ٢١٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَاليَوْمِ الآخِرِ أَنْ تُسَافِرَ مَسِيرَةَ يَوْمٍ وَلَيْلَةٍ؛ إِلَّا وَمَعَهَا حُرْمَةٌ». وَفِي لَفْظٍ لِلْبُخَارِيِّ: «تُسَافِرُ مَسِيرَةَ يَوْمٍ إِلَّا مَعَ ذِي مَحْرَمٍ»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um43","title":"بَابُ الفِدْيَةِ","units":[{"id":"um43_1","label":"الحديث ٢١٣ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ مَعْقِلٍ قَالَ:"],["matn","«جَلَسْتُ إِلَى كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللَّهُ عَنْهُ فَسَأَلْتُهُ عَنِ الفِدْيَةِ؛ فَقَالَ: نَزَلَتْ فِيَّ خَاصَّةً، وَهِيَ لَكُمْ عَامَّةٌ؛ حُمِلْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالقَمْلُ يَتَنَاثَرُ عَلَى وَجْهِي، فَقَالَ:"]]},{"id":"um43_2","label":"الحديث ٢١٣ · المقطع ٢ من ٣","segs":[["matn","مَا كُنْتُ أُرَى الوَجَعَ بَلَغَ بِكَ مَا أَرَى - أَوْ مَا كُنْتُ أُرَى الجَهْدَ بَلَغَ بِكَ مَا أَرَى - أَتَجِدُ شَاةً؟ فَقُلْتُ: لَا، فَقَالَ: فَصُمْ ثَلَاثَةَ أَيَّامٍ، أَوْ أَطْعِمْ سِتَّةَ مَسَاكِينَ؛ لِكُلِّ مِسْكِينٍ نِصْفُ صَاعٍ»."]]},{"id":"um43_3","label":"الحديث ٢١٣ · المقطع ٣ من ٣","segs":[["matn","وَفِي رِوَايَةٍ: «فَأَمَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُطْعِمَ فَرَقاً بَيْنَ سِتَّةٍ، أَوْ يُهْدِيَ شَاةً، أَوْ يَصُومَ ثَلَاثَةَ أَيَّامٍ»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um44","title":"بَابُ حُرْمَةِ مَكَّةَ","units":[{"id":"um44_1","label":"الحديث ٢١٤ · المقطع ١ من ٤","segs":[["rawi","عَنْ أَبِي شُرَيْحٍ خُوَيْلِدِ بْنِ عَمْرٍو الخُزَاعِيِّ العَدَوِيِّ رَضِيَ اللَّهُ عَنْهُ:"],["matn","أَنَّهُ قَالَ لِعَمْرِو بْنِ سَعِيدِ بْنِ العَاصِي - وَهُوَ يَبْعَثُ البُعُوثَ إِلَى مَكَّةَ -: «ائْذَنْ لِي أَيُّهَا الأَمِيرُ أَنْ أُحَدِّثَكَ قَوْلاً قَامَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الغَدَ مِنْ يَوْمِ الفَتْحِ؛ سَمِعَتْهُ أُذُنَايَ،"]]},{"id":"um44_2","label":"الحديث ٢١٤ · المقطع ٢ من ٤","segs":[["matn","وَوَعَاهُ قَلْبِي، وَأَبْصَرَتْهُ عَيْنَايَ حِينَ تَكَلَّمَ بِهِ: أَنَّهُ حَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: إِنَّ مَكَّةَ حَرَّمَهَا اللَّهُ، وَلَمْ يُحَرِّمْهَا النَّاسُ، فَلَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللَّهِ وَاليَوْمِ الآخِرِ أَنْ يَسْفِكَ بِهَا دَماً،"]]},{"id":"um44_3","label":"الحديث ٢١٤ · المقطع ٣ من ٤","segs":[["matn","وَلَا يَعْضِدَ بِهَا شَجَرَةً، فَإِنْ أَحَدٌ تَرَخَّصَ بِقِتَالِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُولُوا: إِنَّ اللَّهَ أَذِنَ لِرَسُولِهِ وَلَمْ يَأْذَنْ لَكُمْ، وَإِنَّمَا أَذِنَ لِي سَاعَةً مِنْ نَهَارٍ، وَقَدْ عَادَتْ حُرْمَتُهَا اليَوْمَ كَحُرْمَتِهَا بِالأَمْسِ،"]]},{"id":"um44_4","label":"الحديث ٢١٤ · المقطع ٤ من ٤","segs":[["matn","فَلْيُبْلِغِ الشَّاهِدُ الغَائِبَ، فَقِيلَ لِأَبِي شُرَيْحٍ: مَا قَالَ لَكَ؟ قَالَ: أَنَا أَعْلَمُ بِذَلِكَ مِنْكَ يَا أَبَا شُرَيْحٍ! إِنَّ الحَرَمَ لَا يُعِيذُ عَاصِياً، وَلَا فَارّاً بِدَمٍ، وَلَا فَارّاً بِخُرْبَةٍ»."]]},{"id":"um44_5","label":"الحديث ٢١٥ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يَوْمَ فَتْحِ مَكَّةَ -: «لَا هِجْرَةَ، وَلَكِنْ جِهَادٌ وَنِيَّةٌ، وَإِذَا اسْتُنْفِرْتُمْ فَانْفِرُوا، وَقَالَ - يَوْمَ فَتْحِ مَكَّةَ -: إِنَّ هَذَا البَلَدَ حَرَّمَهُ اللَّهُ يَوْمَ خَلَقَ السَّمَوَاتِ وَالأَرْضَ؛"]]},{"id":"um44_6","label":"الحديث ٢١٥ · المقطع ٢ من ٣","segs":[["matn","فَهُوَ حَرَامٌ بِحُرْمَةِ اللَّهِ إِلَى يَوْمِ القِيَامَةِ، وَإِنَّهُ لَمْ يَحِلَّ القِتَالُ فِيهِ لِأَحَدٍ قَبْلِي، وَلَمْ يَحِلَّ لِي إِلَّا سَاعَةً مِنْ نَهَارٍ، فَهُوَ حَرَامٌ بِحُرْمَةِ اللَّهِ إِلَى يَوْمِ القِيَامَةِ؛ لَا يُعْضَدُ شَوْكُهُ، وَلَا يُنَفَّرُ صَيْدُهُ،"]]},{"id":"um44_7","label":"الحديث ٢١٥ · المقطع ٣ من ٣","segs":[["matn","وَلَا يَلْتَقِطُ لُقَطَتَهُ إِلَّا مَنْ عَرَّفَهَا، وَلَا يُخْتَلَى خَلَاهُ، فَقَالَ العَبَّاسُ رَضِيَ اللَّهُ عَنْهُ: يَا رَسُولَ اللَّهِ! إِلَّا الإِذْخِرَ؛ فَإِنَّهُ لِقَيْنِهِمْ وَبُيُوتِهِمْ، فَقَالَ: إِلَّا الإِذْخِرَ»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um45","title":"بَابُ مَا يَجُوزُ قَتْلُهُ","units":[{"id":"um45_1","label":"الحديث ٢١٦","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«خَمْسٌ مِنَ الدَّوَابِّ كُلُّهُنَّ فَاسِقٌ؛ يُقْتَلْنَ فِي الحَرَمِ: الغُرَابُ، وَالحِدَأَةُ، وَالعَقْرَبُ، وَالفَأْرَةُ، وَالكَلْبُ العَقُورُ». وَلِمُسْلِمٍ: «تُقْتَلُ خَمْسٌ فَوَاسِقُ فِي الحِلِّ وَالحَرَمِ»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um46","title":"بَابُ دُخُولِ مَكَّةَ وَغَيْرِهِ","units":[{"id":"um46_1","label":"الحديث ٢١٧","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ عَامَ الفَتْحِ، وَعَلَى رَأْسِهِ المِغْفَرُ، فَلَمَّا نَزَعَهُ جَاءَهُ رَجُلٌ فَقَالَ: ابْنُ خَطَلٍ مُتَعَلِّقٌ بِأَسْتَارِ الكَعْبَةِ، فَقَالَ: اقْتُلُوهُ»."]]},{"id":"um46_2","label":"الحديث ٢١٨","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ مِنْ كَدَاءٍ، مِنَ الثَّنِيَّةِ العُلْيَا الَّتِي بِالبَطْحَاءِ، وَخَرَجَ مِنَ الثَّنِيَّةِ السُّفْلَى»."]]},{"id":"um46_3","label":"الحديث ٢١٩ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ البَيْتَ وَأُسَامَةُ بْنُ زَيْدٍ وَبِلَالٌ وَعُثْمَانُ بْنُ طَلْحَةَ، فَأَغْلَقُوا عَلَيْهِمُ البَابَ، فَلَمَّا فَتَحُوا كُنْتُ أَوَّلَ مَنْ وَلَجَ، فَلَقِيتُ بِلَالاً فَسَأَلْتُهُ:"]]},{"id":"um46_4","label":"الحديث ٢١٩ · المقطع ٢ من ٢","segs":[["matn","هَلْ صَلَّى فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ، بَيْنَ العَمُودَيْنِ اليَمَانِيَيْنِ»."]]},{"id":"um46_5","label":"الحديث ٢٢٠","segs":[["rawi","عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّهُ جَاءَ إِلَى الحَجَرِ الأَسْوَدِ فَقَبَّلَهُ، وَقَالَ: إِنِّي لَأَعْلَمُ أَنَّكَ حَجَرٌ لَا تَضُرُّ وَلَا تَنْفَعُ، وَلَوْلَا أَنِّي رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَبِّلُكَ مَا قَبَّلْتُكَ»."]]},{"id":"um46_6","label":"الحديث ٢٢١ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ، فَقَالَ المُشْرِكُونَ: إِنَّهُ يَقْدَمُ عَلَيْكُمْ وَفْدٌ وَهَنَتْهُمْ حُمَّى يَثْرِبَ، فَأَمَرَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَرْمُلُوا الأَشْوَاطَ الثَّلَاثَةَ، وَأَنْ يَمْشُوا مَا بَيْنَ الرُّكْنَيْنِ،"]]},{"id":"um46_7","label":"الحديث ٢٢١ · المقطع ٢ من ٢","segs":[["matn","وَلَمْ يَمْنَعْهُمْ أَنْ يَرْمُلُوا الأَشْوَاطَ كُلَّهَا إِلَّا الإِبْقَاءُ عَلَيْهِمْ»."]]},{"id":"um46_8","label":"الحديث ٢٢٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ يَقْدَمُ مَكَّةَ: إِذَا اسْتَلَمَ الرُّكْنَ الأَسْوَدَ أَوَّلَ مَا يَطُوفُ؛ يَخُبُّ ثَلَاثَةَ أَشْوَاطٍ»."]]},{"id":"um46_9","label":"الحديث ٢٢٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«طَافَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الوَدَاعِ عَلَى بَعِيرٍ؛ يَسْتَلِمُ الرُّكْنَ بِمِحْجَنٍ»."]]},{"id":"um46_10","label":"الحديث ٢٢٤","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«لَمْ أَرَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَلِمُ مِنَ البَيْتِ إِلَّا الرُّكْنَيْنِ اليَمَانِيَيْنِ»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um47","title":"بَابُ التَّمَتُّعِ","units":[{"id":"um47_1","label":"الحديث ٢٢٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي جَمْرَةَ نَصْرِ بْنِ عِمْرَانَ الضُّبَعِيِّ قَالَ:"],["matn","«سَأَلْتُ ابْنَ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنِ المُتْعَةِ فَأَمَرَنِي بِهَا، وَسَأَلْتُهُ عَنِ الهَدْيِ فَقَالَ: فِيهَا جَزُورٌ، أَوْ بَقَرَةٌ، أَوْ شَاةٌ، أَوْ شِرْكٌ فِي دَمٍ، قَالَ: وَكَانَ نَاسٌ كَرِهُوهَا، فَنِمْتُ فَرَأَيْتُ فِي المَنَامِ كَأَنَّ إِنْسَاناً يُنَادِي:"]]},{"id":"um47_2","label":"الحديث ٢٢٥ · المقطع ٢ من ٢","segs":[["matn","حَجٌّ مَبْرُورٌ، وَمُتْعَةٌ مُتَقَبَّلَةٌ، فَأَتَيْتُ ابْنَ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا فَحَدَّثْتُهُ، فَقَالَ: اللَّهُ أَكْبَرُ، سُنَّةُ أَبِي القَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ»."]]},{"id":"um47_3","label":"الحديث ٢٢٦ · المقطع ١ من ٦","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«تَمَتَّعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الوَدَاعِ بِالعُمْرَةِ إِلَى الحَجِّ وَأَهْدَى؛ فَسَاقَ مَعَهُ الهَدْيَ مِنْ ذِي الحُلَيْفَةِ، وَبَدَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَهَلَّ بِالعُمْرَةِ، ثُمَّ أَهَلَّ بِالحَجِّ،"]]},{"id":"um47_4","label":"الحديث ٢٢٦ · المقطع ٢ من ٦","segs":[["matn","فَتَمَتَّعَ النَّاسُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالعُمْرَةِ إِلَى الحَجِّ، فَكَانَ مِنَ النَّاسِ مَنْ أَهْدَى - فَسَاقَ الهَدْيَ مِنْ ذِي الحُلَيْفَةِ -، وَمِنْهُمْ مَنْ لَمْ يُهْدِ،"]]},{"id":"um47_5","label":"الحديث ٢٢٦ · المقطع ٣ من ٦","segs":[["matn","فَلَمَّا قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِلنَّاسِ: مَنْ كَانَ مِنْكُمْ أَهْدَى؛ فَإِنَّهُ لَا يَحِلُّ مِنْ شَيْءٍ حَرُمَ مِنْهُ حَتَّى يَقْضِيَ حَجَّهُ، وَمَنْ لَمْ يَكُنْ أَهْدَى؛ فَلْيَطُفْ بِالبَيْتِ وَبِالصَّفَا وَالمَرْوَةِ، وَلْيُقَصِّرْ وَلْيَحْلِلْ،"]]},{"id":"um47_6","label":"الحديث ٢٢٦ · المقطع ٤ من ٦","segs":[["matn","ثُمَّ لِيُهِلَّ بِالحَجِّ وَلْيُهْدِ، فَمَنْ لَمْ يَجِدْ هَدْياً فَلْيَصُمْ ثَلَاثَةَ أَيَّامٍ فِي الحَجِّ وَسَبْعَةً إِذَا رَجَعَ إِلَى أَهْلِهِ؛ فَطَافَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَدِمَ مَكَّةَ؛ وَاسْتَلَمَ الرُّكْنَ أَوَّلَ شَيْءٍ،"]]},{"id":"um47_7","label":"الحديث ٢٢٦ · المقطع ٥ من ٦","segs":[["matn","ثُمَّ خَبَّ ثَلَاثَةَ أَطْوَافٍ مِنَ السَّبْعِ، وَمَشَى أَرْبَعَةً، وَرَكَعَ حِينَ قَضَى طَوَافَهُ بِالبَيْتِ عِنْدَ المَقَامِ رَكْعَتَيْنِ، ثُمَّ سَلَّمَ فَانْصَرَفَ، فَأَتَى الصَّفَا؛ فَطَافَ بِالصَّفَا وَالمَرْوَةِ سَبْعَةَ أَطْوَافٍ،"]]},{"id":"um47_8","label":"الحديث ٢٢٦ · المقطع ٦ من ٦","segs":[["matn","ثُمَّ لَمْ يَحْلِلْ مِنْ شَيْءٍ حَرُمَ مِنْهُ حَتَّى قَضَى حَجَّهُ، وَنَحَرَ هَدْيَهُ يَوْمَ النَّحْرِ، وَأَفَاضَ فَطَافَ بِالبَيْتِ، ثُمَّ حَلَّ مِنْ كُلِّ شَيْءٍ حَرُمَ مِنْهُ، وَفَعَلَ مِثْلَ مَا فَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ مَنْ أَهْدَى فَسَاقَ الهَدْيَ مِنَ النَّاسِ»."]]},{"id":"um47_9","label":"الحديث ٢٢٧","segs":[["rawi","عَنْ حَفْصَةَ رَضِيَ اللَّهُ عَنْهَا - زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَنَّهَا قَالَتْ:"],["matn","«يَا رَسُولَ اللَّهِ! مَا شَأْنُ النَّاسِ حَلُّوا مِنَ العُمْرَةِ، وَلَمْ تَحِلَّ أَنْتَ مِنْ عُمْرَتِكَ؟ فَقَالَ: إِنِّي لَبَّدْتُ رَأْسِي، وَقَلَّدْتُ هَدْيِي، فَلَا أَحِلُّ حَتَّى أَنْحَرَ»."]]},{"id":"um47_10","label":"الحديث ٢٢٨ · المقطع ١ من ٢","segs":[["rawi","عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أُنْزِلَتْ آيَةُ المُتْعَةِ فِي كِتَابِ اللَّهِ، فَفَعَلْنَاهَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَمْ يَنْزِلْ قُرْآنٌ يُحَرِّمُهُ، وَلَمْ يَنْهَ عَنْهَا حَتَّى مَاتَ، قَالَ رَجُلٌ بِرَأْيِهِ مَا شَاءَ». قَالَ البُخَارِيُّ: «يُقَالُ: إِنَّهُ عُمَرُ». وَلِمُسْلِمٍ:"]]},{"id":"um47_11","label":"الحديث ٢٢٨ · المقطع ٢ من ٢","segs":[["matn","«نَزَلَتْ آيَةُ المُتْعَةِ - يَعْنِي: مُتْعَةَ الحَجِّ -، وَأَمَرَنَا بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ لَمْ تَنْزِلْ آيَةٌ تَنْسَخُ آيَةَ مُتْعَةِ الحَجِّ، وَلَمْ يَنْهَ عَنْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى مَاتَ». وَلَهُمَا: بِمَعْنَاهُ."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um48","title":"بَابُ الهَدْيِ","units":[{"id":"um48_1","label":"الحديث ٢٢٩","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«فَتَلْتُ قَلَائِدَ هَدْيِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ أَشْعَرَهَا وَقَلَّدَهَا - أَوْ قَلَّدْتُهَا -، ثُمَّ بَعَثَ بِهَا إِلَى البَيْتِ وَأَقَامَ بِالمَدِينَةِ، فَمَا حَرُمَ عَلَيْهِ شَيْءٌ كَانَ لَهُ حِلّاً»."]]},{"id":"um48_2","label":"الحديث ٢٣٠","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«أَهْدَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّةً غَنَماً»."]]},{"id":"um48_3","label":"الحديث ٢٣١","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلاً يَسُوقُ بَدَنَةً؛ قَالَ: ارْكَبْهَا، قَالَ: إِنَّهَا بَدَنَةٌ، قَالَ: ارْكَبْهَا؛ فَرَأَيْتُهُ رَاكِبَهَا، يُسَايِرُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ». وَفِي لَفْظٍ: «قَالَ فِي الثَّانِيَةِ - أَوِ الثَّالِثَةِ -: ارْكَبْهَا وَيْلَكَ! - أَوْ وَيْحَكَ! -»."]]},{"id":"um48_4","label":"الحديث ٢٣٢","segs":[["rawi","عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«أَمَرَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقُومَ عَلَى بُدْنِهِ، وَأَنْ أَتَصَدَّقَ بِلَحْمِهَا وَجُلُودِهَا وَأَجِلَّتِهَا، وَأَنْ لَا أُعْطِيَ الجَزَّارَ مِنْهَا شَيْئاً، وَقَالَ: نَحْنُ نُعْطِيهِ مِنْ عِنْدِنَا»."]]},{"id":"um48_5","label":"الحديث ٢٣٣","segs":[["rawi","عَنْ زِيَادِ بْنِ جُبَيْرٍ قَالَ:"],["matn","«رَأَيْتُ ابْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَتَى عَلَى رَجُلٍ قَدْ أَنَاخَ بَدَنَتَهُ فَنَحَرَهَا، فَقَالَ: ابْعَثْهَا قِيَاماً مُقَيَّدَةً؛ سُنَّةَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um49","title":"بَابُ الغُسْلِ لِلْمُحْرِمِ","units":[{"id":"um49_1","label":"الحديث ٢٣٤ · المقطع ١ من ٤","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ:"],["matn","«أَنَّ عَبْدَ اللَّهِ بْنَ عَبَّاسٍ وَالمِسْوَرَ بْنَ مَخْرَمَةَ رَضِيَ اللَّهُ عَنْهُمْ اخْتَلَفَا بِالأَبْوَاءِ، فَقَالَ ابْنُ عَبَّاسٍ: يَغْسِلُ المُحْرِمُ رَأْسَهُ، وَقَالَ المِسْوَرُ: لَا يَغْسِلُ المُحْرِمُ رَأْسَهُ، قَالَ:"]]},{"id":"um49_2","label":"الحديث ٢٣٤ · المقطع ٢ من ٤","segs":[["matn","فَأَرْسَلَنِي ابْنُ عَبَّاسٍ إِلَى أَبِي أَيُّوبَ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ فَوَجَدْتُهُ يَغْتَسِلُ بَيْنَ القَرْنَيْنِ وَهُوَ يُسْتَرُ بِثَوْبٍ، فَسَلَّمْتُ عَلَيْهِ فَقَالَ: مَنْ هَذَا؟ قُلْتُ: أَنَا عَبْدُ اللَّهِ بْنُ حُنَيْنٍ، أَرْسَلَنِي إِلَيْكَ ابْنُ عَبَّاسٍ يَسْأَلُكَ:"]]},{"id":"um49_3","label":"الحديث ٢٣٤ · المقطع ٣ من ٤","segs":[["matn","كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْسِلُ رَأْسَهُ وَهُوَ مُحْرِمٌ؟ فَوَضَعَ أَبُو أَيُّوبَ يَدَهُ عَلَى الثَّوْبِ فَطَأْطَأَهُ حَتَّى بَدَا لِي رَأْسُهُ، ثُمَّ قَالَ لِإِنْسَانٍ يَصُبُّ عَلَيْهِ المَاءَ: اصْبُبْ، فَصَبَّ عَلَى رَأْسِهِ،"]]},{"id":"um49_4","label":"الحديث ٢٣٤ · المقطع ٤ من ٤","segs":[["matn","ثُمَّ حَرَّكَ رَأْسَهُ بِيَدَيْهِ فَأَقْبَلَ بِهِمَا وَأَدْبَرَ، ثُمَّ قَالَ: هَكَذَا رَأَيْتُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ». وَفِي رِوَايَةٍ: «فَقَالَ المِسْوَرُ لِابْنِ عَبَّاسٍ: لَا أُمَارِيكَ أَبَداً»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um50","title":"بَابُ فَسْخِ الحَجِّ إِلَى العُمْرَةِ","units":[{"id":"um50_1","label":"الحديث ٢٣٥ · المقطع ١ من ٤","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أَهَلَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ بِالحَجِّ، وَلَيْسَ مَعَ أَحَدٍ مِنْهُمْ هَدْيٌ غَيْرَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَطَلْحَةَ رَضِيَ اللَّهُ عَنْهُ، وَقَدِمَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ مِنَ اليَمَنِ فَقَالَ:"]]},{"id":"um50_2","label":"الحديث ٢٣٥ · المقطع ٢ من ٤","segs":[["matn","أَهْلَلْتُ بِمَا أَهَلَّ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَصْحَابَهُ أَنْ يَجْعَلُوهَا عُمْرَةً، فَيَطُوفُوا ثُمَّ يُقَصِّرُوا وَيَحِلُّوا؛ إِلَّا مَنْ كَانَ مَعَهُ الهَدْيُ، فَقَالُوا: نَنْطَلِقُ إِلَى مِنىً وَذَكَرُ أَحَدِنَا يَقْطُرُ؟!"]]},{"id":"um50_3","label":"الحديث ٢٣٥ · المقطع ٣ من ٤","segs":[["matn","فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لَوِ اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ مَا أَهْدَيْتُ، وَلَوْلَا أَنَّ مَعِيَ الهَدْيَ لَأَحْلَلْتُ، وَحَاضَتْ عَائِشَةُ فَنَسَكَتِ المَنَاسِكَ كُلَّهَا، غَيْرَ أَنَّهَا لَمْ تَطُفْ بِالبَيْتِ؛ فَلَمَّا طَهَرَتْ طَافَتْ بِالبَيْتِ،"]]},{"id":"um50_4","label":"الحديث ٢٣٥ · المقطع ٤ من ٤","segs":[["matn","قَالَتْ: يَا رَسُولَ اللَّهِ! تَنْطَلِقُونَ بِحَجَّةٍ وَعُمْرَةٍ، وَأَنْطَلِقُ بِحَجٍّ؟! فَأَمَرَ عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ أَنْ يَخْرُجَ مَعَهَا إِلَى التَّنْعِيمِ، فَاعْتَمَرَتْ بَعْدَ الحَجِّ»."]]},{"id":"um50_5","label":"الحديث ٢٣٦","segs":[["rawi","عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«قَدِمْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَقُولُ: لَبَّيْكَ بِالحَجِّ، فَأَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَعَلْنَاهَا عُمْرَةً»."]]},{"id":"um50_6","label":"الحديث ٢٣٧","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ صَبِيحَةَ رَابِعَةٍ، فَأَمَرَهُمْ أَنْ يَجْعَلُوهَا عُمْرَةً، فَقَالُوا: يَا رَسُولَ اللَّهِ! أَيُّ الحِلِّ؟ قَالَ: الحِلُّ كُلُّهُ»."]]},{"id":"um50_7","label":"الحديث ٢٣٨","segs":[["rawi","عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ قَالَ:"],["matn","«سُئِلَ أُسَامَةُ بْنُ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا - وَأَنَا جَالِسٌ - كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسِيرُ حِينَ دَفَعَ؟ قَالَ: كَانَ يَسِيرُ العَنَقَ؛ فَإِذَا وَجَدَ فَجْوَةً نَصَّ»."]]},{"id":"um50_8","label":"الحديث ٢٣٩ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَفَ فِي حَجَّةِ الوَدَاعِ، فَجَعَلُوا يَسْأَلُونَهُ، فَقَالَ رَجُلٌ: لَمْ أَشْعُرْ فَحَلَقْتُ قَبْلَ أَنْ أَذْبَحَ؟ قَالَ: اذْبَحْ وَلَا حَرَجَ، وَجَاءَ آخَرُ فَقَالَ: لَمْ أَشْعُرْ فَنَحَرْتُ قَبْلَ أَنْ أَرْمِيَ؟ قَالَ:"]]},{"id":"um50_9","label":"الحديث ٢٣٩ · المقطع ٢ من ٢","segs":[["matn","ارْمِ وَلَا حَرَجَ، فَمَا سُئِلَ يَوْمَئِذٍ عَنْ شَيْءٍ قُدِّمَ وَلَا أُخِّرَ إِلَّا قَالَ: افْعَلْ وَلَا حَرَجَ»."]]},{"id":"um50_10","label":"الحديث ٢٤٠","segs":[["rawi","عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ النَّخَعِيِّ:"],["matn","«أَنَّهُ حَجَّ مَعَ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ فَرَآهُ يَرْمِي الجَمْرَةَ الكُبْرَى بِسَبْعِ حَصَيَاتٍ، فَجَعَلَ البَيْتَ عَنْ يَسَارِهِ وَمِنىً عَنْ يَمِينِهِ، ثُمَّ قَالَ: هَذَا مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ البَقَرَةِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ»."]]},{"id":"um50_11","label":"الحديث ٢٤١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«اللَّهُمَّ ارْحَمِ المُحَلِّقِينَ، قَالُوا: وَالمُقَصِّرِينَ يَا رَسُولَ اللَّهِ؟! قَالَ: اللَّهُمَّ ارْحَمِ المُحَلِّقِينَ، قَالُوا: وَالمُقَصِّرِينَ يَا رَسُولَ اللَّهِ؟! قَالَ: وَالمُقَصِّرِينَ»."]]},{"id":"um50_12","label":"الحديث ٢٤٢ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«حَجَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَفَضْنَا يَوْمَ النَّحْرِ، فَحَاضَتْ صَفِيَّةُ، فَأَرَادَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهَا مَا يُرِيدُ الرَّجُلُ مِنْ أَهْلِهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ! إِنَّهَا حَائِضٌ، قَالَ: أَحَابِسَتُنَا هِيَ؟ قَالُوا:"]]},{"id":"um50_13","label":"الحديث ٢٤٢ · المقطع ٢ من ٢","segs":[["matn","يَا رَسُولَ اللَّهِ! أَفَاضَتْ يَوْمَ النَّحْرِ، قَالَ: اخْرُجُوا». وَفِي لَفْظٍ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «عَقْرَى حَلْقَى، أَطَافَتْ يَوْمَ النَّحْرِ؟ قِيلَ: نَعَمْ، قَالَ: فَانْفِرِي»."]]},{"id":"um50_14","label":"الحديث ٢٤٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أُمِرَ النَّاسُ أَنْ يَكُونَ آخِرُ عَهْدِهِمْ بِالبَيْتِ، إِلَّا أَنَّهُ خُفِّفَ عَنِ المَرْأَةِ الحَائِضِ»."]]},{"id":"um50_15","label":"الحديث ٢٤٤","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«اسْتَأْذَنَ العَبَّاسُ بْنُ عَبْدِ المُطَّلِبِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبِيتَ بِمَكَّةَ لَيَالِيَ مِنىً؛ مِنْ أَجْلِ سِقَايَتِهِ، فَأَذِنَ لَهُ»."]]},{"id":"um50_16","label":"الحديث ٢٤٥","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«جَمَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ المَغْرِبِ وَالعِشَاءِ بِجَمْعٍ لِكُلِّ وَاحِدَةٍ مِنْهُمَا بِإِقَامَةٍ، وَلَمْ يُسَبِّحْ بَيْنَهُمَا، وَلَا عَلَى إِثْرِ وَاحِدَةٍ مِنْهُمَا»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um51","title":"بَابُ المُحْرِمِ يَأْكُلُ مِنْ صَيْدِ الحَلَالِ","units":[{"id":"um51_1","label":"الحديث ٢٤٦ · المقطع ١ من ٤","segs":[["rawi","عَنْ أَبِي قَتَادَةَ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ حَاجّاً فَخَرَجُوا مَعَهُ، فَصَرَفَ طَائِفَةً مِنْهُمْ - فِيهِمْ أَبُو قَتَادَةَ - وَقَالَ: خُذُوا سَاحِلَ البَحْرِ حَتَّى نَلْتَقِيَ، فَأَخَذُوا سَاحِلَ البَحْرِ،"]]},{"id":"um51_2","label":"الحديث ٢٤٦ · المقطع ٢ من ٤","segs":[["matn","فَلَمَّا انْصَرَفُوا أَحْرَمُوا كُلُّهُمْ إِلَّا أَبَا قَتَادَةَ لَمْ يُحْرِمْ، فَبَيْنَمَا هُمْ يَسِيرُونَ إِذْ رَأَوْا حُمُرَ وَحْشٍ، فَحَمَلَ أَبُو قَتَادَةَ عَلَى الحُمُرِ، فَعَقَرَ مِنْهَا أَتَاناً، فَنَزَلْنَا فَأَكَلْنَا مِنْ لَحْمِهَا، ثُمَّ قُلْنَا: أَنَأْكُلُ لَحْمَ صَيْدٍ وَنَحْنُ مُحْرِمُونَ؟"]]},{"id":"um51_3","label":"الحديث ٢٤٦ · المقطع ٣ من ٤","segs":[["matn","فَحَمَلْنَا مَا بَقِيَ مِنْ لَحْمِهَا، فَأَدْرَكْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلْنَاهُ عَنْ ذَلِكَ؛ قَالَ: مِنْكُمْ أَحَدٌ أَمَرَهُ أَنْ يَحْمِلَ عَلَيْهَا أَوْ أَشَارَ إِلَيْهَا؟ قَالُوا: لَا، قَالَ: فَكُلُوا مَا بَقِيَ مِنْ لَحْمِهَا». وَفِي رِوَايَةٍ:"]]},{"id":"um51_4","label":"الحديث ٢٤٦ · المقطع ٤ من ٤","segs":[["matn","«فَقَالَ: هَلْ مَعَكُمْ مِنْهُ شَيْءٌ؟ فَقُلْتُ: نَعَمْ، فَنَاوَلْتُهُ العَضُدَ، فَأَكَلَهَا»."]]},{"id":"um51_5","label":"الحديث ٢٤٧ · المقطع ١ من ٢","segs":[["rawi","عَنِ الصَّعْبِ بْنِ جَثَّامَةَ اللَّيْثِيِّ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّهُ أَهْدَى إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِمَاراً وَحْشِيّاً وَهُوَ بِالأَبْوَاءِ - أَوْ بِوَدَّانَ - فَرَدَّهُ عَلَيْهِ، فَلَمَّا رَأَى مَا فِي وَجْهِهِ قَالَ: إِنَّا لَمْ نَرُدُّهُ عَلَيْكَ إِلَّا أَنَّا حُرُمٌ». وَفِي لَفْظٍ لِمُسْلِمٍ:"]]},{"id":"um51_6","label":"الحديث ٢٤٧ · المقطع ٢ من ٢","segs":[["matn","«رِجْلَ حِمَارٍ». وَفِي لَفْظٍ: «شِقَّ حِمَارٍ». وَفِي لَفْظٍ: «عَجُزَ حِمَارٍ»."]]}],"group":"كِتَابُ الحَجِّ"},{"id":"um52","title":"كِتَابُ البُيُوعِ","units":[{"id":"um52_1","label":"الحديث ٢٤٨","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:"],["matn","«إِذَا تَبَايَعَ الرَّجُلَانِ فَكُلُّ وَاحِدٍ مِنْهُمَا بِالخِيَارِ مَا لَمْ يَتَفَرَّقَا وَكَانَا جَمِيعاً، أَوْ يُخَيِّرُ أَحَدُهُمَا الآخَرَ، فَتَبَايَعَا عَلَى ذَلِكَ؛ فَقَدْ وَجَبَ البَيْعُ»."]]},{"id":"um52_2","label":"الحديث ٢٤٩","segs":[["rawi","عَنْ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «البَيِّعَانِ بِالخِيَارِ مَا لَمْ يَتَفَرَّقَا - أَوْ قَالَ: حَتَّى يَتَفَرَّقَا -؛ فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا، وَإِنْ كَتَمَا وَكَذَبَا مُحِقَتْ بَرَكَةُ بَيْعِهِمَا»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um53","title":"بَابُ مَا نُهِيَ عَنْهُ مِنَ البُيُوعِ","units":[{"id":"um53_1","label":"الحديث ٢٥٠","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ المُنَابَذَةِ - وَهِيَ: طَرْحُ الرَّجُلِ ثَوْبَهُ بِالبَيْعِ إِلَى الرَّجُلِ قَبْلَ أَنْ يُقَلِّبَهُ، أَوْ يَنْظُرَ إِلَيْهِ -، وَنَهَى عَنِ المُلَامَسَةِ - وَالمُلَامَسَةُ: لَمْسُ الثَّوْبِ لَا يَنْظُرُ إِلَيْهِ -»."]]},{"id":"um53_2","label":"الحديث ٢٥١","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا تَلَقَّوُا الرُّكْبَانَ، وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَلَا تَنَاجَشُوا، وَلَا يَبِعْ حَاضِرٌ لِبَادٍ، وَلَا تُصَرُّوا الغَنَمَ، وَمَنِ ابْتَاعَهَا فَهُوَ بِخَيْرِ النَّظَرَيْنِ بَعْدَ أَنْ يَحْلُبَهَا؛ إِنْ رَضِيَهَا أَمْسَكَهَا، وَإِنْ سَخِطَهَا رَدَّهَا وَصَاعاً مِنْ تَمْرٍ». وَفِي لَفْظٍ: «وَهُوَ بِالخِيَارِ ثَلَاثاً»."]]},{"id":"um53_3","label":"الحديث ٢٥٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ حَبَلِ الحَبَلَةِ - وَكَانَ بَيْعاً يَتَبَايَعُهُ أَهْلُ الجَاهِلِيَّةِ، كَانَ الرَّجُلُ يَبْتَاعُ الجَزُورَ إِلَى أَنْ تُنْتَجَ النَّاقَةُ، ثُمَّ تُنْتَجُ الَّتِي فِي بَطْنِهَا -»."]]},{"id":"um53_4","label":"الحديث ٢٥٣","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الثَّمَرِ حَتَّى يَبْدُوَ صَلَاحُهَا؛ نَهَى البَائِعَ وَالمُشْتَرِيَ»."]]},{"id":"um53_5","label":"الحديث ٢٥٤","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الثِّمَارِ حَتَّى تُزْهِيَ؛ - قِيلَ: وَمَا تُزْهِي؟ قَالَ: حَتَّى تَحْمَرَّ - قَالَ: أَرَأَيْتَ إِذَا مَنَعَ اللَّهُ الثَّمَرَةَ، بِمَ يَسْتَحِلُّ أَحَدُكُمْ مَالَ أَخِيهِ؟»."]]},{"id":"um53_6","label":"الحديث ٢٥٥","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُتَلَقَّى الرُّكْبَانُ، وَأَنْ يَبِيعَ حَاضِرٌ لِبَادٍ، قَالَ: فَقُلْتُ لِابْنِ عَبَّاسٍ: مَا قَوْلُهُ: حَاضِرٌ لِبَادٍ؟ قَالَ: لَا يَكُونُ لَهُ سِمْسَاراً»."]]},{"id":"um53_7","label":"الحديث ٢٥٦","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ المُزَابَنَةِ - أَنْ يَبِيعَ ثَمَرَ حَائِطِهِ إِنْ كَانَ نَخْلاً بِتَمْرٍ كَيْلاً، وَإِنْ كَانَ كَرْماً أَنْ يَبِيعَهُ بِزَبِيبٍ كَيْلاً، أَوْ كَانَ زَرْعاً أَنْ يَبِيعَهُ بِكَيْلِ طَعَامٍ؛ نَهَى عَنْ ذَلِكَ كُلِّهِ -»."]]},{"id":"um53_8","label":"الحديث ٢٥٧","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ المُخَابَرَةِ وَالمُحَاقَلَةِ، وَعَنِ المُزَابَنَةِ، وَعَنْ بَيْعِ الثَّمَرِ حَتَّى يَبْدُوَ صَلَاحُهَا، وَأَنْ لَا تُبَاعَ إِلَّا بِالدِّينَارِ وَالدِّرْهَمِ، إِلَّا العَرَايَا»."]]},{"id":"um53_9","label":"الحديث ٢٥٨","segs":[["rawi","عَنْ أَبِي مَسْعُودٍ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الكَلْبِ، وَمَهْرِ البَغِيِّ، وَحُلْوَانِ الكَاهِنِ»."]]},{"id":"um53_10","label":"الحديث ٢٥٩","segs":[["rawi","عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«ثَمَنُ الكَلْبِ خَبِيثٌ، وَمَهْرُ البَغِيِّ خَبِيثٌ، وَكَسْبُ الحَجَّامِ خَبِيثٌ»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um54","title":"بَابُ العَرَايَا وَغَيْرِ ذَلِكَ","units":[{"id":"um54_1","label":"الحديث ٢٦٠","segs":[["rawi","عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ لِصَاحِبِ العَرِيَّةِ أَنْ يَبِيعَهَا بِخَرْصِهَا». وَلِمُسْلِمٍ: «بِخَرْصِهَا تَمْراً، يَأْكُلُونَهَا رُطَباً»."]]},{"id":"um54_2","label":"الحديث ٢٦١","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ فِي بَيْعِ العَرَايَا فِي خَمْسَةِ أَوْسُقٍ - أَوْ دُونَ خَمْسَةِ أَوْسُقٍ -»."]]},{"id":"um54_3","label":"الحديث ٢٦٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ بَاعَ نَخْلاً قَدْ أُبِّرَتْ فَثَمَرُهَا لِلْبَائِعِ، إِلَّا أَنْ يَشْتَرِطَ المُبْتَاعُ». وَلِمُسْلِمٍ: «وَمَنِ ابْتَاعَ عَبْداً فَمَالُهُ لِلَّذِي بَاعَهُ، إِلَّا أَنْ يَشْتَرِطَ المُبْتَاعُ»."]]},{"id":"um54_4","label":"الحديث ٢٦٣","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنِ ابْتَاعَ طَعَاماً فَلَا يَبِعْهُ حَتَّى يَسْتَوْفِيَهُ». وَفِي لَفْظٍ: «حَتَّى يَقْبِضَهُ». وَعَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: مِثْلُهُ."]]},{"id":"um54_5","label":"الحديث ٢٦٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَامَ الفَتْحِ: «إِنَّ اللَّهَ وَرَسُولَهُ حَرَّمَ بَيْعَ الخَمْرِ وَالمَيْتَةِ وَالخِنْزِيرِ وَالأَصْنَامِ، فَقِيلَ: يَا رَسُولَ اللَّهِ! أَرَأَيْتَ شُحُومَ المَيْتَةِ؛ فَإِنَّهُ يُطْلَى بِهَا السُّفُنُ، وَيُدْهَنُ بِهَا الجُلُودُ،"]]},{"id":"um54_6","label":"الحديث ٢٦٤ · المقطع ٢ من ٢","segs":[["matn","وَيَسْتَصْبِحُ بِهَا النَّاسُ؟ فَقَالَ: لَا، هُوَ حَرَامٌ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: قَاتَلَ اللَّهُ اليَهُودَ؛ إِنَّ اللَّهَ لَمَّا حَرَّمَ شُحُومَهَا جَمَلُوهُ، ثُمَّ بَاعُوهُ، فَأَكَلُوا ثَمَنَهُ»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um55","title":"بَابُ السَّلَمِ","units":[{"id":"um55_1","label":"الحديث ٢٦٥","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ المَدِينَةَ وَهُمْ يُسْلِفُونَ فِي الثِّمَارِ: السَّنَتَيْنِ وَالثَّلَاثَ، فَقَالَ: مَنْ أَسْلَفَ فِي شَيْءٍ فَلْيُسْلِفْ؛ فِي كَيْلٍ مَعْلُومٍ، وَوَزْنٍ مَعْلُومٍ، إِلَى أَجَلٍ مَعْلُومٍ»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um56","title":"بَابُ الشُّرُوطِ فِي البَيْعِ","units":[{"id":"um56_1","label":"الحديث ٢٦٦ · المقطع ١ من ٤","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«جَاءَتْنِي بَرِيرَةُ فَقَالَتْ: كَاتَبْتُ أَهْلِي عَلَى تِسْعِ أَوَاقٍ، فِي كُلِّ عَامٍ أُوقِيَّةٌ فَأَعِينِينِي، فَقُلْتُ: إِنْ أَحَبَّ أَهْلُكِ أَنْ أَعُدَّهَا لَهُمْ وَيَكُونَ وَلَاؤُكِ لِي فَعَلْتُ، فَذَهَبَتْ بَرِيرَةُ إِلَى أَهْلِهَا، فَقَالَتْ لَهُمْ، فَأَبَوْا عَلَيْهَا،"]]},{"id":"um56_2","label":"الحديث ٢٦٦ · المقطع ٢ من ٤","segs":[["matn","فَجَاءَتْ مِنْ عِنْدِهِمْ - وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ -، فَقَالَتْ: إِنِّي عَرَضْتُ ذَلِكَ عَلَيْهِمْ فَأَبَوْا إِلَّا أَنْ يَكُونَ لَهُمُ الوَلَاءُ، فَأَخْبَرَتْ عَائِشَةُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: خُذِيهَا وَاشْتَرِطِي لَهُمُ الوَلَاءَ،"]]},{"id":"um56_3","label":"الحديث ٢٦٦ · المقطع ٣ من ٤","segs":[["matn","فَإِنَّمَا الوَلَاءُ لِمَنْ أَعْتَقَ؛ فَفَعَلَتْ عَائِشَةُ، ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي النَّاسِ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: أَمَّا بَعْدُ، مَا بَالُ رِجَالٍ يَشْتَرِطُونَ شُرُوطاً لَيْسَتْ فِي كِتَابِ اللَّهِ،"]]},{"id":"um56_4","label":"الحديث ٢٦٦ · المقطع ٤ من ٤","segs":[["matn","مَا كَانَ مِنْ شَرْطٍ لَيْسَ فِي كِتَابِ اللَّهِ فَهُوَ بَاطِلٌ وَإِنْ كَانَ مِئَةَ شَرْطٍ؛ قَضَاءُ اللَّهِ أَحَقُّ، وَشَرْطُ اللَّهِ أَوْثَقُ، وَإِنَّمَا الوَلَاءُ لِمَنْ أَعْتَقَ»."]]},{"id":"um56_5","label":"الحديث ٢٦٧ · المقطع ١ من ٢","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّهُ كَانَ يَسِيرُ عَلَى جَمَلٍ فَأَعْيَا، فَأَرَادَ أَنْ يُسَيِّبَهُ، فَلَحِقَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَعَا لِي وَضَرَبَهُ، فَسَارَ سَيْراً لَمْ يَسِرْ مِثْلَهُ، قَالَ: بِعْنِيهِ بِأُوقِيَّةٍ، قُلْتُ: لَا، ثُمَّ قَالَ: بِعْنِيهِ، فَبِعْتُهُ بِأُوقِيَّةٍ،"]]},{"id":"um56_6","label":"الحديث ٢٦٧ · المقطع ٢ من ٢","segs":[["matn","وَاسْتَثْنَيْتُ حُمْلَانَهُ إِلَى أَهْلِي، فَلَمَّا بَلَغْتُ أَتَيْتُهُ بِالجَمَلِ فَنَقَدَنِي ثَمَنَهُ، ثُمَّ رَجَعْتُ، فَأَرْسَلَ فِي أَثَرِي فَقَالَ: أَتُرَانِي مَاكَسْتُكَ لِآخُذَ جَمَلَكَ؟ خُذْ جَمَلَكَ وَدَرَاهِمَكَ فَهُوَ لَكَ»."]]},{"id":"um56_7","label":"الحديث ٢٦٨","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبِيعَ حَاضِرٌ لِبَادٍ، وَلَا تَنَاجَشُوا، وَلَا يَبِيعُ الرَّجُلُ عَلَى بَيْعِ أَخِيهِ، وَلَا يَخْطُبُ عَلَى خِطْبَةِ أَخِيهِ، وَلَا تَسْأَلِ المَرْأَةُ طَلَاقَ أُخْتِهَا لِتَكْفَأَ مَا فِي إِنَائِهَا»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um57","title":"بَابُ الرِّبَا وَالصَّرْفِ","units":[{"id":"um57_1","label":"الحديث ٢٦٩","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «الذَّهَبُ بِالوَرِقِ رِباً؛ إِلَّا هَاءَ وَهَاءَ، وَالبُرُّ بِالبُرِّ رِباً؛ إِلَّا هَاءَ وَهَاءَ، وَالشَّعِيرُ بِالشَّعِيرِ رِباً؛ إِلَّا هَاءَ وَهَاءَ»."]]},{"id":"um57_2","label":"الحديث ٢٧٠ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا تَبِيعُوا الذَّهَبَ بِالذَّهَبِ إِلَّا مِثْلاً بِمِثْلٍ، وَلَا تُشِفُّوا بَعْضَهَا عَلَى بَعْضٍ، وَلَا تَبِيعُوا الوَرِقَ بِالوَرِقِ إِلَّا مِثْلاً بِمِثْلٍ، وَلَا تُشِفُّوا بَعْضَهَا عَلَى بَعْضٍ، وَلَا تَبِيعُوا مِنْهَا غَائِباً بِنَاجِزٍ». وَفِي لَفْظٍ: «إِلَّا يَداً بِيَدٍ»."]]},{"id":"um57_3","label":"الحديث ٢٧٠ · المقطع ٢ من ٢","segs":[["matn","وَفِي لَفْظٍ: «إِلَّا وَزْناً بِوَزْنٍ؛ مِثْلاً بِمِثْلٍ، سَوَاءً بِسَوَاءٍ»."]]},{"id":"um57_4","label":"الحديث ٢٧١ · المقطع ١ من ٢","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«جَاءَ بِلَالٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَمْرٍ بَرْنِيٍّ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مِنْ أَيْنَ هَذَا؟ قَالَ بِلَالٌ: كَانَ عِنْدَنَا تَمْرٌ رَدِيءٌ، فَبِعْتُ مِنْهُ صَاعَيْنِ بِصَاعٍ؛"]]},{"id":"um57_5","label":"الحديث ٢٧١ · المقطع ٢ من ٢","segs":[["matn","لِيَطْعَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: أَوَّهْ! عَيْنُ الرِّبَا، عَيْنُ الرِّبَا؛ لَا تَفْعَلْ؛ وَلَكِنْ إِذَا أَرَدْتَ أَنْ تَشْتَرِيَ فَبِعِ التَّمْرَ بِبَيْعٍ آخَرَ، ثُمَّ اشْتَرِ بهِ»."]]},{"id":"um57_6","label":"الحديث ٢٧٢","segs":[["rawi","عَنْ أَبِي المِنْهَالِ قَالَ:"],["matn","«سَأَلْتُ البَرَاءَ بْنَ عَازِبٍ وَزَيْدَ بْنَ أَرْقَمَ رَضِيَ اللَّهُ عَنْهُمْ عَنِ الصَّرْفِ؛ فَكُلُّ وَاحِدٍ مِنْهُمَا يَقُولُ: هَذَا خَيْرٌ مِنِّي، وَكِلَاهُمَا يَقُولُ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الذَّهَبِ بِالوَرِقِ دَيْناً»."]]},{"id":"um57_7","label":"الحديث ٢٧٣","segs":[["rawi","عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الفِضَّةِ بِالفِضَّةِ، وَالذَّهَبِ بِالذَّهَبِ؛ إِلَّا سَوَاءً بِسَوَاءٍ، وَأَمَرَنَا أَنْ نَشْتَرِيَ الفِضَّةَ بِالذَّهَبِ كَيْفَ شِئْنَا، وَنَشْتَرِيَ الذَّهَبَ بِالفِضَّةِ كَيْفَ شِئْنَا، قَالَ: فَسَأَلَهُ رَجُلٌ فَقَالَ: يَداً بِيَدٍ؟ فَقَالَ: هَكَذَا سَمِعْتُ»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um58","title":"بَابُ الرَّهْنِ وَغَيْرِهِ","units":[{"id":"um58_1","label":"الحديث ٢٧٤","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اشْتَرَى طَعَاماً مِنْ يَهُودِيٍّ، وَرَهَنَهُ دِرْعاً مِنْ حَدِيدٍ»."]]},{"id":"um58_2","label":"الحديث ٢٧٥","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَطْلُ الغَنِيِّ ظُلْمٌ؛ فَإِذَا أُتْبِعَ أَحَدُكُمْ عَلَى مَلِيءٍ فَلْيَتْبَعْ»."]]},{"id":"um58_3","label":"الحديث ٢٧٦","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَوْ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ -:"],["matn","«مَنْ أَدْرَكَ مَالَهُ بِعَيْنِهِ عِنْدَ رَجُلٍ - أَوْ إِنْسَانٍ - قَدْ أَفْلَسَ؛ فَهُوَ أَحَقُّ بِهِ مِنْ غَيْرِهِ»."]]},{"id":"um58_4","label":"الحديث ٢٧٧","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«جَعَلَ - وَفِي لَفْظٍ: قَضَى - النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالشُّفْعَةِ فِي كُلِّ مَالٍ لَمْ يُقْسَمْ، فَإِذَا وَقَعَتِ الحُدُودُ، وَصُرِّفَتِ الطُّرُقُ؛ فَلَا شُفْعَةَ»."]]},{"id":"um58_5","label":"الحديث ٢٧٨ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أَصَابَ عُمَرُ أَرْضاً بِخَيْبَرَ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَأْمِرُهُ فِيهَا، فَقَالَ: يَا رَسُولَ اللَّهِ! إِنِّي أَصَبْتُ أَرْضاً بِخَيْبَرَ لَمْ أُصِبْ مَالاً قَطُّ هُوَ أَنْفَسُ عِنْدِي مِنْهُ، فَمَا تَأْمُرُنِي بِهِ؟ قَالَ:"]]},{"id":"um58_6","label":"الحديث ٢٧٨ · المقطع ٢ من ٣","segs":[["matn","إِنْ شِئْتَ حَبَّسْتَ أَصْلَهَا، وَتَصَدَّقْتَ بِهَا، قَالَ: فَتَصَدَّقَ بِهَا؛ غَيْرَ أَنَّهُ لَا يُبَاعُ أَصْلُهَا، وَلَا يُورَثُ، وَلَا يُوهَبُ، قَالَ: فَتَصَدَّقَ عُمَرُ فِي الفُقَرَاءِ، وَفِي القُرْبَى، وَفِي الرِّقَابِ، وَفِي سَبِيلِ اللَّهِ، وَابْنِ السَّبِيلِ، وَالضَّيْفِ،"]]},{"id":"um58_7","label":"الحديث ٢٧٨ · المقطع ٣ من ٣","segs":[["matn","لَا جُنَاحَ عَلَى مَنْ وَلِيَهَا أَنْ يَأْكُلَ مِنْهَا بِالمَعْرُوفِ، أَوْ يُطْعِمَ صَدِيقاً؛ غَيْرَ مُتَمَوِّلٍ فِيهِ». وَفِي لَفْظٍ: «غَيْرَ مُتَأَثِّلٍ»."]]},{"id":"um58_8","label":"الحديث ٢٧٩ · المقطع ١ من ٢","segs":[["rawi","عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«حَمَلْتُ عَلَى فَرَسٍ فِي سَبِيلِ اللَّهِ، فَأَضَاعَهُ الَّذِي كَانَ عِنْدَهُ، فَأَرَدْتُ أَنْ أَشْتَرِيَهُ وَظَنَنْتُ أَنَّهُ يَبِيعُهُ بِرُخْصٍ؛ فَسَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لَا تَشْتَرِهِ وَلَا تَعُدْ فِي صَدَقَتِكَ - وَإِنْ أَعْطَاكَهُ بِدِرْهَمٍ -؛"]]},{"id":"um58_9","label":"الحديث ٢٧٩ · المقطع ٢ من ٢","segs":[["matn","فَإِنَّ العَائِدَ فِي هِبَتِهِ كَالعَائِدِ فِي قَيْئِهِ». وَفِي لَفْظٍ: «فَإِنَّ الَّذِي يَعُودُ فِي صَدَقَتِهِ كَالكَلْبِ يَعُودُ فِي قَيْئِهِ»."]]},{"id":"um58_10","label":"الحديث ٢٨٠","segs":[["rawi","وَعَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«العَائِدُ فِي هِبَتِهِ كَالعَائِدِ فِي قَيْئِهِ»."]]},{"id":"um58_11","label":"الحديث ٢٨١ · المقطع ١ من ٣","segs":[["rawi","عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«تَصَدَّقَ عَلَيَّ أَبِي بِبَعْضِ مَالِهِ، فَقَالَتْ أُمِّي - عَمْرَةُ بِنْتُ رَوَاحَةَ -: لَا أَرْضَى حَتَّى تُشْهِدَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَانْطَلَقَ أَبِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُشْهِدَهُ عَلَى صَدَقَتِي،"]]},{"id":"um58_12","label":"الحديث ٢٨١ · المقطع ٢ من ٣","segs":[["matn","فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفَعَلْتَ هَذَا بِوَلَدِكَ كُلِّهِمْ؟ قَالَ: لَا، قَالَ: اتَّقُوا اللَّهَ، وَاعْدِلُوا فِي أَوْلَادِكُمْ، فَرَجَعَ أَبِي فَرَدَّ تِلْكَ الصَّدَقَةَ». وَفِي لَفْظٍ: «قَالَ: فَلَا تُشْهِدْنِي إِذَنْ؛"]]},{"id":"um58_13","label":"الحديث ٢٨١ · المقطع ٣ من ٣","segs":[["matn","فَإِنِّي لَا أَشْهَدُ عَلَى جَوْرٍ». وَفِي لَفْظٍ: «فَأَشْهِدْ عَلَى هَذَا غَيْرِي»."]]},{"id":"um58_14","label":"الحديث ٢٨٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَلَ أَهْلَ خَيْبَرَ بِشَطْرِ مَا يَخْرُجُ مِنْهَا مِنْ ثَمَرٍ أَوْ زَرْعٍ»."]]},{"id":"um58_15","label":"الحديث ٢٨٣ · المقطع ١ من ٣","segs":[["rawi","عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كُنَّا أَكْثَرَ الأَنْصَارِ حَقْلاً؛ فَكُنَّا نُكْرِي الأَرْضَ عَلَى أَنَّ لَنَا هَذِهِ وَلَهُمْ هَذِهِ، فَرُبَّمَا أَخْرَجَتْ هَذِهِ وَلَمْ تُخْرِجْ هَذِهِ؛ فَنَهَانَا عَنْ ذَلِكَ، وَأَمَّا الوَرِقُ فَلَمْ يَنْهَنَا». وَلِمُسْلِمٍ عَنْ حَنْظَلَةَ بْنِ قَيْسٍ قَالَ:"]]},{"id":"um58_16","label":"الحديث ٢٨٣ · المقطع ٢ من ٣","segs":[["matn","«سَأَلْتُ رَافِعَ بْنَ خَدِيجٍ رَضِيَ اللَّهُ عَنْهُ عَنْ كِرَاءِ الأَرْضِ بِالذَّهَبِ وَالوَرِقِ، فَقَالَ: لَا بَأْسَ بِهِ؛ إِنَّمَا كَانَ النَّاسُ يُؤَاجِرُونَ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا عَلَى المَاذِيَانَاتِ، وَأَقْبَالِ الجَدَاوِلِ، وَأَشْيَاءَ مِنَ الزَّرْعِ،"]]},{"id":"um58_17","label":"الحديث ٢٨٣ · المقطع ٣ من ٣","segs":[["matn","فَيَهْلِكُ هَذَا وَيَسْلَمُ هَذَا، وَيَسْلَمُ هَذَا وَيَهْلِكُ هَذَا، وَلَمْ يَكُنْ لِلنَّاسِ كِرَاءٌ إِلَّا هَذَا، فَلِذَلِكَ زَجَرَ عَنْهُ، فَأَمَّا شَيْءٌ مَعْلُومٌ مَضْمُونٌ فَلَا بَأْسَ بِهِ»."]]},{"id":"um58_18","label":"الحديث ٢٨٤ · المقطع ١ من ٣","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالعُمْرَى لِمَنْ وُهِبَتْ لَهُ». وَفِي لَفْظٍ: «مَنْ أُعْمِرَ عُمْرَى لَهُ وَلِعَقِبِهِ فَإِنَّهَا لِلَّذِي أُعْطِيَهَا، لَا تَرْجِعُ إِلَى الَّذِي أَعْطَاهَا؛ لِأَنَّهُ أَعْطَى عَطَاءً وَقَعَتْ فِيهِ المَوَارِيثُ»."]]},{"id":"um58_19","label":"الحديث ٢٨٤ · المقطع ٢ من ٣","segs":[["matn","وَقَالَ جَابِرٌ رَضِيَ اللَّهُ عَنْهُ: «إِنَّمَا العُمْرَى الَّتِي أَجَازَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنْ يَقُولَ: هِيَ لَكَ وَلِعَقِبِكَ؛ فَأَمَّا إِذَا قَالَ: هِيَ لَكَ مَا عِشْتَ؛ فَإِنَّهَا تَرْجِعُ إِلَى صَاحِبِهَا». وَفِي لَفْظٍ لِمُسْلِمٍ:"]]},{"id":"um58_20","label":"الحديث ٢٨٤ · المقطع ٣ من ٣","segs":[["matn","«أَمْسِكُوا عَلَيْكُمْ أَمْوَالَكُمْ وَلَا تُفْسِدُوهَا، فَإِنَّهُ مَنْ أَعْمَرَ عُمْرَى فَهِيَ لِلَّذِي أُعْمِرَهَا حَيّاً وَمَيِّتاً وَلِعَقِبِهِ»."]]},{"id":"um58_21","label":"الحديث ٢٨٥","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا يَمْنَعَنَّ جَارٌ جَارَهُ أَنْ يَغْرِزَ خَشَبَةً فِي جِدَارِهِ، ثُمَّ يَقُولُ أَبُو هُرَيْرَةَ: مَا لِي أَرَاكُمْ عَنْهَا مُعْرِضِينَ؟ وَاللَّهِ! لَأَرْمِيَنَّ بِهَا بَيْنَ أَكْتَافِكُمْ»."]]},{"id":"um58_22","label":"الحديث ٢٨٦","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ ظَلَمَ قِيدَ شِبْرٍ مِنَ الأَرْضِ؛ طُوِّقَهُ مِنْ سَبْعِ أَرَضِينَ»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um59","title":"بَابُ اللُّقَطَةِ","units":[{"id":"um59_1","label":"الحديث ٢٨٧ · المقطع ١ من ٢","segs":[["rawi","عَنْ زَيْدِ بْنِ خَالِدٍ الجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ اللُّقَطَةِ؛ الذَّهَبِ أَوِ الوَرِقِ؛ فَقَالَ: اعْرِفْ وِكَاءَهَا وَعِفَاصَهَا، ثُمَّ عَرِّفْهَا سَنَةً، فَإِنْ لَمْ تُعْرَفْ فَاسْتَنْفِقْهَا، وَلْتَكُنْ وَدِيعَةً عِنْدَكَ، فَإِنْ جَاءَ طَالِبُهَا يَوْماً مِنَ الدَّهْرِ فَأَدِّهَا إِلَيْهِ،"]]},{"id":"um59_2","label":"الحديث ٢٨٧ · المقطع ٢ من ٢","segs":[["matn","وَسَأَلَهُ عَنْ ضَالَّةِ الإِبِلِ؛ فَقَالَ: مَا لَكَ وَلَهَا؟ دَعْهَا؛ فَإِنَّ مَعَهَا حِذَاءَهَا وَسِقَاءَهَا، تَرِدُ المَاءَ، وَتَأْكُلُ الشَّجَرَ، حَتَّى يَجِدَهَا رَبُّهَا، وَسَأَلَهُ عَنِ الشَّاةِ؛ فَقَالَ: خُذْهَا؛ فَإِنَّمَا هِيَ لَكَ، أَوْ لِأَخِيكَ، أَوْ لِلذِّئْبِ»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um60","title":"بَابُ الوَصَايَا","units":[{"id":"um60_1","label":"الحديث ٢٨٨ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَا حَقُّ امْرِئٍ مُسْلِمٍ لَهُ شَيْءٌ يُوصِي فِيهِ، يَبِيتُ لَيْلَتَيْنِ؛ إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ». زَادَ مُسْلِمٌ: «قَالَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"]]},{"id":"um60_2","label":"الحديث ٢٨٨ · المقطع ٢ من ٢","segs":[["matn","مَا مَرَّتْ عَلَيَّ لَيْلَةٌ مُنْذُ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ ذَلِكَ إِلَّا وَعِنْدِي وَصِيَّتِي»."]]},{"id":"um60_3","label":"الحديث ٢٨٩ · المقطع ١ من ٥","segs":[["rawi","عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«جَاءَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي عَامَ حَجَّةِ الوَدَاعِ مِنْ وَجَعٍ اشْتَدَّ بِي، فَقُلْتُ: يَا رَسُولَ اللَّهِ! قَدْ بَلَغَ بِي مِنَ الوَجَعِ مَا تَرَى، وَأَنَا ذُو مَالٍ وَلَا يَرِثُنِي إِلَّا ابْنَةٌ؛"]]},{"id":"um60_4","label":"الحديث ٢٨٩ · المقطع ٢ من ٥","segs":[["matn","أَفَأَتَصَدَّقُ بِثُلُثَيْ مَالِي؟ قَالَ: لَا، قُلْتُ: فَالشَّطْرُ يَا رَسُولَ اللَّهِ؟ قَالَ: لَا، قُلْتُ: فَالثُّلُثُ؟ قَالَ: الثُّلُثُ؛ وَالثُّلُثُ كَثِيرٌ؛ إِنَّكَ أَنْ تَذَرَ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ مِنْ أَنْ تَذَرَهُمْ عَالَةً يَتَكَفَّفُونَ النَّاسَ،"]]},{"id":"um60_5","label":"الحديث ٢٨٩ · المقطع ٣ من ٥","segs":[["matn","وَإِنَّكَ لَنْ تُنْفِقَ نَفَقَةً تَبْتَغِي بِهَا وَجْهَ اللَّهِ إِلَّا أُجِرْتَ بِهَا؛ حَتَّى مَا تَجْعَلُ فِي فِي امْرَأَتِكَ، قَالَ: فَقُلْتُ: يَا رَسُولَ اللَّهِ! أُخَلَّفُ بَعْدَ أَصْحَابِي؟ قَالَ:"]]},{"id":"um60_6","label":"الحديث ٢٨٩ · المقطع ٤ من ٥","segs":[["matn","إِنَّكَ لَنْ تُخَلَّفَ فَتَعْمَلَ عَمَلاً تَبْتَغِي بِهِ وَجْهَ اللَّهِ إِلَّا ازْدَدْتَ بِهِ دَرَجَةً وَرِفْعَةً، وَلَعَلَّكَ أَنْ تُخَلَّفَ حَتَّى يَنْتَفِعَ بِكَ أَقْوَامٌ وَيُضَرَّ بِكَ آخَرُونَ، اللَّهُمَّ أَمْضِ لِأَصْحَابِي هِجْرَتَهُمْ، وَلَا تَرُدُّهُمْ عَلَى أَعْقَابِهِمْ،"]]},{"id":"um60_7","label":"الحديث ٢٨٩ · المقطع ٥ من ٥","segs":[["matn","لَكِنِ البَائِسُ سَعْدُ بْنُ خَوْلَةَ؛ يَرْثِي لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ مَاتَ بِمَكَّةَ»."]]},{"id":"um60_8","label":"الحديث ٢٩٠","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«لَوْ أَنَّ النَّاسَ غَضُّوا مِنَ الثُّلُثِ إِلَى الرُّبُعِ؛ فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الثُّلُثُ؛ وَالثُّلُثُ كَثِيرٌ»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um61","title":"بَابُ الفَرَائِضِ","units":[{"id":"um61_1","label":"الحديث ٢٩١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«أَلْحِقُوا الفَرَائِضَ بِأَهْلِهَا؛ فَمَا بَقِيَ فَهُوَ لِأَوْلَى رَجُلٍ ذَكَرٍ». وَفِي رِوَايَةٍ: «اقْسِمُوا المَالَ بَيْنَ أَهْلِ الفَرَائِضِ عَلَى كِتَابِ اللَّهِ، فَمَا تَرَكَتِ الفَرَائِضُ فَلِأَوْلَى رَجُلٍ ذَكَرٍ»."]]},{"id":"um61_2","label":"الحديث ٢٩٢","segs":[["rawi","عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«قُلْتُ: يَا رَسُولَ اللَّهِ! أَتَنْزِلُ غَداً فِي دَارِكَ بِمَكَّةَ؟ قَالَ: وَهَلْ تَرَكَ لَنَا عَقِيلٌ مِنْ رِبَاعٍ؟ ثُمَّ قَالَ: لَا يَرِثُ الكَافِرُ المُسْلِمَ، وَلَا المُسْلِمُ الكَافِرَ»."]]},{"id":"um61_3","label":"الحديث ٢٩٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الوَلَاءِ، وَعَنْ هِبَتِهِ»."]]},{"id":"um61_4","label":"الحديث ٢٩٤ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ:"],["matn","«كَانَتْ فِي بَرِيرَةَ ثَلَاثُ سُنَنٍ: خُيِّرَتْ عَلَى زَوْجِهَا حِينَ عَتَقَتْ، وَأُهْدِيَ لَهَا لَحْمٌ، فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالبُرْمَةُ عَلَى النَّارِ، فَدَعَا بِطَعَامٍ؛ فَأُتِيَ بِخُبْزٍ وَأُدُمٍ مِنْ أُدُمِ البَيْتِ، فَقَالَ:"]]},{"id":"um61_5","label":"الحديث ٢٩٤ · المقطع ٢ من ٣","segs":[["matn","أَلَمْ أَرَ البُرْمَةَ عَلَى النَّارِ فِيهَا لَحْمٌ؟ فَقَالُوا: بَلَى يَا رَسُولَ اللَّهِ؛ ذَلِكَ لَحْمٌ تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ، فَكَرِهْنَا أَنْ نُطْعِمَكَ مِنْهُ، فَقَالَ: هُوَ عَلَيْهَا صَدَقَةٌ، وَهُوَ مِنْهَا لَنَا هَدِيَّةٌ،"]]},{"id":"um61_6","label":"الحديث ٢٩٤ · المقطع ٣ من ٣","segs":[["matn","وَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا: إِنَّمَا الوَلَاءُ لِمَنْ أَعْتَقَ»."]]}],"group":"كِتَابُ البُيُوعِ"},{"id":"um62","title":"كِتَابُ النِّكَاحِ","units":[{"id":"um62_1","label":"الحديث ٢٩٥","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «يَا مَعْشَرَ الشَّبَابِ! مَنِ اسْتَطَاعَ مِنْكُمُ البَاءَةَ فَلْيَتَزَوَّجْ؛ فَإِنَّهُ أَغَضُّ لِلْبَصَرِ، وَأَحْصَنُ لِلْفَرْجِ، وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ؛ فَإِنَّهُ لَهُ وِجَاءٌ»."]]},{"id":"um62_2","label":"الحديث ٢٩٦ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ نَفَراً مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَأَلُوا أَزْوَاجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ عَمَلِهِ فِي السِّرِّ؛ فَقَالَ بَعْضُهُمْ: لَا أَتَزَوَّجُ النِّسَاءَ، وَقَالَ بَعْضُهُمْ: لَا آكُلُ اللَّحْمَ، وَقَالَ بَعْضُهُمْ:"]]},{"id":"um62_3","label":"الحديث ٢٩٦ · المقطع ٢ من ٢","segs":[["matn","لَا أَنَامُ عَلَى فِرَاشٍ، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَقَالَ: مَا بَالُ أَقْوَامٍ قَالُوا كَذَا؟ لَكِنِّي أُصَلِّي وَأَنَامُ، وَأَصُومُ وَأُفْطِرُ، وَأَتَزَوَّجُ النِّسَاءَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي»."]]},{"id":"um62_4","label":"الحديث ٢٩٧","segs":[["rawi","عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«رَدَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عُثْمَانَ بْنِ مَظْعُونٍ التَّبَتُّلَ، وَلَوْ أَذِنَ لَهُ لَاخْتَصَيْنَا»."]]},{"id":"um62_5","label":"الحديث ٢٩٨ · المقطع ١ من ٤","segs":[["rawi","عَنْ أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهَا قَالَتْ:"],["matn","«يَا رَسُولَ اللَّهِ! انْكِحْ أُخْتِي ابْنَةَ أَبِي سُفْيَانَ، فَقَالَ: أَوَ تُحِبِّينَ ذَلِكِ؟ فَقُلْتُ: نَعَمْ؛ لَسْتُ لَكَ بِمُخْلِيَةٍ، وَأَحَبُّ مَنْ شَارَكَنِي فِي خَيْرٍ: أُخْتِي، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ ذَلِكِ لَا يَحِلُّ لِي، قَالَتْ:"]]},{"id":"um62_6","label":"الحديث ٢٩٨ · المقطع ٢ من ٤","segs":[["matn","فَإِنَّا نُحَدَّثُ أَنَّكَ تُرِيدُ أَنْ تَنْكِحَ بِنْتَ أَبِي سَلَمَةَ، قَالَ: بِنْتُ أُمِّ سَلَمَةَ؟! قُلْتُ: نَعَمْ، قَالَ: إِنَّهَا لَوْ لَمْ تَكُنْ رَبِيبَتِي فِي حَجْرِي مَا حَلَّتْ لِي؛ إِنَّهَا لَابْنَةُ أَخِي مِنَ الرَّضَاعَةِ، أَرْضَعَتْنِي وَأَبَا سَلَمَةَ ثُوَيْبَةُ،"]]},{"id":"um62_7","label":"الحديث ٢٩٨ · المقطع ٣ من ٤","segs":[["matn","فَلَا تَعْرِضْنَ عَلَيَّ بَنَاتِكُنَّ وَلَا أَخَوَاتِكُنَّ، قَالَ عُرْوَةُ: وَثُوَيْبَةُ مَوْلَاةٌ لِأَبِي لَهَبٍ، كَانَ أَبُو لَهَبٍ أَعْتَقَهَا، فَأَرْضَعَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ فَلَمَّا مَاتَ أَبُو لَهَبٍ أُرِيَهُ بَعْضُ أَهْلِهِ بِشَرِّ حِيبَةٍ، قَالَ لَهُ: مَاذَا لَقِيتَ؟"]]},{"id":"um62_8","label":"الحديث ٢٩٨ · المقطع ٤ من ٤","segs":[["matn","قَالَ لَهُ أَبُو لَهَبٍ: لَمْ أَلْقَ بَعْدَكُمْ خَيْراً غَيْرَ أَنِّي سُقِيتُ فِي هَذِهِ بِعَتَاقَتِي ثُوَيْبَةَ»."]]},{"id":"um62_9","label":"الحديث ٢٩٩","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«لَا يُجْمَعُ بَيْنَ المَرْأَةِ وَعَمَّتِهَا، وَلَا بَيْنَ المَرْأَةِ وَخَالَتِهَا»."]]},{"id":"um62_10","label":"الحديث ٣٠٠","segs":[["rawi","عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ أَحَقَّ الشُّرُوطِ أَنْ تُوفُوا بِهِ مَا اسْتَحْلَلْتُمْ بِهِ الفُرُوجَ»."]]},{"id":"um62_11","label":"الحديث ٣٠١","segs":[["rawi","عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الشِّغَارِ - وَالشِّغَارُ: أَنْ يُزَوِّجَ الرَّجُلُ ابْنَتَهُ عَلَى أَنْ يُزَوِّجَهُ ابْنَتَهُ، وَلَيْسَ بَيْنَهُمَا صَدَاقٌ -»."]]},{"id":"um62_12","label":"الحديث ٣٠٢","segs":[["rawi","عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ نِكَاحِ المُتْعَةِ يَوْمَ خَيْبَرَ، وَعَنْ لُحُومِ الحُمُرِ الأَهْلِيَّةِ»."]]},{"id":"um62_13","label":"الحديث ٣٠٣","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا تُنْكَحُ الأَيِّمُ حَتَّى تُسْتَأْمَرَ، وَلَا تُنْكَحُ البِكْرُ حَتَّى تُسْتَأْذَنَ؛ قَالُوا: يَا رَسُولَ اللَّهِ! فَكَيْفَ إِذْنُهَا؟ قَالَ: أَنْ تَسْكُتَ»."]]},{"id":"um62_14","label":"الحديث ٣٠٤ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«جَاءَتِ امْرَأَةُ رِفَاعَةَ القُرَظِيِّ رَضِيَ اللَّهُ عَنْهُمَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: كُنْتُ عِنْدَ رِفَاعَةَ القُرَظِيِّ فَطَلَّقَنِي فَبَتَّ طَلَاقِي، فَتَزَوَّجْتُ بَعْدَهُ عَبْدَ الرَّحْمَنِ بْنَ الزَّبِيرِ، وَإِنَّمَا مَعَهُ مِثْلُ هُدْبَةِ الثَّوْبِ،"]]},{"id":"um62_15","label":"الحديث ٣٠٤ · المقطع ٢ من ٣","segs":[["matn","فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَتُرِيدِينَ أَنْ تَرْجِعِي إِلَى رِفَاعَةَ؟ لَا، حَتَّى تَذُوقِي عُسَيْلَتَهُ، وَيَذُوقَ عُسَيْلَتَكِ، قَالَتْ: وَأَبُو بَكْرٍ عِنْدَهُ، وَخَالِدُ بْنُ سَعِيدٍ بِالبَابِ يَنْتَظِرُ أَنْ يُؤْذَنَ لَهُ، فَنَادَى: يَا أَبَا بَكْرٍ!"]]},{"id":"um62_16","label":"الحديث ٣٠٤ · المقطع ٣ من ٣","segs":[["matn","أَلَا تَسْمَعُ هَذِهِ مَا تَجْهَرُ بِهِ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟»."]]},{"id":"um62_17","label":"الحديث ٣٠٥","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«مِنَ السُّنَّةِ: إِذَا تَزَوَّجَ البِكْرَ عَلَى الثَّيِّبِ أَقَامَ عِنْدَهَا سَبْعاً وَقَسَمَ، وَإِذَا تَزَوَّجَ الثَّيِّبَ أَقَامَ عِنْدَهَا ثَلَاثاً ثُمَّ قَسَمَ، قَالَ أَبُو قِلَابَةَ: وَلَوْ شِئْتُ لَقُلْتُ: إِنَّ أَنَساً رَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ»."]]},{"id":"um62_18","label":"الحديث ٣٠٦","segs":[["rawi","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَوْ أَنَّ أَحَدَهُمْ إِذَا أَرَادَ أَنْ يَأْتِيَ أَهْلَهُ قَالَ: بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا؛ فَإِنَّهُ إِنْ يُقَدَّرْ بَيْنَهُمَا وَلَدٌ فِي ذَلِكَ؛ لَمْ يَضُرُّهُ الشَّيْطَانُ أَبَداً»."]]},{"id":"um62_19","label":"الحديث ٣٠٧","segs":[["rawi","عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ! فَقَالَ رَجُلٌ مِنَ الأَنْصَارِ: يَا رَسُولَ اللَّهِ! أَفَرَأَيْتَ الحَمْوَ؟ قَالَ: الحَمْوُ المَوْتُ». وَلِمُسْلِمٍ: عَنْ أَبِي الطَّاهِرِ، عَنِ ابْنِ وَهْبٍ قَالَ: سَمِعْتُ اللَّيْثَ يَقُولُ: «الحَمْوُ: أَخُو الزَّوْجِ وَمَا أَشْبَهَهُ مِنْ أَقَارِبِ الزَّوْجِ؛ ابْنِ العَمِّ وَنَحْوِهِ»."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"um63","title":"بَابُ الصَّدَاقِ","units":[{"id":"um63_1","label":"الحديث ٣٠٨","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْتَقَ صَفِيَّةَ، وَجَعَلَ عِتْقَهَا صَدَاقَهَا»."]]},{"id":"um63_2","label":"الحديث ٣٠٩ · المقطع ١ من ٣","segs":[["rawi","عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَاءَتْهُ امْرَأَةٌ فَقَالَتْ: إِنِّي وَهَبْتُ نَفْسِي لَكَ، فَقَامَتْ طَوِيلاً، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ! زَوِّجْنِيهَا إِنْ لَمْ يَكُنْ لَكَ بِهَا حَاجَةٌ؛ فَقَالَ: هَلْ عِنْدَكَ مِنْ شَيْءٍ تُصْدِقُهَا؟ قَالَ:"]]},{"id":"um63_3","label":"الحديث ٣٠٩ · المقطع ٢ من ٣","segs":[["matn","مَا عِنْدِي إِلَّا إِزَارِي هَذَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِزَارُكَ إِنْ أَعْطَيْتَهَا جَلَسْتَ وَلَا إِزَارَ لَكَ، فَالْتَمِسْ شَيْئاً، قَالَ: مَا أَجِدُ، قَالَ: فَالْتَمِسْ وَلَوْ خَاتَماً مِنْ حَدِيدٍ! فَالْتَمَسَ فَلَمْ يَجِدْ شَيْئاً،"]]},{"id":"um63_4","label":"الحديث ٣٠٩ · المقطع ٣ من ٣","segs":[["matn","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: زَوَّجْتُكَهَا بِمَا مَعَكَ مِنَ القُرْآنِ»."]]},{"id":"um63_5","label":"الحديث ٣١٠ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ وَعَلَيْهِ رَدْعُ زَعْفَرَانٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَهْيَمْ؟ فَقَالَ: يَا رَسُولَ اللَّهِ! تَزَوَّجْتُ امْرَأَةً، فَقَالَ: مَا أَصْدَقْتَهَا؟ قَالَ:"]]},{"id":"um63_6","label":"الحديث ٣١٠ · المقطع ٢ من ٢","segs":[["matn","وَزْنَ نَوَاةٍ مِنْ ذَهَبٍ، قَالَ: فَبَارَكَ اللَّهُ لَكَ، أَوْلِمْ وَلَوْ بِشَاةٍ»."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"um64","title":"كِتَابُ الطَّلَاقِ","units":[{"id":"um64_1","label":"الحديث ٣١١ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّهُ طَلَّقَ امْرَأَةً لَهُ وَهِيَ حَائِضٌ، فَذَكَرَ ذَلِكَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَتَغَيَّظَ فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: لِيُرَاجِعْهَا ثُمَّ يُمْسِكْهَا حَتَّى تَطْهُرَ،"]]},{"id":"um64_2","label":"الحديث ٣١١ · المقطع ٢ من ٣","segs":[["matn","ثُمَّ تَحِيضَ فَتَطْهُرَ، فَإِنْ بَدَا لَهُ أَنْ يُطَلِّقَهَا؛ فَلْيُطَلِّقْهَا قَبْلَ أَنْ يَمَسَّهَا، فَتِلْكَ العِدَّةُ كَمَا أَمَرَ اللَّهُ عَزَّ وَجَلَّ». وَفِي لَفْظٍ: «حَتَّى تَحِيضَ حَيْضَةً مُسْتَقْبَلَةً، سِوَى حَيْضَتِهَا الَّتِي طَلَّقَهَا فِيهَا». وَفِي لَفْظٍ: «فَحُسِبَتْ مِنْ طَلَاقِهَا،"]]},{"id":"um64_3","label":"الحديث ٣١١ · المقطع ٣ من ٣","segs":[["matn","وَرَاجَعَهَا عَبْدُ اللَّهِ كَمَا أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ»."]]},{"id":"um64_4","label":"الحديث ٣١٢ · المقطع ١ من ٤","segs":[["rawi","عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ أَبَا عَمْرِو بْنَ حَفْصٍ رَضِيَ اللَّهُ عَنْهُ طَلَّقَهَا البَتَّةَ وَهُوَ غَائِبٌ - وَفِي رِوَايَةٍ: طَلَّقَهَا ثَلَاثاً -، فَأَرْسَلَ إِلَيْهَا وَكِيلُهُ بِشَعِيرٍ فَسَخِطَتْهُ، فَقَالَ: وَاللَّهِ! مَالَكِ عَلَيْنَا مِنْ شَيْءٍ،"]]},{"id":"um64_5","label":"الحديث ٣١٢ · المقطع ٢ من ٤","segs":[["matn","فَجَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ، فَقَالَ: لَيْسَ لَكِ عَلَيْهِ نَفَقَةٌ - وَفِي لَفْظٍ: وَلَا سُكْنَى -؛ فَأَمَرَهَا أَنْ تَعْتَدَّ فِي بَيْتِ أُمِّ شَرِيكٍ رَضِيَ اللَّهُ عَنْهَا، ثُمَّ قَالَ:"]]},{"id":"um64_6","label":"الحديث ٣١٢ · المقطع ٣ من ٤","segs":[["matn","تِلْكَ امْرَأَةٌ يَغْشَاهَا أَصْحَابِي، اعْتَدِّي عِنْدَ ابْنِ أُمِّ مَكْتُومٍ؛ فَإِنَّهُ رَجُلٌ أَعْمَى، تَضَعِينَ ثِيَابَكِ، فَإِذَا حَلَلْتِ فَآذِنِينِي، قَالَتْ: فَلَمَّا حَلَلْتُ ذَكَرْتُ لَهُ أَنَّ مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ وَأَبَا جَهْمٍ رَضِيَ اللَّهُ عَنْهُمْ خَطَبَانِي،"]]},{"id":"um64_7","label":"الحديث ٣١٢ · المقطع ٤ من ٤","segs":[["matn","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّا أَبُو الجَهْمِ فَلَا يَضَعُ عَصَاهُ عَنْ عَاتِقِهِ، وَأَمَّا مُعَاوِيَةُ فَصُعْلُوكٌ لَا مَالَ لَهُ، انْكِحِي أُسَامَةَ بْنَ زَيْدٍ؛ فَكَرِهْتُهُ، ثُمَّ قَالَ: انْكِحِي أُسَامَةَ بْنَ زَيْدٍ؛ فَنَكَحْتُهُ، فَجَعَلَ اللَّهُ فِيهِ خَيْراً وَاغْتَبَطْتُ»."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um65","title":"بَابُ العِدَّةِ","units":[{"id":"um65_1","label":"الحديث ٣١٣ · المقطع ١ من ٤","segs":[["rawi","عَنْ سُبَيْعَةَ الأَسْلَمِيَّةِ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّهَا كَانَتْ تَحْتَ سَعْدِ بْنِ خَوْلَةَ رَضِيَ اللَّهُ عَنْهُ، وَهُوَ فِي بَنِي عَامِرِ بْنِ لُؤَيٍّ، وَكَانَ مِمَّنْ شَهِدَ بَدْراً، فَتُوُفِّيَ عَنْهَا فِي حَجَّةِ الوَدَاعِ وَهِيَ حَامِلٌ؛ فَلَمْ تَنْشَبْ أَنْ وَضَعَتْ حَمْلَهَا بَعْدَ وَفَاتِهِ،"]]},{"id":"um65_2","label":"الحديث ٣١٣ · المقطع ٢ من ٤","segs":[["matn","فَلَمَّا تَعَلَّتْ مِنْ نِفَاسِهَا تَجَمَّلَتْ لِلْخُطَّابِ، فَدَخَلَ عَلَيْهَا أَبُو السَّنَابِلِ ابْنُ بَعْكَكٍ رَضِيَ اللَّهُ عَنْهُ - رَجُلٌ مِنْ بَنِي عَبْدِ الدَّارِ -، فَقَالَ لَهَا: مَا لِي أَرَاكِ مُتَجَمِّلَةً؟ لَعَلَّكِ تُرَجِّينَ النِّكَاحَ!"]]},{"id":"um65_3","label":"الحديث ٣١٣ · المقطع ٣ من ٤","segs":[["matn","وَاللَّهِ مَا أَنْتِ بِنَاكِحٍ حَتَّى تَمُرَّ عَلَيْكِ أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ، قَالَتْ سُبَيْعَةُ: فَلَمَّا قَالَ لِي ذَلِكَ جَمَعْتُ عَلَيَّ ثِيَابِي حِينَ أَمْسَيْتُ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلْتُهُ عَنْ ذَلِكَ؛"]]},{"id":"um65_4","label":"الحديث ٣١٣ · المقطع ٤ من ٤","segs":[["matn","فَأَفْتَانِي بِأَنِّي قَدْ حَلَلْتُ حِينَ وَضَعْتُ حَمْلِي، وَأَمَرَنِي بِالتَّزْوِيجِ إِنْ بَدَا لِي. قَالَ ابْنُ شِهَابٍ: وَلَا أَرَى بَأْساً أَنْ تَتَزَوَّجَ حِينَ وضَعَتْ وَإِنْ كَانَتْ فِي دَمِهَا؛ غَيْرَ أَنَّهُ لَا يَقْرَبُهَا زَوْجُهَا حَتَّى تَطْهُرَ»."]]},{"id":"um65_5","label":"الحديث ٣١٤","segs":[["rawi","عَنْ زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ:"],["matn","«تُوُفِّيَ حَمِيمٌ لِأُمِّ حَبِيبَةَ رَضِيَ اللَّهُ عَنْهَا؛ فَدَعَتْ بِصُفْرَةٍ فَمَسَحَتْهُ بِذِرَاعَيْهَا، وَقَالَتْ: إِنَّمَا أَصْنَعُ هَذَا؛ لِأَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَاليَوْمِ الآخِرِ أَنْ تُحِدَّ فَوْقَ ثَلَاثٍ؛ إِلَّا عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْراً»."]]},{"id":"um65_6","label":"الحديث ٣١٥","segs":[["rawi","عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَا تُحِدُّ امْرَأَةٌ عَلَى مَيِّتٍ فَوْقَ ثَلَاثٍ؛ إِلَّا عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْراً، وَلَا تَلْبَسُ ثَوْباً مَصْبُوغاً إِلَّا ثَوْبَ عَصْبٍ، وَلَا تَكْتَحِلُ، وَلَا تَمَسُّ طِيباً؛ إِلَّا إِذَا طَهَرَتْ؛ نُبْذَةً مِنْ قُسْطٍ أَوْ أَظْفَارٍ»."]]},{"id":"um65_7","label":"الحديث ٣١٦ · المقطع ١ من ٤","segs":[["rawi","عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ! إِنَّ ابْنَتِي تُوُفِّيَ عَنْهَا زَوْجُهَا وَقَدِ اشْتَكَتْ عَيْنُهَا، أَفَنَكْحُلُهَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا - مَرَّتَيْنِ أَوْ ثَلَاثاً -،"]]},{"id":"um65_8","label":"الحديث ٣١٦ · المقطع ٢ من ٤","segs":[["matn","كُلَّ ذَلِكَ يَقُولُ: لَا، ثُمَّ قَالَ: إِنَّمَا هِيَ أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ، وَقَدْ كَانَتْ إِحْدَاكُنَّ فِي الجَاهِلِيَّةِ تَرْمِي بِالبَعَرَةِ عَلَى رَأْسِ الحَوْلِ، فَقَالَتْ زَيْنَبُ رَضِيَ اللَّهُ عَنْهَا: كَانَتِ المَرْأَةُ إِذَا تُوُفِّيَ عَنْهَا زَوْجُهَا دَخَلَتْ حِفْشاً،"]]},{"id":"um65_9","label":"الحديث ٣١٦ · المقطع ٣ من ٤","segs":[["matn","وَلَبِسَتْ شَرَّ ثِيَابِهَا، وَلَمْ تَمَسَّ طِيباً وَلَا شَيْئاً حَتَّى تَمُرَّ بِهَا سَنَةٌ، ثُمَّ تُؤْتَى بِدَابَّةٍ - حِمَارٍ، أَوْ شَاةٍ، أَوْ طَيْرٍ -؛ فَتَفْتَضُّ بِهِ؛ فَقَلَّمَا تَفْتَضُّ بِشَيْءٍ إِلَّا مَاتَ، ثُمَّ تَخْرُجُ فَتُعْطَى بَعَرَةً فَتَرْمِي بِهَا،"]]},{"id":"um65_10","label":"الحديث ٣١٦ · المقطع ٤ من ٤","segs":[["matn","ثُمَّ تُرَاجِعُ بَعْدُ مَا شَاءَتْ مِنْ طِيبٍ أَوْ غَيْرِهِ»."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um66","title":"كِتَابُ اللِّعَانِ","units":[{"id":"um66_1","label":"الحديث ٣١٧ · المقطع ١ من ٦","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ فُلَانَ بْنَ فُلَانٍ قَالَ: يَا رَسُولَ اللَّهِ! أَرَأَيْتَ لَوْ وَجَدَ أَحَدُنَا امْرَأَتَهُ عَلَى فَاحِشَةٍ كَيْفَ يَصْنَعُ؟ إِنْ تَكَلَّمَ تَكَلَّمَ بِأَمْرٍ عَظِيمٍ، وَإِنْ سَكَتَ سَكَتَ عَلَى مِثْلِ ذَلِكَ، قَالَ: فَسَكَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،"]]},{"id":"um66_2","label":"الحديث ٣١٧ · المقطع ٢ من ٦","segs":[["matn","فَلَمْ يُجِبْهُ، فَلَمَّا كَانَ بَعْدَ ذَلِكَ أَتَاهُ فَقَالَ: إِنَّ الَّذِي سَأَلْتُكَ عَنْهُ قَدِ ابْتُلِيتُ بِهِ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ هَؤُلَاءِ الآيَاتِ فِي سُورَةِ النُّورِ: ﴿وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ … ﴾، فَتَلَاهُنَّ عَلَيْهِ، وَوَعَظَهُ وَذَكَّرَهُ،"]]},{"id":"um66_3","label":"الحديث ٣١٧ · المقطع ٣ من ٦","segs":[["matn","وَأَخْبَرَهُ أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الآخِرَةِ، فَقَالَ: لَا، وَالَّذِي بَعَثَكَ بِالحَقِّ! مَا كَذَبْتُ عَلَيْهَا، ثُمَّ دَعَاهَا، فَوَعَظَهَا، وَأَخْبَرَهَا أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الآخِرَةِ، فَقَالَتْ: لَا، وَالَّذِي بَعَثَكَ بِالحَقِّ إِنَّهُ لَكَاذِبٌ."]]},{"id":"um66_4","label":"الحديث ٣١٧ · المقطع ٤ من ٦","segs":[["matn","فَبَدَأَ بِالرَّجُلِ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الصَّادِقِينَ، وَالخَامِسَةُ أَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الكَاذِبِينَ. ثُمَّ ثَنَّى بِالمَرْأَةِ؛ فَشَهِدَتْ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الكَاذِبِينَ،"]]},{"id":"um66_5","label":"الحديث ٣١٧ · المقطع ٥ من ٦","segs":[["matn","وَالخَامِسَةُ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ. ثُمَّ فَرَّقَ بَيْنَهُمَا، ثُمَّ قَالَ: اللَّهُ يَعْلَمُ أَنَّ أَحَدَكُمَا كَاذِبٌ؛ فَهَلْ مِنْكُمَا تَائِبٌ؟ - ثَلَاثاً -». وَفِي لَفْظٍ: «لَا سَبِيلَ لَكَ عَلَيْهَا، قَالَ:"]]},{"id":"um66_6","label":"الحديث ٣١٧ · المقطع ٦ من ٦","segs":[["matn","يَا رَسُولَ اللَّهِ مَالِي؟! قَالَ: لَا مَالَ لَكَ؛ إِنْ كُنْتَ صَدَقْتَ عَلَيْهَا فَهُوَ بِمَا اسْتَحْلَلْتَ مِنْ فَرْجِهَا؛ وَإِنْ كُنْتَ كَذَبْتَ عَلَيْهَا فَهُوَ أَبْعَدُ لَكَ مِنْهَا»."]]},{"id":"um66_7","label":"الحديث ٣١٨","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَجُلاً رَمَى امْرَأَتَهُ وَانْتَفَى مِنْ وَلَدِهَا - فِي زَمَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -؛ فَأَمَرَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَلَاعَنَا - كَمَا قَالَ اللَّهُ عَزَّ وَجَلَّ -، ثُمَّ قَضَى بِالوَلَدِ لِلْمَرْأَةِ، وَفَرَّقَ بَيْنَ المُتَلَاعِنَيْنِ»."]]},{"id":"um66_8","label":"الحديث ٣١٩ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«جَاءَ رَجُلٌ مِنْ بَنِي فَزَارَةَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ امْرَأَتِي وَلَدَتْ غُلَاماً أَسْوَدَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ لَكَ إِبِلٌ؟ قَالَ: نَعَمْ، قَالَ: فَمَا أَلْوَانُهَا؟ قَالَ: حُمْرٌ، قَالَ:"]]},{"id":"um66_9","label":"الحديث ٣١٩ · المقطع ٢ من ٢","segs":[["matn","هَلْ فِيهَا مِنْ أَوْرَقَ؟ قَالَ: إِنَّ فِيهَا لَوُرْقاً، قَالَ: فَأَنَّى أَتَاهَا ذَلِكَ؟ قَالَ: عَسَى أَنْ يَكُونَ نَزَعَهُ عِرْقٌ، قَالَ: وَهَذَا عَسَى أَنْ يَكُونَ نَزَعَهُ عِرْقٌ»."]]},{"id":"um66_10","label":"الحديث ٣٢٠ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتِ:"],["matn","«اخْتَصَمَ سَعْدُ بْنُ أَبِي وَقَّاصٍ وَعَبْدُ بْنُ زَمْعَةَ فِي غُلَامٍ، فَقَالَ سَعْدٌ: يَا رَسُولَ اللَّهِ! هَذَا ابْنُ أَخِي عُتْبَةَ بْنِ أَبِي وَقَّاصٍ، عَهِدَ إِلَيَّ أَنَّهُ ابْنُهُ، انْظُرْ إِلَى شَبَهِهِ، وَقَالَ عَبْدُ بْنُ زَمْعَةَ:"]]},{"id":"um66_11","label":"الحديث ٣٢٠ · المقطع ٢ من ٣","segs":[["matn","هَذَا أَخِي يَا رَسُولَ اللَّهِ! وُلِدَ عَلَى فِرَاشِ أَبِي مِنْ وَلِيدَتِهِ، فَنَظَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى شَبَهِهِ، فَرَأَى شَبَهاً بَيِّناً بِعُتْبَةَ، فَقَالَ: هُوَ لَكَ يَا عَبْدُ بْنَ زَمْعَةَ، الوَلَدُ لِلْفِرَاشِ، وَلِلْعَاهِرِ الحَجَرُ،"]]},{"id":"um66_12","label":"الحديث ٣٢٠ · المقطع ٣ من ٣","segs":[["matn","وَاحْتَجِبِي مِنْهُ يَا سَوْدَةُ، فَلَمْ تَرَهُ سَوْدَةُ قَطُّ»."]]},{"id":"um66_13","label":"الحديث ٣٢١","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ:"],["matn","«إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيَّ مَسْرُوراً تَبْرُقُ أَسَارِيرُ وَجْهِهِ، فَقَالَ: أَلَمْ تَرَيْ أَنَّ مُجَزِّزاً نَظَرَ آنِفاً إِلَى زَيْدِ بْنِ حَارِثَةَ وَأُسَامَةَ بْنِ زَيْدٍ، فَقَالَ: إِنَّ بَعْضَ هَذِهِ الأَقْدَامِ لَمِنْ بَعْضٍ؟». وَفِي لَفْظٍ: «كَانَ مُجَزِّزٌ قَائِفاً»."]]},{"id":"um66_14","label":"الحديث ٣٢٢","segs":[["rawi","عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«ذُكِرَ العَزْلُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: وَلِمَ يَفْعَلُ ذَلِكَ أَحَدُكُمْ؟ - وَلَمْ يَقُلْ: فَلَا يَفْعَلْ ذَلِكَ أَحَدُكُمْ -؛ فَإِنَّهُ لَيْسَتْ نَفْسٌ مَخْلُوقَةٌ إِلَّا اللَّهُ خَالِقُهَا»."]]},{"id":"um66_15","label":"الحديث ٣٢٣","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«كُنَّا نَعْزِلُ وَالقُرْآنُ يَنْزِلُ». «لَوْ كَانَ شَيْءٌ يُنْهَى عَنْهُ لَنَهَانَا عَنْهُ القُرْآنُ»."]]},{"id":"um66_16","label":"الحديث ٣٢٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ:"],["matn","أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «لَيْسَ مِنْ رَجُلٍ ادَّعَى لِغَيْرِ أَبِيهِ وَهُوَ يَعْلَمُهُ؛ إِلَّا كَفَرَ، وَمَنِ ادَّعَى مَا لَيْسَ لَهُ فَلَيْسَ مِنَّا، وَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ، وَمَنْ دَعَا رَجُلاً بِالكُفْرِ،"]]},{"id":"um66_17","label":"الحديث ٣٢٤ · المقطع ٢ من ٢","segs":[["matn","أَوْ قَالَ: عَدُوَّ اللَّهِ؛ وَلَيْسَ كَذَلِكَ؛ إِلَّا حَارَ عَلَيْهِ». كَذَا عِنْدَ مُسْلِمٍ؛ وَلِلْبُخَارِيِّ: نَحْوُهُ."]]}],"group":"كِتَابُ اللِّعَانِ"},{"id":"um67","title":"كِتَابُ الرَّضَاعِ","units":[{"id":"um67_1","label":"الحديث ٣٢٥","segs":[["rawi","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فِي بِنْتِ حَمْزَةَ -:"],["matn","«لَا تَحِلُّ لِي، يَحْرُمُ مِنَ الرَّضَاعَةِ مَا يَحْرُمُ مِنَ النَّسَبِ؛ وَهِيَ ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ»."]]},{"id":"um67_2","label":"الحديث ٣٢٦","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ الرَّضَاعَةَ تُحَرِّمُ مَا يَحْرُمُ مِنَ الوِلَادَةِ»."]]},{"id":"um67_3","label":"الحديث ٣٢٧ · المقطع ١ من ٤","segs":[["rawi","وَعَنْهَا رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«إِنَّ أَفْلَحَ - أَخَا أَبِي القُعَيْسِ - اسْتَأْذَنَ عَلَيَّ بَعْدَمَا أُنْزِلَ الحِجَابُ؛ فَقُلْتُ: وَاللَّهِ لَا آذَنُ لَهُ حَتَّى أَسْتَأْذِنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ فَإِنَّ أَخَا أَبِي القُعَيْسِ لَيْسَ هُوَ أَرْضَعَنِي؛"]]},{"id":"um67_4","label":"الحديث ٣٢٧ · المقطع ٢ من ٤","segs":[["matn","وَلَكِنْ أَرْضَعَتْنِي امْرَأَةُ أَبِي القُعَيْسِ، فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ! إِنَّ الرَّجُلَ لَيْسَ هُوَ أَرْضَعَنِي، وَلَكِنْ أَرْضَعَتْنِي امْرَأَتُهُ، قَالَ: ائْذَنِي لَهُ؛ فَإِنَّهُ عَمُّكِ تَرِبَتْ يَمِينُكِ، قَالَ عُرْوَةُ:"]]},{"id":"um67_5","label":"الحديث ٣٢٧ · المقطع ٣ من ٤","segs":[["matn","فَبِذَلِكَ كَانَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا تَقُولُ: حَرِّمُوا مِنَ الرَّضَاعَةِ مَا يَحْرُمُ مِنَ النَّسَبِ». وَفِي لَفْظٍ: «اسْتَأْذَنَ عَلَيَّ أَفْلَحُ فَلَمْ آذَنْ لَهُ، فَقَالَ: أَتَحْتَجِبِينَ مِنِّي وَأَنَا عَمُّكِ؟ فَقُلْتُ: كَيْفَ ذَلِكَ؟ قَالَ:"]]},{"id":"um67_6","label":"الحديث ٣٢٧ · المقطع ٤ من ٤","segs":[["matn","أَرْضَعَتْكِ امْرَأَةُ أَخِي بِلَبَنِ أَخِي، قَالَتْ: فَسَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: صَدَقَ أَفْلَحُ، ائْذَنِي لَهُ»."]]},{"id":"um67_7","label":"الحديث ٣٢٨","segs":[["rawi","وَعَنْهَا رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«دَخَلَ عَلَيَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدِي رَجُلٌ، فَقَالَ: يَا عَائِشَةُ! مَنْ هَذَا؟ قُلْتُ: أَخِي مِنَ الرَّضَاعَةِ، فَقَالَ: يَا عَائِشَةُ! انْظُرْنَ مَنْ إِخْوَانُكُنَّ؟ فَإِنَّمَا الرَّضَاعَةُ مِنَ المَجَاعَةِ»."]]},{"id":"um67_8","label":"الحديث ٣٢٩","segs":[["rawi","عَنْ عُقْبَةَ بْنِ الحَارِثِ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّهُ تَزَوَّجَ أُمَّ يَحْيَى بِنْتَ أَبِي إِهَابٍ، فَجَاءَتْ أَمَةٌ سَوْدَاءُ فَقَالَتْ: قَدْ أَرْضَعْتُكُمَا، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَعْرَضَ عَنِّي، قَالَ: فَتَنَحَّيْتُ فَذَكَرْتُ ذَلِكَ لَهُ، قَالَ: وَكَيْفَ وَقَدْ زَعَمَتْ أَنْ قَدْ أَرْضَعَتْكُمَا؟»."]]},{"id":"um67_9","label":"الحديث ٣٣٠ · المقطع ١ من ٣","segs":[["rawi","عَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يَعْنِي: مِنْ مَكَّةَ - فَتَبِعَتْهُمُ ابْنَةُ حَمْزَةَ تُنَادِي: يَا عَمِّ! فَتَنَاوَلَهَا عَلِيٌّ فَأَخَذَ بِيَدِهَا، وَقَالَ لِفَاطِمَةَ: دُونَكِ ابْنَةَ عَمِّكِ فَاحْتَمِلِيهَا، فَاخْتَصَمَ فِيهَا عَلِيٌّ وَزَيْدٌ وَجَعْفَرٌ: فَقَالَ عَلِيٌّ:"]]},{"id":"um67_10","label":"الحديث ٣٣٠ · المقطع ٢ من ٣","segs":[["matn","أَنَا أَحَقُّ بِهَا، وَهِيَ ابْنَةُ عَمِّي، وَقَالَ جَعْفَرٌ: ابْنَةُ عَمِّي، وَخَالَتُهَا تَحْتِي، وَقَالَ زَيْدٌ: ابْنَةُ أَخِي، فَقَضَى بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِخَالَتِهَا، وَقَالَ: الخَالَةُ بِمَنْزِلَةِ الأُمِّ، وَقَالَ لِعَلِيٍّ: أَنْتَ مِنِّي، وَأَنَا مِنْكَ،"]]},{"id":"um67_11","label":"الحديث ٣٣٠ · المقطع ٣ من ٣","segs":[["matn","وَقَالَ لِجَعْفَرٍ: أَشْبَهْتَ خَلْقِي وَخُلُقِي، وَقَالَ لِزَيْدٍ: أَنْتَ أَخُونَا وَمَوْلَانَا»."]]}],"group":"كِتَابُ الرَّضَاعِ"},{"id":"um68","title":"كِتَابُ القِصَاصِ","units":[{"id":"um68_1","label":"الحديث ٣٣١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ؛ إِلَّا بِإِحْدَى ثَلَاثٍ: الثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ، وَالتَّارِكُ لِدِينِهِ المُفَارِقُ لِلْجَمَاعَةِ»."]]},{"id":"um68_2","label":"الحديث ٣٣٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«أَوَّلُ مَا يُقْضَى بَيْنَ النَّاسِ يَوْمَ القِيَامَةِ فِي الدِّمَاءِ»."]]},{"id":"um68_3","label":"الحديث ٣٣٣ · المقطع ١ من ٥","segs":[["rawi","عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«انْطَلَقَ عَبْدُ اللَّهِ بْنُ سَهْلٍ وَمُحَيِّصَةُ بْنُ مَسْعُودٍ إِلَى خَيْبَرَ - وَهِيَ يَوْمَئِذٍ صُلْحٌ - فَتَفَرَّقَا، فَأَتَى مُحَيِّصَةُ إِلَى عَبْدِ اللَّهِ بْنِ سَهْلٍ - وَهُوَ يَتَشَحَّطُ فِي دَمِهِ قَتِيلاً - فَدَفَنَهُ، ثُمَّ قَدِمَ المَدِينَةَ،"]]},{"id":"um68_4","label":"الحديث ٣٣٣ · المقطع ٢ من ٥","segs":[["matn","فَانْطَلَقَ عَبْدُ الرَّحْمَنِ بْنُ سَهْلٍ وَمُحَيِّصَةُ وَحُوَيِّصَةُ ابْنَا مَسْعُودٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَهَبَ عَبْدُ الرَّحْمَنِ يَتَكَلَّمُ، فَقَالَ: كَبِّرْ، كَبِّرْ - وَهُوَ أَحْدَثُ القَوْمِ - فَسَكَتَ، فَتَكَلَّمَا، فَقَالَ:"]]},{"id":"um68_5","label":"الحديث ٣٣٣ · المقطع ٣ من ٥","segs":[["matn","أَتَحْلِفُونَ وَتَسْتَحِقُّونَ قَاتِلَكُمْ - أَوْ صَاحِبَكُمْ؟ - قَالُوا: وَكَيْفَ نَحْلِفُ، وَلَمْ نَشْهَدْ، وَلَمْ نَرَ؟ قَالَ: فَتُبْرِئُكُمْ يَهُودُ بِخَمْسِينَ يَمِيناً؟ فَقَالُوا: كَيْفَ نَأْخُذُ بِأَيْمَانِ قَوْمٍ كُفَّارٍ؟ فَعَقَلَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ عِنْدِهِ»."]]},{"id":"um68_6","label":"الحديث ٣٣٣ · المقطع ٤ من ٥","segs":[["matn","وَفِي حَدِيثِ حَمَّادِ بْنِ زَيْدٍ: «فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُقْسِمُ خَمْسُونَ مِنْكُمْ عَلَى رَجُلٍ مِنْهُمْ، فَيُدْفَعُ بِرُمَّتِهِ، قَالُوا: أَمْرٌ لَمْ نَشْهَدْ كَيْفَ نَحْلِفُ؟ قَالَ: فَتُبْرِئُكُمْ يَهُودُ بِأَيْمَانٍ خَمْسِينَ مِنْهُمْ؟ قَالُوا:"]]},{"id":"um68_7","label":"الحديث ٣٣٣ · المقطع ٥ من ٥","segs":[["matn","يَا رَسُولَ اللَّهِ قَوْمٌ كُفَّارٌ!». وَفِي حَدِيثِ سَعِيدِ بْنِ عُبَيْدٍ: «فَكَرِهَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُبْطِلَ دَمَهُ؛ فَوَدَاهُ بِمِئَةٍ مِنْ إِبِلِ الصَّدَقَةِ»."]]},{"id":"um68_8","label":"الحديث ٣٣٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ جَارِيَةً وُجِدَ رَأْسُهَا مَرْضُوخاً بَيْنَ حَجَرَيْنِ، فَقِيلَ: مَنْ فَعَلَ هَذَا بِكِ؟ فُلَانٌ؟ فُلَانٌ؟ حَتَّى ذُكِرَ يَهُودِيٌّ؛ فَأَوْمَأَتْ بِرَأْسِهَا، فَأُخِذَ اليَهُودِيُّ فَاعْتَرَفَ؛ فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُرَضَّ رَأْسُهُ بَيْنَ حَجَرَيْنِ». وَلِمُسْلِمٍ،"]]},{"id":"um68_9","label":"الحديث ٣٣٤ · المقطع ٢ من ٢","segs":[["matn","وَالنَّسَائِيِّ عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: «أَنَّ يَهُودِيّاً قَتَلَ جَارِيَةً عَلَى أَوْضَاحٍ؛ فَأَقَادَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهَا»."]]},{"id":"um68_10","label":"الحديث ٣٣٥ · المقطع ١ من ٥","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«لَمَّا فَتَحَ اللَّهُ عَلَى رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ قَتَلَتْ هُذَيْلٌ رَجُلاً مِنْ بَنِي لَيْثٍ بِقَتِيلٍ كَانَ لَهُمْ فِي الجَاهِلِيَّةِ، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ:"]]},{"id":"um68_11","label":"الحديث ٣٣٥ · المقطع ٢ من ٥","segs":[["matn","إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ حَبَسَ عَنْ مَكَّةَ الفِيلَ، وَسَلَّطَ عَلَيْهَا رَسُولَهُ وَالمُؤْمِنِينَ، وَإِنَّهَا لَمْ تَحِلَّ لِأَحَدٍ كَانَ قَبْلِي، وَلَا تَحِلُّ لِأَحَدٍ بَعْدِي، وَإِنَّمَا أُحِلَّتْ لِي سَاعَةً مِنْ نَهَارٍ، وَإِنَّهَا سَاعَتِي هَذِهِ حَرَامٌ،"]]},{"id":"um68_12","label":"الحديث ٣٣٥ · المقطع ٣ من ٥","segs":[["matn","لَا يُعْضَدُ شَجَرُهَا، وَلَا يُخْتَلَى خَلَاهَا، وَلَا يُعْضَدُ شَوْكُهَا، وَلَا تُلْتَقَطُ سَاقِطَتُهَا إِلَّا لِمُنْشِدٍ، وَمَنْ قُتِلَ لَهُ قَتِيلٌ؛ فَهُوَ بِخَيْرِ النَّظَرَيْنِ: إِمَّا أَنْ يَقْتُلَ، وَإِمَّا أَنْ يُفْدَى، فَقَامَ رَجُلٌ مِنْ أَهْلِ اليَمَنِ - يُقَالُ لَهُ:"]]},{"id":"um68_13","label":"الحديث ٣٣٥ · المقطع ٤ من ٥","segs":[["matn","أَبُو شَاهٍ - فَقَالَ: يَا رَسُولَ اللَّهِ! اكْتُبُوا لِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اكْتُبُوا لِأَبِي شَاهٍ، ثُمَّ قَامَ العَبَّاسُ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: يَا رَسُولَ اللَّهِ! إِلَّا الإِذْخِرَ؛"]]},{"id":"um68_14","label":"الحديث ٣٣٥ · المقطع ٥ من ٥","segs":[["matn","فَإِنَّا نَجْعَلُهُ فِي بُيُوتِنَا وَقُبُورِنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِلَّا الإِذْخِرَ»."]]},{"id":"um68_15","label":"الحديث ٣٣٦","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّهُ اسْتَشَارَ النَّاسَ فِي إِمْلَاصِ المَرْأَةِ، فَقَالَ المُغِيرَةُ بْنُ شُعْبَةَ رَضِيَ اللَّهُ عَنْهُ: شَهِدْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى فِيهِ بِغُرَّةٍ - عَبْدٍ أَوْ أَمَةٍ -، فَقَالَ: لَتَأْتِيَنَّ بِمَنْ يَشْهَدُ مَعَكَ، فَشَهِدَ مَعَهُ مُحَمَّدُ بْنُ مَسْلَمَةَ»."]]},{"id":"um68_16","label":"الحديث ٣٣٧ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«اقْتَتَلَتِ امْرَأَتَانِ مِنْ هُذَيْلٍ؛ فَرَمَتْ إِحْدَاهُمَا الأُخْرَى بِحَجَرٍ فَقَتَلَتْهَا وَمَا فِي بَطْنِهَا، فَاخْتَصَمُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛"]]},{"id":"um68_17","label":"الحديث ٣٣٧ · المقطع ٢ من ٣","segs":[["matn","فَقَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ دِيَةَ جَنِينِهَا غُرَّةٌ - عَبْدٌ أَوْ وَلِيدَةٌ -، وَقَضَى بِدِيَةِ المَرْأَةِ عَلَى عَاقِلَتِهَا، وَوَرَّثَهَا وَلَدَهَا وَمَنْ مَعَهُمْ، فَقَامَ حَمَلُ بْنُ النَّابِغَةِ الهُذَلِيُّ فَقَالَ: يَا رَسُولَ اللَّهِ!"]]},{"id":"um68_18","label":"الحديث ٣٣٧ · المقطع ٣ من ٣","segs":[["matn","كَيْفَ أَغْرَمُ مَنْ لَا شَرِبَ وَلَا أَكَلْ، وَلَا نَطَقَ وَلَا اسْتَهَلْ؟ فَمِثْلُ ذَلِكَ يُطَلْ! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا هُوَ مِنْ إِخْوَانِ الكُهَّانِ؛ مِنْ أَجْلِ سَجْعِهِ الَّذِي سَجَعَ»."]]},{"id":"um68_19","label":"الحديث ٣٣٨","segs":[["rawi","عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَجُلاً عَضَّ يَدَ رَجُلٍ فَنَزَعَ يَدَهُ مِنْ فَمِهِ، فَوَقَعَتْ ثَنَايَاهُ، فَاخْتَصَمُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَعَضُّ أَحَدُكُمْ أَخَاهُ كَمَا يَعَضُّ الفَحْلُ؟! لَا دِيَةَ لَكَ»."]]},{"id":"um68_20","label":"الحديث ٣٣٩ · المقطع ١ من ٢","segs":[["rawi","عَنِ الحَسَنِ بْنِ أَبِي الحَسَنِ البَصْرِيِّ قَالَ:"],["matn","«حَدَّثَنَا جُنْدُبٌ رَضِيَ اللَّهُ عَنْهُ فِي هَذَا المَسْجِدِ، وَمَا نَسِينَا مِنْهُ حَدِيثاً، وَمَا نَخْشَى أَنْ يَكُونَ جُنْدُبٌ كَذَبَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um68_21","label":"الحديث ٣٣٩ · المقطع ٢ من ٢","segs":[["matn","كَانَ فِيمَنْ كَانَ قَبْلَكُمْ رَجُلٌ بِهِ جُرْحٌ فَجَزِعَ، فَأَخَذَ سِكِّيناً فَحَزَّ بِهَا يَدَهُ؛ فَمَا رَقَأَ الدَّمُ حَتَّى مَاتَ، قَالَ اللَّهُ عَزَّ وَجَلَّ: عَبْدِي بَادَرَنِي بِنَفْسِهِ؛ حَرَّمْتُ عَلَيْهِ الجَنَّةَ»."]]},{"id":"um68_22","label":"الحديث ٣٤٠ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«قَدِمَ نَاسٌ مِنْ عُكْلٍ - أَوْ عُرَيْنَةَ - فَاجْتَوَوُا المَدِينَةَ، فَأَمَرَ لَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلِقَاحٍ، وَأَمَرَهُمْ أَنْ يَشْرَبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا، فَانْطَلَقُوا،"]]},{"id":"um68_23","label":"الحديث ٣٤٠ · المقطع ٢ من ٣","segs":[["matn","فَلَمَّا صَحُّوا قَتَلُوا رَاعِيَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاسْتَاقُوا النَّعَمَ، فَجَاءَ الخَبَرُ فِي أَوَّلِ النَّهَارِ، فَبَعَثَ فِي آثَارِهِمْ، فَلَمَّا ارْتَفَعَ النَّهَارُ جِيءَ بِهِمْ، فَأَمَرَ بِقَطْعِ أَيْدِيهِمْ وَأَرْجُلِهِمْ، وَسُمِرَتْ أَعْيُنُهُمْ،"]]},{"id":"um68_24","label":"الحديث ٣٤٠ · المقطع ٣ من ٣","segs":[["matn","وَتُرِكُوا فِي الحَرَّةِ يَسْتَسْقُونَ فَلَا يُسْقَوْنَ. قَالَ أَبُو قِلَابَةَ: فَهَؤُلَاءِ سَرَقُوا وَقَتَلُوا وَكَفَرُوا بَعْدَ إِيْمَانِهِمْ، وَحَارَبُوا اللَّهَ وَرَسُولَهُ». أَخْرَجَهُ الجَمَاعَةُ."]]}],"group":"كِتَابُ القِصَاصِ"},{"id":"um69","title":"كِتَابُ الحُدُودِ","units":[{"id":"um69_1","label":"الحديث ٣٤١ · المقطع ١ من ٤","segs":[["rawi","عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ، عَنْ أَبِي هُرَيْرَةَ وَزَيْدِ بْنِ خَالِدٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُمَا قَالَا:"],["matn","«إِنَّ رَجُلاً مِنَ الأَعْرَابِ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! أَنْشُدُكَ اللَّهَ إِلَّا قَضَيْتَ بَيْنَنَا بِكِتَابِ اللَّهِ، فَقَالَ الخَصْمُ الآخَرُ - وَهُوَ أَفْقَهُ مِنْهُ -: نَعَمْ، فَاقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ،"]]},{"id":"um69_2","label":"الحديث ٣٤١ · المقطع ٢ من ٤","segs":[["matn","وَائْذَنْ لِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قُلْ، قَالَ: إِنَّ ابْنِي كَانَ عَسِيفاً عَلَى هَذَا؛ فَزَنَى بِامْرَأَتِهِ، وَإِنِّي أُخْبِرْتُ أَنَّ عَلَى ابْنِي الرَّجْمَ، فَافْتَدَيْتُ مِنْهُ بِمِئَةِ شَاةٍ وَوَلِيدَةٍ،"]]},{"id":"um69_3","label":"الحديث ٣٤١ · المقطع ٣ من ٤","segs":[["matn","فَسَأَلْتُ أَهْلَ العِلْمِ فَأَخْبَرُونِي أَنَّمَا عَلَى ابْنِي جَلْدُ مِئَةٍ وَتَغْرِيبُ عَامٍ، وَأَنَّ عَلَى امْرَأَةِ هَذَا الرَّجْمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَالَّذِي نَفْسِي بِيَدِهِ! لَأَقْضِيَنَّ بَيْنَكُمَا بِكِتَابِ اللَّهِ: الوَلِيدَةُ وَالغَنَمُ رَدٌّ عَلَيْكَ،"]]},{"id":"um69_4","label":"الحديث ٣٤١ · المقطع ٤ من ٤","segs":[["matn","وَعَلَى ابْنِكَ جَلْدُ مِئَةٍ وَتَغْرِيبُ عَامٍ، وَاغْدُ يَا أُنَيْسُ - لِرَجُلٍ مِنْ أَسْلَمَ - إِلَى امْرَأَةِ هَذَا؛ فَإِنِ اعْتَرَفَتْ فَارْجُمْهَا، قَالَ: فَغَدَا عَلَيْهَا فَاعْتَرَفَتْ، فَأَمَرَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَتْ»."]]},{"id":"um69_5","label":"الحديث ٣٤٢","segs":[["rawi","وَعَنْهُ، عَنْهُمَا رَضِيَ اللَّهُ عَنْهُمَا قَالَا:"],["matn","«سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الأَمَةِ إِذَا زَنَتْ وَلَمْ تُحْصِنْ؛ قَالَ: إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ بِيعُوهَا وَلَوْ بِضَفِيرٍ! قَالَ ابْنُ شِهَابٍ: لَا أَدْرِي، أَبَعْدَ الثَّالِثَةِ أَوِ الرَّابِعَةِ، وَالضَّفِيرُ: الحَبْلُ»."]]},{"id":"um69_6","label":"الحديث ٣٤٣ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ:"],["matn","«أَتَى رَجُلٌ مِنَ المُسْلِمِينَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَهُوَ فِي المَسْجِدِ - فَنَادَاهُ فَقَالَ: يَا رَسُولَ اللَّهِ! إِنِّي زَنَيْتُ، فَأَعْرَضَ عَنْهُ، فَتَنَحَّى تِلْقَاءَ وَجْهِهِ فَقَالَ: يَا رَسُولَ اللَّهِ! إِنِّي زَنَيْتُ، فَأَعْرَضَ عَنْهُ،"]]},{"id":"um69_7","label":"الحديث ٣٤٣ · المقطع ٢ من ٣","segs":[["matn","حَتَّى ثَنَى ذَلِكَ عَلَيْهِ أَرْبَعَ مَرَّاتٍ، فَلَمَّا شَهِدَ عَلَى نَفْسِهِ أَرْبَعَ شَهَادَاتٍ؛ دَعَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَبِكَ جُنُونٌ؟ قَالَ: لَا، قَالَ: فَهَلْ أَحْصَنْتَ؟ قَالَ: نَعَمْ،"]]},{"id":"um69_8","label":"الحديث ٣٤٣ · المقطع ٣ من ٣","segs":[["matn","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اذْهَبُوا بِهِ فَارْجُمُوهُ. قَالَ ابْنُ شِهَابٍ: فَأَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: كُنْتُ فِيمَنْ رَجَمَهُ، فَرَجَمْنَاهُ بِالمُصَلَّى، فَلَمَّا أَذْلَقَتْهُ الحِجَارَةُ هَرَبَ، فَأَدْرَكْنَاهُ بِالحَرَّةِ، فَرَجَمْنَاهُ»."]]},{"id":"um69_9","label":"الحديث ٣٤٤ · المقطع ١ من ٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ قَالَ:"],["matn","«إِنَّ اليَهُودَ جَاؤُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرُوا لَهُ أَنَّ امْرَأَةً مِنْهُمْ وَرَجُلاً زَنَيَا؛ فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا تَجِدُونَ فِي التَّوْرَاةِ فِي شَأْنِ الرَّجْمِ؟ فَقَالُوا: نَفْضَحُهُمْ وَيُجْلَدُونَ،"]]},{"id":"um69_10","label":"الحديث ٣٤٤ · المقطع ٢ من ٣","segs":[["matn","قَالَ عَبْدُ اللَّهِ بْنُ سَلَامٍ: كَذَبْتُمْ، إِنَّ فِيهَا الرَّجْمَ، فَأَتَوْا بِالتَّوْرَاةِ فَنَشَرُوهَا، فَوَضَعَ أَحَدُهُمْ يَدَهُ عَلَى آيَةِ الرَّجْمِ فَقَرَأَ مَا قَبْلَهَا وَمَا بَعْدَهَا، فَقَالَ لَهُ عَبْدُ اللَّهِ بْنُ سَلَامٍ: ارْفَعْ يَدَكَ! فَرَفَعَ يَدَهُ،"]]},{"id":"um69_11","label":"الحديث ٣٤٤ · المقطع ٣ من ٣","segs":[["matn","فَإِذَا فِيهَا آيَةُ الرَّجْمِ، فَقَالَ: صَدَقَ يَا مُحَمَّدُ، فَأَمَرَ بِهِمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَا، قَالَ: فَرَأَيْتُ الرَّجُلَ يَجْنَأُ عَلَى المَرْأَةِ؛ يَقِيهَا الحِجَارَةَ»."]]},{"id":"um69_12","label":"الحديث ٣٤٥","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَوْ أَنَّ امْرَأً اطَّلَعَ عَلَيْكَ بِغَيْرِ إِذْنٍ، فَخَذَفْتَهُ بِحَصَاةٍ فَفَقَأْتَ عَيْنَهُ؛ مَا كَانَ عَلَيْكَ جُنَاحٌ»."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um70","title":"بَابُ حَدِّ السَّرِقَةِ","units":[{"id":"um70_1","label":"الحديث ٣٤٦","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطَعَ فِي مِجَنٍّ قِيمَتُهُ - وَفِي لَفْظٍ: ثَمَنُهُ - ثَلَاثَةُ دَرَاهِمَ»."]]},{"id":"um70_2","label":"الحديث ٣٤٧","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"],["matn","«تُقْطَعُ اليَدُ فِي رُبُعِ دِينَارٍ فَصَاعِداً»."]]},{"id":"um70_3","label":"الحديث ٣٤٨ · المقطع ١ من ٣","segs":[["rawi","وَعَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ قُرَيْشاً أَهَمَّهُمْ شَأْنُ المَخْزُومِيَّةِ الَّتِي سَرَقَتْ، فَقَالُوا: مَنْ يُكَلِّمُ فِيهَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالُوا: وَمَنْ يَجْتَرِئُ عَلَيْهِ إِلَّا أُسَامَةُ بْنُ زَيْدٍ - حِبُّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -؟"]]},{"id":"um70_4","label":"الحديث ٣٤٨ · المقطع ٢ من ٣","segs":[["matn","فَكَلَّمَهُ أُسَامَةُ، فَقَالَ: أَتَشْفَعُ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ؟ ثُمَّ قَامَ فَاخْتَطَبَ، فَقَالَ: إِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ: أَنَّهُمْ كَانُوا إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ تَرَكُوهُ، وَإِذَا سَرَقَ فِيهِمُ الضَّعِيفُ أَقَامُوا عَلَيْهِ الحَدَّ، وَايْمُ اللَّهِ!"]]},{"id":"um70_5","label":"الحديث ٣٤٨ · المقطع ٣ من ٣","segs":[["matn","لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا». وَفِي لَفْظٍ: «قَالَتْ: كَانَتِ امْرَأَةٌ تَسْتَعِيرُ المَتَاعَ وَتَجْحَدُهُ؛ فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَطْعِ يَدِهَا»."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um71","title":"بَابُ حَدِّ الخَمْرِ","units":[{"id":"um71_1","label":"الحديث ٣٤٩ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِرَجُلٍ قَدْ شَرِبَ الخَمْرَ، فَجَلَدَهُ بِجَرِيدٍ نَحْوَ أَرْبَعِينَ، قَالَ: وَفَعَلَهُ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ، فَلَمَّا كَانَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ اسْتَشَارَ النَّاسَ، فَقَالَ عَبْدُ الرَّحْمَنِ:"]]},{"id":"um71_2","label":"الحديث ٣٤٩ · المقطع ٢ من ٢","segs":[["matn","أَخَفَّ الحُدُودِ ثَمَانِينَ، فَأَمَرَ بِهِ عُمَرُ رَضِيَ اللَّهُ عَنْهُ»."]]},{"id":"um71_3","label":"الحديث ٣٥٠","segs":[["rawi","عَنْ أَبِي بُرْدَةَ هَانِئِ بْنِ نِيَارٍ البَلَوِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"],["matn","«لَا يُجْلَدُ فَوْقَ عَشَرَةِ أَسْوَاطٍ إِلَّا فِي حَدٍّ مِنْ حُدُودِ اللَّهِ»."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um72","title":"كِتَابُ الأَيْمَانِ وَالنُّذُورِ","units":[{"id":"um72_1","label":"الحديث ٣٥١ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «يَا عَبْدَ الرَّحْمَنِ بْنَ سَمُرَةَ! لَا تَسْأَلِ الإِمَارَةَ؛ فَإِنَّكَ إِنْ أُعْطِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا، وَإِنْ أُعْطِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا،"]]},{"id":"um72_2","label":"الحديث ٣٥١ · المقطع ٢ من ٢","segs":[["matn","وَإِذَا حَلَفْتَ عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْراً مِنْهَا؛ فَكَفِّرْ عَنْ يَمِينِكَ وَائْتِ الَّذِي هُوَ خَيْرٌ»."]]},{"id":"um72_3","label":"الحديث ٣٥٢","segs":[["rawi","عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنِّي وَاللَّهِ - إِنْ شَاءَ اللَّهُ - لَا أَحْلِفُ عَلَى يَمِينٍ، فَأَرَى غَيْرَهَا خَيْراً مِنْهَا؛ إِلَّا أَتَيْتُ الَّذِي هُوَ خَيْرٌ، وَتَحَلَّلْتُهَا»."]]},{"id":"um72_4","label":"الحديث ٣٥٣","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«إِنَّ اللَّهَ يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ». وَلِمُسْلِمٍ: «فَمَنْ كَانَ حَالِفاً؛ فَلْيَحْلِفْ بِاللَّهِ، أَوْ لِيَصْمُتْ». وَفِي رِوَايَةٍ: «قَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: فَوَاللَّهِ! مَا حَلَفْتُ بِهَا مُنْذُ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْهَا؛ ذَاكِراً وَلَا آثِراً»."]]},{"id":"um72_5","label":"الحديث ٣٥٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«قَالَ سُلَيْمَانُ بْنُ دَاوُدَ عَلَيْهِمَا السَّلَامُ: لَأَطُوفَنَّ اللَّيْلَةَ عَلَى سَبْعِينَ امْرَأَةً؛ تَلِدُ كُلُّ امْرَأَةٍ مِنْهُنَّ غُلَاماً يُقَاتِلُ فِي سَبِيلِ اللَّهِ، فَقِيلَ لَهُ: قُلْ: إِنْ شَاءَ اللَّهُ، فَلَمْ يَقُلْ، فَأَطَافَ بِهِنَّ،"]]},{"id":"um72_6","label":"الحديث ٣٥٤ · المقطع ٢ من ٢","segs":[["matn","فَلَمْ تَلِدْ مِنْهُنَّ إِلَّا امْرَأَةٌ وَاحِدَةٌ نِصْفَ إِنْسَانٍ، قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ قَالَ: إِنْ شَاءَ اللَّهُ؛ لَمْ يَحْنَثْ، وَكَانَ دَرَكاً لِحَاجَتِهِ». قَوْلُهُ: «قِيلَ لَهُ: قُلْ: إِنْ شَاءَ اللَّهُ»؛ يَعْنِي: قَالَ لَهُ المَلَكُ."]]},{"id":"um72_7","label":"الحديث ٣٥٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ حَلَفَ عَلَى يَمِينِ صَبْرٍ يَقْتَطِعُ بِهَا مَالَ امْرِئٍ مُسْلِمٍ هُوَ فِيهَا فَاجِرٌ؛ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ، وَنَزَلَتْ:"]]},{"id":"um72_8","label":"الحديث ٣٥٥ · المقطع ٢ من ٢","segs":[["matn","﴿إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَناً قَلِيلاً﴾ إِلَى آخِرِ الآيَةِ»."]]},{"id":"um72_9","label":"الحديث ٣٥٦ · المقطع ١ من ٢","segs":[["rawi","عَنِ الأَشْعَثِ بْنِ قَيْسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَانَ بَيْنِي وَبَيْنَ رَجُلٍ خُصُومَةٌ فِي بِئْرٍ، فَاخْتَصَمْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: شَاهِدَاكَ أَوْ يَمِينُهُ، قُلْتُ: إِذَنْ يَحْلِفُ وَلَا يُبَالِي!"]]},{"id":"um72_10","label":"الحديث ٣٥٦ · المقطع ٢ من ٢","segs":[["matn","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ حَلَفَ عَلَى يَمِينِ صَبْرٍ يَقْتَطِعُ بِهَا مَالَ امْرِئٍ مُسْلِمٍ، هُوَ فِيهَا فَاجِرٌ؛ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ»."]]},{"id":"um72_11","label":"الحديث ٣٥٧ · المقطع ١ من ٢","segs":[["rawi","عَنْ ثَابِتِ بْنِ الضَّحَّاكِ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّهُ بَايَعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَحْتَ الشَّجَرَةِ، وَأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ حَلَفَ عَلَى يَمِينٍ بِمِلَّةٍ غَيْرِ الإِسْلَامِ كَاذِباً مُتَعَمِّداً؛ فَهُوَ كَمَا قَالَ، وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ؛"]]},{"id":"um72_12","label":"الحديث ٣٥٧ · المقطع ٢ من ٢","segs":[["matn","عُذِّبَ بِهِ يَوْمَ القِيَامَةِ، وَلَيْسَ عَلَى رَجُلٍ نَذْرٌ فِيمَا لَا يَمْلِكُ». وَفِي رِوَايَةٍ: «وَلَعْنُ المُؤْمِنِ كَقَتْلِهِ». وَفِي رِوَايَةٍ: «مَنِ ادَّعَى دَعْوَى كَاذِبَةً لِيَتَكَثَّرَ بِهَا؛ لَمْ يَزِدْهُ اللَّهُ إِلَّا قِلَّةً»."]]}],"group":"كِتَابُ الأَيْمَانِ وَالنُّذُورِ"},{"id":"um73","title":"بَابُ النَّذْرِ","units":[{"id":"um73_1","label":"الحديث ٣٥٨","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«قُلْتُ: يَا رَسُولَ اللَّهِ! إِنِّي كُنْتُ نَذَرْتُ فِي الجَاهِلِيَّةِ أَنْ أَعْتَكِفَ لَيْلَةً - وَفِي رِوَايَةٍ: يَوْماً - فِي المَسْجِدِ الحَرَامِ؟ قَالَ: فَأَوْفِ بِنَذْرِكَ»."]]},{"id":"um73_2","label":"الحديث ٣٥٩","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«أَنَّهُ نَهَى عَنِ النَّذْرِ، وَقَالَ: إِنَّهُ لَا يَأْتِي بِخَيْرٍ، وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنَ البَخِيلِ»."]]},{"id":"um73_3","label":"الحديث ٣٦٠","segs":[["rawi","عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«نَذَرَتْ أُخْتِي أَنْ تَمْشِيَ إِلَى بَيْتِ اللَّهِ الحَرَامِ حَافِيَةً، فَأَمَرَتْنِي أَنْ أَسْتَفْتِيَ لَهَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَفْتَيْتُهُ فَقَالَ: لِتَمْشِ وَلْتَرْكَبْ»."]]},{"id":"um73_4","label":"الحديث ٣٦١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ قَالَ:"],["matn","«اسْتَفْتَى سَعْدُ بْنُ عُبَادَةَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَذْرٍ كَانَ عَلَى أُمِّهِ، تُوُفِّيَتْ قَبْلَ أَنْ تَقْضِيَهُ؛ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَاقْضِهِ عَنْهَا»."]]},{"id":"um73_5","label":"الحديث ٣٦٢","segs":[["rawi","عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«قُلْتُ: يَا رَسُولَ اللَّهِ! إِنَّ مِنْ تَوْبَتِي أَنْ أَنْخَلِعَ مِنْ مَالِي صَدَقَةً إِلَى اللَّهِ وَرَسُولِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمْسِكْ عَلَيْكَ بَعْضَ مَالِكَ؛ فَهُوَ خَيْرٌ لَكَ»."]]}],"group":"كِتَابُ الأَيْمَانِ وَالنُّذُورِ"},{"id":"um74","title":"بَابُ القَضَاءِ","units":[{"id":"um74_1","label":"الحديث ٣٦٣","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ؛ فَهُوَ رَدٌّ». وَفِي لَفْظٍ: «مَنْ عَمِلَ عَمَلاً لَيْسَ عَلَيْهِ أَمْرُنَا؛ فَهُوَ رَدٌّ»."]]},{"id":"um74_2","label":"الحديث ٣٦٤ · المقطع ١ من ٢","segs":[["rawi","وَعَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:"],["matn","«دَخَلَتْ هِنْدٌ بِنْتُ عُتْبَةَ - امْرَأَةُ أَبِي سُفْيَانَ - عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ! إِنَّ أَبَا سُفْيَانَ رَجُلٌ شَحِيحٌ، لَا يُعْطِينِي مِنَ النَّفَقَةِ مَا يَكْفِينِي وَيَكْفِي بَنِيَّ،"]]},{"id":"um74_3","label":"الحديث ٣٦٤ · المقطع ٢ من ٢","segs":[["matn","إِلَّا مَا أَخَذْتُ مِنْ مَالِهِ بِغَيْرِ عِلْمِهِ؛ فَهَلْ عَلَيَّ فِي ذَلِكَ مِنْ جُنَاحٍ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خُذِي مِنْ مَالِهِ بِالمَعْرُوفِ مَا يَكْفِيكِ وَيَكْفِي بَنِيكِ»."]]},{"id":"um74_4","label":"الحديث ٣٦٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَ جَلَبَةَ خَصْمٍ بِبَابِ حُجْرَتِهِ، فَخَرَجَ إِلَيْهِمْ فَقَالَ: أَلَا إِنَّمَا أَنَا بَشَرٌ، وَإِنَّمَا يَأْتِينِي الخَصْمُ، فَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَبْلَغَ مِنْ بَعْضٍ؛ فَأَحْسِبُ أَنَّهُ صَادِقٌ، فَأَقْضِي لَهُ!"]]},{"id":"um74_5","label":"الحديث ٣٦٥ · المقطع ٢ من ٢","segs":[["matn","فَمَنْ قَضَيْتُ لَهُ بِحَقِّ مُسْلِمٍ، فَإِنَّمَا هِيَ قِطْعَةٌ مِنْ نَارٍ، فَلْيَحْمِلْهَا أَوْ يَذَرْهَا»."]]},{"id":"um74_6","label":"الحديث ٣٦٦ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَتَبَ أَبِي - وَكَتَبْتُ لَهُ - إِلَى ابْنِهِ عُبَيْدِ اللَّهِ بْنِ أَبِي بَكْرَةَ - وَهُوَ قَاضٍ بِسِجِسْتَانَ -: أَنْ لَا تَحْكُمَ بَيْنَ اثْنَيْنِ وَأَنْتَ غَضْبَانُ؛ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"]]},{"id":"um74_7","label":"الحديث ٣٦٦ · المقطع ٢ من ٢","segs":[["matn","لَا يَحْكُمْ أَحَدٌ بَيْنَ اثْنَيْنِ وَهُوَ غَضْبَانُ». وَفِي رِوَايَةٍ: «لَا يَقْضِيَنَّ حَكَمٌ بَيْنَ اثْنَيْنِ وَهُوَ غَضْبَانُ»."]]},{"id":"um74_8","label":"الحديث ٣٦٧","segs":[["rawi","عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الكَبَائِرِ؟ - ثَلَاثاً - قُلْنَا: بَلَى يَا رَسُولَ اللَّهِ! قَالَ: الإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الوَالِدَيْنِ، وَكَانَ مُتَّكِئاً فَجَلَسَ، فَقَالَ: أَلَا وَقَوْلُ الزُّورِ، وَشَهَادَةُ الزُّورِ، فَمَا زَالَ يُكَرِّرُهَا حَتَّى قُلْنَا: لَيْتَهُ سَكَتَ»."]]},{"id":"um74_9","label":"الحديث ٣٦٨","segs":[["rawi","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ؛ لَادَّعَى نَاسٌ دِمَاءَ رِجَالٍ وَأَمْوَالَهُمْ، وَلَكِنِ اليَمِينُ عَلَى المُدَّعَى عَلَيْهِ»."]]}],"group":"كِتَابُ الأَيْمَانِ وَالنُّذُورِ"},{"id":"um75","title":"كِتَابُ الأَطْعِمَةِ","units":[{"id":"um75_1","label":"الحديث ٣٦٩ · المقطع ١ من ٣","segs":[["rawi","عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ - وَأَهْوَى النُّعْمَانُ بِإِصْبَعَيْهِ إِلَى أُذُنَيْهِ -: «إِنَّ الحَلَالَ بَيِّنٌ، وَإِنَّ الحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ،"]]},{"id":"um75_2","label":"الحديث ٣٦٩ · المقطع ٢ من ٣","segs":[["matn","وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ، أَلَا وَإِنَّ لِكُلِّ مَلِكٍ حِمىً، أَلَا وَإِنَّ حِمَى اللَّهِ مَحَارِمُهُ، أَلَا وَإِنَّ فِي الجَسَدِ مُضْغَةً، إِذَا صَلَحَتْ صَلَحَ الجَسَدُ كُلُّهُ،"]]},{"id":"um75_3","label":"الحديث ٣٦٩ · المقطع ٣ من ٣","segs":[["matn","وَإِذَا فَسَدَتْ فَسَدَ الجَسَدُ كُلُّهُ، أَلَا وَهِيَ القَلْبُ»."]]},{"id":"um75_4","label":"الحديث ٣٧٠","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«أَنْفَجْنَا أَرْنَباً بِمَرِّ الظَّهْرَانِ، فَسَعَى القَوْمُ فَلَغَبُوا، وَأَدْرَكْتُهَا فَأَخَذْتُهَا، فَأَتَيْتُ بِهَا أَبَا طَلْحَةَ، فَذَبَحَهَا وَبَعَثَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِوَرِكِهَا وَفَخِذَيْهَا، فَقَبِلَهُ»."]]},{"id":"um75_5","label":"الحديث ٣٧١","segs":[["rawi","عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ:"],["matn","«نَحَرْنَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَساً فَأَكَلْنَاهُ». وَفِي رِوَايَةٍ: «وَنَحْنُ بِالمَدِينَةِ»."]]},{"id":"um75_6","label":"الحديث ٣٧٢","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُحُومِ الحُمُرِ الأَهْلِيَّةِ، وَأَذِنَ فِي لُحُومِ الخَيْلِ». وَلِمُسْلِمٍ وَحْدَهُ قَالَ: «أَكَلْنَا زَمَنَ خَيْبَرَ الخَيْلَ وَحُمُرَ الوَحْشِ، وَنَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الحِمَارِ الأَهْلِيِّ»."]]},{"id":"um75_7","label":"الحديث ٣٧٣","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أَصَابَتْنَا مَجَاعَةٌ لَيَالِيَ خَيْبَرَ، فَلَمَّا كَانَ يَوْمُ خَيْبَرَ وَقَعْنَا فِي الحُمُرِ الأَهْلِيَّةِ فَانْتَحَرْنَاهَا، فَلَمَّا غَلَتْ بِهَا القُدُورُ نَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنْ أَكْفِئُوا القُدُورَ، وَلَا تَأْكُلُوا مِنْ لُحُومِ الحُمُرِ شَيْئاً»."]]},{"id":"um75_8","label":"الحديث ٣٧٤","segs":[["rawi","عَنْ أَبِي ثَعْلَبَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لُحُومَ الحُمُرِ الأَهْلِيَّةِ»."]]},{"id":"um75_9","label":"الحديث ٣٧٥ · المقطع ١ من ٣","segs":[["rawi","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«دَخَلْتُ أَنَا وَخَالِدُ بْنُ الوَلِيدِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْتَ مَيْمُونَةَ، فَأُتِيَ بِضَبٍّ مَحْنُوذٍ، فَأَهْوَى إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ، فَقَالَ بَعْضُ النِّسْوَةِ اللَّاتِي فِي بَيْتِ مَيْمُونَةَ:"]]},{"id":"um75_10","label":"الحديث ٣٧٥ · المقطع ٢ من ٣","segs":[["matn","أَخْبِرُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا يُرِيدُ أَنْ يَأْكُلَ؛ فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ، فَقُلْتُ: أَحَرَامٌ هُوَ يَا رَسُولَ اللَّهِ؟ قَالَ: لَا، وَلَكِنَّهُ لَمْ يَكُنْ بِأَرْضِ قَوْمِي، فَأَجِدُنِي أَعَافُهُ،"]]},{"id":"um75_11","label":"الحديث ٣٧٥ · المقطع ٣ من ٣","segs":[["matn","قَالَ خَالِدٌ: فَاجْتَرَرْتُهُ فَأَكَلْتُهُ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْظُرُ»."]]},{"id":"um75_12","label":"الحديث ٣٧٦","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«غَزَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبْعَ غَزَوَاتٍ، نَأْكُلُ الجَرَادَ»."]]},{"id":"um75_13","label":"الحديث ٣٧٧ · المقطع ١ من ٢","segs":[["rawi","عَنْ زَهْدَمِ بْنِ مُضَرِّبٍ الجَرْمِيِّ قَالَ:"],["matn","«كُنَّا عِنْدَ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ فَدَعَا بِمَائِدَتِهِ وَعَلَيْهَا لَحْمُ دَجَاجٍ، فَدَخَلَ رَجُلٌ مِنْ بَنِي تَيْمِ اللَّهِ أَحْمَرُ شَبِيهٌ بِالمَوَالِي؛ فَقَالَ: هَلُمَّ! فَتَلَكَّأَ، فَقَالَ لَهُ: هَلُمَّ!"]]},{"id":"um75_14","label":"الحديث ٣٧٧ · المقطع ٢ من ٢","segs":[["matn","فَإِنِّي قَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ مِنْهُ»."]]},{"id":"um75_15","label":"الحديث ٣٧٨","segs":[["rawi","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا أَكَلَ أَحَدُكُمْ طَعَاماً؛ فَلَا يَمْسَحْ يَدَهُ حَتَّى يَلْعَقَهَا أَوْ يُلْعِقَهَا»."]]}],"group":"كِتَابُ الأَطْعِمَةِ"},{"id":"um76","title":"بَابُ الصَّيْدِ","units":[{"id":"um76_1","label":"الحديث ٣٧٩ · المقطع ١ من ٣","segs":[["rawi","عَنْ أَبِي ثَعْلَبَةَ الخُشَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ! إِنَّا بِأَرْضِ قَوْمٍ أَهْلِ كِتَابٍ، أَفَنَأْكُلُ فِي آنِيَتِهِمْ؟ وَفِي أَرْضٍ أَصِيدُ بِقَوْسِي وَبِكَلْبِي الَّذِي لَيْسَ بِمُعَلَّمٍ وَبِكَلْبِي المُعَلَّمِ، فَمَا يَصْلُحُ لِي؟ قَالَ:"]]},{"id":"um76_2","label":"الحديث ٣٧٩ · المقطع ٢ من ٣","segs":[["matn","أَمَّا مَا ذَكَرْتَ - يَعْنِي: مِنْ آنِيَةِ أَهْلِ الكِتَابِ -: فَإِنْ وَجَدْتُمْ غَيْرَهَا فَلَا تَأْكُلُوا فِيهَا، وَإِنْ لَمْ تَجِدُوا فَاغْسِلُوهَا وَكُلُوا فِيهَا، وَمَا صِدْتَ بِقَوْسِكَ فَذَكَرْتَ اسْمَ اللَّهِ عَلَيْهِ؛ فَكُلْ،"]]},{"id":"um76_3","label":"الحديث ٣٧٩ · المقطع ٣ من ٣","segs":[["matn","وَمَا صِدْتَ بِكَلْبِكَ المُعَلَّمِ فَذَكَرْتَ اسْمَ اللَّهِ عَلَيْهِ؛ فَكُلْ، وَمَا صِدْتَ بِكَلْبِكَ غَيْرِ المُعَلَّمِ فَأَدْرَكْتَ ذَكَاتَهُ؛ فَكُلْ»."]]},{"id":"um76_4","label":"الحديث ٣٨٠ · المقطع ١ من ٥","segs":[["rawi","عَنْ هَمَّامِ بْنِ الحَارِثِ، عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«قُلْتُ: يَا رَسُولَ اللَّهِ! إِنِّي أُرْسِلُ الكِلَابَ المُعَلَّمَةَ فَيُمْسِكْنَ عَلَيَّ وَأَذْكُرُ اسْمَ اللَّهِ؟ فَقَالَ: إِذَا أَرْسَلْتَ كَلْبَكَ المُعَلَّمَ وَذَكَرْتَ اسْمَ اللَّهِ؛ فَكُلْ مَا أَمْسَكَ عَلَيْكَ، قُلْتُ: وَإِنْ قَتَلْنَ؟ قَالَ: وَإِنْ قَتَلْنَ؛"]]},{"id":"um76_5","label":"الحديث ٣٨٠ · المقطع ٢ من ٥","segs":[["matn","مَا لَمْ يَشْرَكْهَا كَلْبٌ لَيْسَ مِنْهَا، قُلْتُ لَهُ: فَإِنِّي أَرْمِي بِالمِعْرَاضِ الصَّيْدَ فَأُصِيبُ؟ فَقَالَ: إِذَا رَمَيْتَ بِالمِعْرَاضِ فَخَزَقَ فَكُلْهُ، وَإِنْ أَصَابَهُ بِعَرْضِهِ فَلَا تَأْكُلْهُ». وَحَدِيثُ الشَّعْبِيِّ عَنْ عَدِيٍّ نَحْوُهُ، وَفِيهِ: «إِلَّا أَنْ يَأْكُلَ الكَلْبُ،"]]},{"id":"um76_6","label":"الحديث ٣٨٠ · المقطع ٣ من ٥","segs":[["matn","فَإِنْ أَكَلَ فَلَا تَأْكُلْ؛ فَإِنِّي أَخَافُ أَنْ يَكُونَ إِنَّمَا أَمْسَكَ عَلَى نَفْسِهِ، وَإِنْ خَالَطَهَا كِلَابٌ مِنْ غَيْرِهَا فَلَا تَأْكُلْ، فَإِنَّمَا سَمَّيْتَ عَلَى كَلْبِكَ، وَلَمْ تُسَمِّ عَلَى غَيْرِهِ». وَفِيهِ:"]]},{"id":"um76_7","label":"الحديث ٣٨٠ · المقطع ٤ من ٥","segs":[["matn","«إِذَا أَرْسَلْتَ كَلْبَكَ المُكَلَّبَ فَاذْكُرِ اسْمَ اللَّهِ عَلَيْهِ، فَإِنْ أَمْسَكَ عَلَيْكَ فَأَدْرَكْتَهُ حَيّاً فَاذْبَحْهُ، وَإِنْ أَدْرَكْتَهُ قَدْ قَتَلَ وَلَمْ يَأْكُلْ مِنْهُ فَكُلْهُ؛ فَإِنَّ أَخْذَ الكَلْبِ ذَكَاتُهُ». وَفِيهِ أَيْضاً: «إِذَا رَمَيْتَ بِسَهْمِكَ؛ فَاذْكُرِ اسْمَ اللَّهِ عَلَيْهِ»."]]},{"id":"um76_8","label":"الحديث ٣٨٠ · المقطع ٥ من ٥","segs":[["matn","وَفِيهِ: «فَإِنْ غَابَ عَنْكَ يَوْماً أَوْ يَوْمَيْنِ - وَفِي رِوَايَةٍ: اليَوْمَيْنِ وَالثَّلَاثَةَ -، فَلَمْ تَجِدْ فِيهِ إِلَّا أَثَرَ سَهْمِكَ؛ فَكُلْ إِنْ شِئْتَ، فَإِنْ وَجَدْتَهُ غَرِيقاً فِي المَاءِ فَلَا تَأْكُلْ؛ فَإِنَّكَ لَا تَدْرِي: المَاءُ قَتَلَهُ، أَوْ سَهْمُكَ؟»."]]},{"id":"um76_9","label":"الحديث ٣٨١","segs":[["rawi","عَنْ سَالِمٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"],["matn","«مَنِ اقْتَنَى كَلْباً إِلَّا كَلْبَ صَيْدٍ أَوْ مَاشِيَةٍ؛ فَإِنَّهُ يَنْقُصُ مِنْ أَجْرِهِ كُلَّ يَوْمٍ قِيرَاطَانِ. قَالَ سَالِمٌ: وَكَانَ أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: أَوْ كَلْبَ حَرْثٍ - وَكَانَ صَاحِبَ حَرْثٍ -»."]]},{"id":"um76_10","label":"الحديث ٣٨٢ · المقطع ١ من ٤","segs":[["rawi","عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذِي الحُلَيْفَةِ مِنْ تِهَامَةَ، فَأَصَابَ النَّاسَ جُوعٌ، فَأَصَابُوا إِبِلاً وَغَنَماً، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أُخْرَيَاتِ القَوْمِ، فَعَجَّلُوا وَذَبَحُوا وَنَصَبُوا القُدُورَ،"]]},{"id":"um76_11","label":"الحديث ٣٨٢ · المقطع ٢ من ٤","segs":[["matn","فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالقُدُورِ فَأُكْفِئَتْ، ثُمَّ قَسَمَ فَعَدَلَ عَشَرَةً مِنَ الغَنَمِ بِبَعِيرٍ، فَنَدَّ مِنْهَا بَعِيرٌ، فَطَلَبُوهُ فَأَعْيَاهُمْ، وَكَانَ فِي القَوْمِ خَيْلٌ يَسِيرَةٌ، فَأَهْوَى رَجُلٌ مِنْهُمْ بِسَهْمٍ، فَحَبَسَهُ اللَّهُ، فَقَالَ:"]]},{"id":"um76_12","label":"الحديث ٣٨٢ · المقطع ٣ من ٤","segs":[["matn","إِنَّ لِهَذِهِ البَهَائِمِ أَوَابِدَ كَأَوَابِدِ الوَحْشِ، فَمَا غَلَبَكُمْ مِنْهَا فَاصْنَعُوا بِهِ هَكَذَا، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ! إِنَّا لَاقُوا العَدُوِّ غَداً، وَلَيْسَتْ مَعَنَا مُدىً، أَفَنَذْبَحُ بِالقَصَبِ؟ قَالَ: مَا أَنْهَرَ الدَّمَ، وَذُكِرَ اسْمُ اللَّهِ عَلَيْهِ فَكُلُوهُ؛"]]},{"id":"um76_13","label":"الحديث ٣٨٢ · المقطع ٤ من ٤","segs":[["matn","لَيْسَ السِّنَّ وَالظُّفُرَ، وَسَأُحَدِّثُكُمْ عَنْ ذَلِكَ؛ أَمَّا السِّنُّ: فَعَظْمٌ، وَأَمَّا الظُّفُرُ: فَمُدَى الحَبَشَةِ»."]]}],"group":"كِتَابُ الأَطْعِمَةِ"},{"id":"um77","title":"بَابُ الأَضَاحِي","units":[{"id":"um77_1","label":"الحديث ٣٨٣","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«ضَحَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكَبْشَيْنِ أَمْلَحَيْنِ أَقْرَنَيْنِ؛ ذَبَحَهُمَا بِيَدِهِ، وَسَمَّى وَكَبَّرَ، وَوَضَعَ رِجْلَهُ عَلَى صِفَاحِهِمَا»."]]}],"group":"كِتَابُ الأَطْعِمَةِ"},{"id":"um78","title":"كِتَابُ الأَشْرِبَةِ","units":[{"id":"um78_1","label":"الحديث ٣٨٤ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ عَلَى مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّا بَعْدُ، أَيُّهَا النَّاسُ! إِنَّهُ نَزَلَ تَحْرِيمُ الخَمْرِ وَهِيَ مِنْ خَمْسَةٍ: مِنَ العِنَبِ، وَالتَّمْرِ، وَالعَسَلِ، وَالحِنْطَةِ، وَالشَّعِيرِ، وَالخَمْرُ: مَا خَامَرَ العَقْلَ،"]]},{"id":"um78_2","label":"الحديث ٣٨٤ · المقطع ٢ من ٢","segs":[["matn","ثَلَاثٌ وَدِدْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ عَهِدَ إِلَيْنَا فِيهِنَّ عَهْداً نَنْتَهِي إِلَيْهِ: الجَدُّ، وَالكَلَالَةُ، وَأَبْوَابٌ مِنْ أَبْوَابِ الرِّبَا»."]]},{"id":"um78_3","label":"الحديث ٣٨٥","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«أَنَّهُ سُئِلَ عَنِ البِتْعِ؟ فَقَالَ: كُلُّ شَرَابٍ أَسْكَرَ؛ فَهُوَ حَرَامٌ»."]]},{"id":"um78_4","label":"الحديث ٣٨٦","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«بَلَغَ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ فُلَاناً بَاعَ خَمْراً، فَقَالَ: قَاتَلَ اللَّهُ فُلَاناً! أَلَمْ يَعْلَمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَاتَلَ اللَّهُ اليَهُودَ؛ حُرِّمَتْ عَلَيْهِمُ الشُّحُومُ، فَجَمَلُوهَا فَبَاعُوهَا»."]]}],"group":"كِتَابُ الأَشْرِبَةِ"},{"id":"um79","title":"كِتَابُ اللِّبَاسِ","units":[{"id":"um79_1","label":"الحديث ٣٨٧","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَا تَلْبَسُوا الحَرِيرَ؛ فَإِنَّهُ مَنْ لَبِسَهُ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الآخِرَةِ»."]]},{"id":"um79_2","label":"الحديث ٣٨٨","segs":[["rawi","عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"],["matn","«لَا تَلْبَسُوا الحَرِيرَ وَلَا الدِّيبَاجَ، وَلَا تَشْرَبُوا فِي آنِيَةِ الذَّهَبِ وَالفِضَّةِ، وَلَا تَأْكُلُوا فِي صِحَافِهَا؛ فَإِنَّهَا لَهُمْ فِي الدُّنْيَا، وَلَكُمْ فِي الآخِرَةِ»."]]},{"id":"um79_3","label":"الحديث ٣٨٩","segs":[["rawi","عَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«مَا رَأَيْتُ مِنْ ذِي لِمَّةٍ فِي حُلَّةٍ حَمْرَاءَ أَحْسَنَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ لَهُ شَعَرٌ يَضْرِبُ مَنْكِبَيْهِ، بَعِيدُ مَا بَيْنَ المَنْكِبَيْنِ، لَيْسَ بِالقَصِيرِ وَلَا بِالطَّوِيلِ»."]]},{"id":"um79_4","label":"الحديث ٣٩٠ · المقطع ١ من ٢","segs":[["rawi","عَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ، وَنَهَانَا عَنْ سَبْعٍ: أَمَرَنَا بِعِيَادَةِ المَرِيضِ، وَاتِّبَاعِ الجِنَازَةِ، وَتَشْمِيتِ العَاطِسِ، وَإِبْرَارِ القَسَمِ - أَوِ المُقْسِمِ -، وَنَصْرِ المَظْلُومِ، وَإِجَابَةِ الدَّاعِي، وَإِفْشَاءِ السَّلَامِ،"]]},{"id":"um79_5","label":"الحديث ٣٩٠ · المقطع ٢ من ٢","segs":[["matn","وَنَهَانَا عَنْ خَوَاتِيمِ - أَوْ عَنْ تَخَتُّمِ - الذَّهَبِ، وَعَنْ شُرْبٍ بِالفِضَّةِ، وَعَنِ المَيَاثِرِ، وَعَنِ القَسِّيِّ، وَعَنْ لُبْسِ الحَرِيرِ وَالإِسْتَبْرَقِ وَالدِّيبَاجِ»."]]},{"id":"um79_6","label":"الحديث ٣٩١ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اصْطَنَعَ خَاتَماً مِنْ ذَهَبٍ، فَكَانَ يَجْعَلُ فَصَّهُ فِي بَاطِنِ كَفِّهِ إِذَا لَبِسَهُ، فَصَنَعَ النَّاسُ، ثُمَّ إِنَّهُ جَلَسَ فَنَزَعَهُ، وَقَالَ: إِنِّي كُنْتُ أَلْبَسُ هَذَا الخَاتَمَ، وَأَجْعَلُ فَصَّهُ مِنْ دَاخِلٍ،"]]},{"id":"um79_7","label":"الحديث ٣٩١ · المقطع ٢ من ٢","segs":[["matn","فَرَمَى بِهِ، ثُمَّ قَالَ: وَاللَّهِ لَا أَلْبَسُهُ أَبَداً! فَنَبَذَ النَّاسُ خَوَاتِيمَهُمْ». وَفِي لَفْظٍ: «جَعَلَهُ فِي يَدِهِ اليُمْنَى»."]]},{"id":"um79_8","label":"الحديث ٣٩٢ · المقطع ١ من ٢","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لَبُوسِ الحَرِيرِ إِلَّا هَكَذَا؛ وَرَفَعَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِصْبَعَيْهِ السَّبَّابَةَ وَالوُسْطَى». وَلِمُسْلِمٍ:"]]},{"id":"um79_9","label":"الحديث ٣٩٢ · المقطع ٢ من ٢","segs":[["matn","«نَهَى نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ لُبْسِ الحَرِيرِ إِلَّا مَوْضِعَ إِصْبَعَيْنِ، أَوْ ثَلَاثٍ، أَوْ أَرْبَعٍ»."]]}],"group":"كِتَابُ اللِّبَاسِ"},{"id":"um80","title":"كِتَابُ الجِهَادِ","units":[{"id":"um80_1","label":"الحديث ٣٩٣ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَيَّامِهِ الَّتِي لَقِيَ فِيهَا العَدُوَّ؛ انْتَظَرَ حَتَّى إِذَا مَالَتِ الشَّمْسُ قَامَ فِيهِمْ فَقَالَ: يَا أَيُّهَا النَّاسُ! لَا تَتَمَنَّوْا لِقَاءَ العَدُوِّ، وَاسْأَلُوا اللَّهَ العَافِيَةَ، فَإِذَا لَقِيتُمُوهُمْ فَاصْبِرُوا،"]]},{"id":"um80_2","label":"الحديث ٣٩٣ · المقطع ٢ من ٢","segs":[["matn","وَاعْلَمُوا أَنَّ الجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ، ثُمَّ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُمَّ مُنْزِلَ الكِتَابِ، وَمُجْرِيَ السَّحَابِ، وَهَازِمَ الأَحْزَابِ؛ اهْزِمْهُمْ وَانْصُرْنَا عَلَيْهِمْ»."]]},{"id":"um80_3","label":"الحديث ٣٩٤","segs":[["rawi","عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«رِبَاطُ يَوْمٍ فِي سَبِيلِ اللَّهِ؛ خَيْرٌ مِنَ الدُّنْيَا وَمَا عَلَيْهَا، وَمَوْضِعُ سَوْطِ أَحَدِكُمْ مِنَ الجَنَّةِ؛ خَيْرٌ مِنَ الدُّنْيَا وَمَا عَلَيْهَا، وَالرَّوْحَةُ يَرُوحُهَا العَبْدُ فِي سَبِيلِ اللَّهِ أَوِ الغَدْوَةُ؛ خَيْرٌ مِنَ الدُّنْيَا وَمَا عَلَيْهَا»."]]},{"id":"um80_4","label":"الحديث ٣٩٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«انْتَدَبَ اللَّهُ - وَلِمُسْلِمٍ: تَضَمَّنَ اللَّهُ - لِمَنْ خَرَجَ فِي سَبِيلِهِ، لَا يُخْرِجُهُ إِلَّا جِهَادٌ فِي سَبِيلِي، وَإِيمَانٌ بِي، وَتَصْدِيقٌ بِرُسُلِي فَهُوَ عَلَيَّ ضَامِنٌ: أَنْ أُدْخِلَهُ الجَنَّةَ، أَوْ أُرْجِعَهُ إِلَى مَسْكَنِهِ الَّذِي خَرَجَ مِنْهُ،"]]},{"id":"um80_5","label":"الحديث ٣٩٥ · المقطع ٢ من ٢","segs":[["matn","نَائِلاً مَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ». وَلِمُسْلِمٍ: «مَثَلُ المُجَاهِدِ فِي سَبِيلِ اللَّهِ - وَاللَّهُ أَعْلَمُ بِمَنْ يُجَاهِدُ فِي سَبِيلِهِ - كَمَثَلِ الصَّائِمِ القَائِمِ، وَتَوَكَّلَ اللَّهُ لِلْمُجَاهِدِ فِي سَبِيلِهِ بِأَنْ تَوَفَّاهُ: أَنْ يُدْخِلَهُ الجَنَّةَ، أَوْ يَرْجِعَهُ سَالِماً مَعَ أَجْرٍ أَوْ غَنِيمَةٍ»."]]},{"id":"um80_6","label":"الحديث ٣٩٦","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«مَا مِنْ مَكْلُومٍ يُكْلَمُ فِي سَبِيلِ اللَّهِ؛ إِلَّا جَاءَ يَوْمَ القِيَامَةِ وَكَلْمُهُ يَدْمَى؛ اللَّوْنُ لَوْنُ الدَّمِ، وَالرِّيحُ رِيحُ مِسْكٍ»."]]},{"id":"um80_7","label":"الحديث ٣٩٧","segs":[["rawi","عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «غَدْوَةٌ فِي سَبِيلِ اللَّهِ، أَوْ رَوْحَةٌ؛ خَيْرٌ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ وَغَرَبَتْ» أَخْرَجَهُ مُسْلِمٌ."]]},{"id":"um80_8","label":"الحديث ٣٩٨","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «غَدْوَةٌ فِي سَبِيلِ اللَّهِ، أَوْ رَوْحَةٌ؛ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا»"],["takh","أَخْرَجَهُ البُخَارِيُّ."]]},{"id":"um80_9","label":"الحديث ٣٩٩","segs":[["rawi","عَنْ أَبِي قَتَادَةَ الأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى حُنَيْنٍ - وَذَكَرَ قِصَّةً - فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ قَتَلَ قَتِيلاً لَهُ عَلَيْهِ بَيِّنَةٌ؛ فَلَهُ سَلَبُهُ - قَالَهَا ثَلَاثاً -»."]]},{"id":"um80_10","label":"الحديث ٤٠٠ · المقطع ١ من ٢","segs":[["rawi","عَنْ سَلَمَةَ ابْنِ الأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَيْنٌ مِنَ المُشْرِكِينَ - وَهُوَ فِي سَفَرٍ -، فَجَلَسَ عِنْدَ أَصْحَابِهِ يَتَحَدَّثُ، ثُمَّ انْفَتَلَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اطْلُبُوهُ وَاقْتُلُوهُ، فَقَتَلْتُهُ، فَنَفَّلَنِي سَلَبَهُ». وَفِي رِوَايَةٍ: «فَقَالَ:"]]},{"id":"um80_11","label":"الحديث ٤٠٠ · المقطع ٢ من ٢","segs":[["matn","مَنْ قَتَلَ الرَّجُلَ؟ فَقَالُوا: سَلَمَةُ ابْنُ الأَكْوَعِ؛ قَالَ: لَهُ سَلَبُهُ أَجْمَعُ»."]]},{"id":"um80_12","label":"الحديث ٤٠١","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً إِلَى نَجْدٍ فَخَرَجْتُ فِيهَا، فَأَصَبْنَا إِبِلاً وَغَنَماً، فَبَلَغَتْ سُهْمَانُنَا اثْنَيْ عَشَرَ بَعِيراً، وَنَفَّلَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعِيراً بَعِيراً»."]]},{"id":"um80_13","label":"الحديث ٤٠٢","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«إِذَا جَمَعَ اللَّهُ الأَوَّلِينَ وَالآخِرِينَ: يُرْفَعُ لِكُلِّ غَادِرٍ لِوَاءٌ؛ فَيُقَالُ: هَذِهِ غَدْرَةُ فُلَانِ بْنِ فُلَانٍ»."]]},{"id":"um80_14","label":"الحديث ٤٠٣","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ امْرَأَةً وُجِدَتْ فِي بَعْضِ مَغَازِي النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَقْتُولَةً؛ فَأَنْكَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَتْلَ النِّسَاءِ وَالصِّبْيَانِ»."]]},{"id":"um80_15","label":"الحديث ٤٠٤","segs":[["rawi","عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ وَالزُّبَيْرَ بْنَ العَوَّامِ رَضِيَ اللَّهُ عَنْهُمَا شَكَيَا القَمْلَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ لَهُمَا؛ فَرَخَّصَ لَهُمَا فِي قَمِيصِ الحَرِيرِ، وَرَأَيْتُهُ عَلَيْهِمَا»."]]},{"id":"um80_16","label":"الحديث ٤٠٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«كَانَتْ أَمْوَالُ بَنِي النَّضِيرِ مِمَّا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِمَّا لَمْ يُوجِفِ المُسْلِمُونَ عَلَيْهِ بِخَيْلٍ وَلَا رِكَابٍ، وَكَانَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَالِصاً،"]]},{"id":"um80_17","label":"الحديث ٤٠٥ · المقطع ٢ من ٢","segs":[["matn","فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْزِلُ نَفَقَةَ أَهْلِهِ سَنَةً، ثُمَّ يَجْعَلُ مَا بَقِيَ فِي الكُرَاعِ وَالسِّلَاحِ عُدَّةً فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ»."]]},{"id":"um80_18","label":"الحديث ٤٠٦ · المقطع ١ من ٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«أَجْرَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا ضُمِّرَ مِنَ الخَيْلِ: مِنَ الحَفْيَاءِ إِلَى ثَنِيَّةِ الوَدَاعِ، وَأَجْرَى مَا لَمْ يُضَمَّرْ: مِنَ الثَّنِيَّةِ إِلَى مَسْجِدِ بَنِي زُرَيْقٍ. قَالَ ابْنُ عُمَرَ: وَكُنْتُ فِيمَنْ أَجْرَى. قَالَ سُفْيَانُ:"]]},{"id":"um80_19","label":"الحديث ٤٠٦ · المقطع ٢ من ٢","segs":[["matn","مِنَ الحَفْيَاءِ إِلَى ثَنِيَّةِ الوَدَاعِ: خَمْسَةُ أَمْيَالٍ، أَوْ سِتَّةٌ، وَمِنْ ثَنِيَّةِ الوَدَاعِ إِلَى مَسْجِدِ بَنِي زُرَيْقٍ: مِيلٌ»."]]},{"id":"um80_20","label":"الحديث ٤٠٧","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«عُرِضْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ وَأَنَا ابْنُ أَرْبَعَ عَشْرَةَ سَنَةً فَلَمْ يُجِزْنِي، وَعُرِضْتُ عَلَيْهِ يَوْمَ الخَنْدَقِ وَأَنَا ابْنُ خَمْسَ عَشْرَةَ فَأَجَازَنِي»."]]},{"id":"um80_21","label":"الحديث ٤٠٨","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَسَمَ فِي النَّفَلِ: لِلْفَرَسِ سَهْمَيْنِ، وَلِلرَّجُلِ سَهْماً»."]]},{"id":"um80_22","label":"الحديث ٤٠٩","segs":[["rawi","وَعَنْهُ رَضِيَ اللَّهُ عَنْهُ:"],["matn","«أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُنَفِّلُ بَعْضَ مَنْ يَبْعَثُ مِنَ السَّرَايَا لِأَنْفُسِهِمْ خَاصَّةً، سِوَى قَسْمِ عَامَّةِ الجَيْشِ»."]]},{"id":"um80_23","label":"الحديث ٤١٠","segs":[["rawi","عَنْ أَبِي مُوسَى عَبْدِ اللَّهِ بْنِ قَيْسٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ؛ فَلَيْسَ مِنَّا»."]]},{"id":"um80_24","label":"الحديث ٤١١","segs":[["rawi","عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ:"],["matn","«سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ يُقَاتِلُ شَجَاعَةً، وَيُقَاتِلُ حَمِيَّةً، وَيُقَاتِلُ رِيَاءً؛ أَيُّ ذَلِكَ فِي سَبِيلِ اللَّهِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ العُلْيَا؛ فَهُوَ فِي سَبِيلِ اللَّهِ»."]]}],"group":"كِتَابُ الجِهَادِ"},{"id":"um81","title":"كِتَابُ العِتْقِ","units":[{"id":"um81_1","label":"الحديث ٤١٢","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ أَعْتَقَ شِرْكاً لَهُ فِي عَبْدٍ فَكَانَ لَهُ مَالٌ يَبْلُغُ ثَمَنَ العَبْدِ؛ قُوِّمَ عَلَيْهِ قِيمَةَ عَدْلٍ، فَأَعْطَى شُرَكَاءَهُ حِصَصَهُمْ، وَعَتَقَ عَلَيْهِ العَبْدُ، وَإِلَّا فَقَدْ عَتَقَ مِنْهُ مَا عَتَقَ»."]]},{"id":"um81_2","label":"الحديث ٤١٣","segs":[["rawi","عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«مَنْ أَعْتَقَ شِقْصاً لَهُ مِنْ مَمْلُوكٍ؛ فَعَلَيْهِ خَلَاصُهُ فِي مَالِهِ، فَإِنْ لَمْ يَكُنْ لَهُ مَالٌ قُوِّمَ المَمْلُوكُ قِيمَةَ عَدْلٍ، ثُمَّ اسْتُسْعِيَ غَيْرَ مَشْقُوقٍ عَلَيْهِ»."]]},{"id":"um81_3","label":"الحديث ٤١٤","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:"],["matn","«دَبَّرَ رَجُلٌ مِنَ الأَنْصَارِ غُلَاماً لَهُ - وَفِي لَفْظٍ: بَلَغَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَجُلاً مِنْ أَصْحَابِهِ أَعْتَقَ غُلَاماً لَهُ عَنْ دُبُرٍ - لَمْ يَكُنْ لَهُ مَالٌ غَيْرَهُ؛ فَبَاعَهُ بِثَمَانِ مِئَةِ دِرْهَمٍ، ثُمَّ أَرْسَلَ ثَمَنَهُ إِلَيْهِ»."]]}],"group":"كِتَابُ العِتْقِ"}]};
